INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (1, 'tt0111161', 278, 'The Shawshank Redemption', 1994, '/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', '{18,80}', 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', '[{"name": "Tim Robbins", "character": "Andy Dufresne"}, {"name": "Morgan Freeman", "character": "Ellis Boyd ''Red'' Redding"}, {"name": "Bob Gunton", "character": "Warden Norton"}, {"name": "William Sadler", "character": "Heywood"}, {"name": "Clancy Brown", "character": "Captain Byron T. Hadley"}]', 'Frank Darabont', NULL, '2026-07-13 21:28:06.282417');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (3, 'tt0468569', 155, 'The Dark Knight', 2008, '/qJ2tW6WMUDux911r6m7haRef0WH.jpg', '{28,80,53}', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.', '[{"name": "Christian Bale", "character": "Bruce Wayne"}, {"name": "Heath Ledger", "character": "Joker"}, {"name": "Aaron Eckhart", "character": "Harvey Dent"}, {"name": "Michael Caine", "character": "Alfred"}, {"name": "Maggie Gyllenhaal", "character": "Rachel"}]', 'Christopher Nolan', NULL, '2026-07-13 21:28:07.572823');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (4, 'tt0167260', 122, 'The Lord of the Rings: The Return of the King', 2003, '/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', '{12,14,28}', 'As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​', '[{"name": "Elijah Wood", "character": "Frodo"}, {"name": "Ian McKellen", "character": "Gandalf"}, {"name": "Viggo Mortensen", "character": "Aragorn"}, {"name": "Sean Astin", "character": "Sam"}, {"name": "Andy Serkis", "character": "Gollum / Smeagol"}]', 'Peter Jackson', NULL, '2026-07-13 21:28:08.183737');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (5, 'tt0108052', 424, 'Schindler''s List', 1993, '/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', '{18,36,10752}', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', '[{"name": "Liam Neeson", "character": "Oskar Schindler"}, {"name": "Ben Kingsley", "character": "Itzhak Stern"}, {"name": "Ralph Fiennes", "character": "Amon Goeth"}, {"name": "Caroline Goodall", "character": "Emilie Schindler"}, {"name": "Jonathan Sagall", "character": "Poldek Pfefferberg"}]', 'Steven Spielberg', NULL, '2026-07-13 21:28:08.804704');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (8, 'tt0120737', 120, 'The Lord of the Rings: The Fellowship of the Ring', 2001, '/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', '{12,14,28}', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', '[{"name": "Elijah Wood", "character": "Frodo"}, {"name": "Ian McKellen", "character": "Gandalf"}, {"name": "Viggo Mortensen", "character": "Aragorn"}, {"name": "Sean Astin", "character": "Sam"}, {"name": "Ian Holm", "character": "Bilbo"}]', 'Peter Jackson', NULL, '2026-07-13 21:28:10.671072');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (9, 'tt1375666', 27205, 'Inception', 2010, '/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', '{28,878,12}', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.', '[{"name": "Leonardo DiCaprio", "character": "Dom Cobb"}, {"name": "Joseph Gordon-Levitt", "character": "Arthur"}, {"name": "Ken Watanabe", "character": "Saito"}, {"name": "Tom Hardy", "character": "Eames"}, {"name": "Elliot Page", "character": "Ariadne"}]', 'Christopher Nolan', NULL, '2026-07-13 21:28:11.241185');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (10, 'tt0137523', 550, 'Fight Club', 1999, '/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg', '{18,53}', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.', '[{"name": "Edward Norton", "character": "Narrator"}, {"name": "Brad Pitt", "character": "Tyler Durden"}, {"name": "Helena Bonham Carter", "character": "Marla Singer"}, {"name": "Meat Loaf", "character": "Robert Paulson"}, {"name": "Jared Leto", "character": "Angel Face"}]', 'David Fincher', NULL, '2026-07-13 21:28:11.839627');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (11, 'tt0109830', 13, 'Forrest Gump', 1994, '/Cw4hIUIAmSYfK9QfaUW5igp9La.jpg', '{35,18,10749}', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.', '[{"name": "Tom Hanks", "character": "Forrest Gump"}, {"name": "Robin Wright", "character": "Jenny Curran"}, {"name": "Gary Sinise", "character": "Lieutenant Dan Taylor"}, {"name": "Sally Field", "character": "Mrs. Gump"}, {"name": "Mykelti Williamson", "character": "Bubba Blue"}]', 'Robert Zemeckis', NULL, '2026-07-13 21:28:12.394568');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (12, 'tt0110912', 680, 'Pulp Fiction', 1994, '/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', '{53,80,35}', 'A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.', '[{"name": "John Travolta", "character": "Vincent Vega"}, {"name": "Samuel L. Jackson", "character": "Jules Winnfield"}, {"name": "Uma Thurman", "character": "Mia Wallace"}, {"name": "Bruce Willis", "character": "Butch Coolidge"}, {"name": "Ving Rhames", "character": "Marsellus Wallace"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:28:12.952855');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (13, 'tt0167261', 121, 'The Lord of the Rings: The Two Towers', 2002, '/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', '{12,14,28}', 'Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers--Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor. Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.', '[{"name": "Elijah Wood", "character": "Frodo"}, {"name": "Ian McKellen", "character": "Gandalf"}, {"name": "Viggo Mortensen", "character": "Aragorn"}, {"name": "Sean Astin", "character": "Sam"}, {"name": "Andy Serkis", "character": "Gollum"}]', 'Peter Jackson', NULL, '2026-07-13 21:28:13.528067');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (15, 'tt28089784', 1155818, 'Satluj', 2026, '/cxFo7L82dW3Vg8x0280BVPpLNXf.jpg', '{80,18,36}', 'Triggered by the search for his missing aunt, human rights activist Jaswant Singh Khalra takes on a broken system in a courageous fight to uncover the conspiracy behind thousands of disappearances and extrajudicial killings during the nadir of Punjab’s period of insurgency.', '[{"name": "Diljit Dosanjh", "character": "Jaswant Singh Khalra"}, {"name": "Arjun Rampal", "character": "Samudra Singh"}, {"name": "Suvinder Vicky", "character": "SSP Surjit Singh Sugga"}, {"name": "Geetika Vidya", "character": "Pammi (Paramjit Kaur)"}, {"name": "Kanwaljit Singh", "character": "DGP Inderpal Singh Bitta"}]', 'Honey Trehan', NULL, '2026-07-13 21:28:14.720118');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (16, 'tt0816692', 157336, 'Interstellar', 2014, '/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', '{12,18,878}', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.', '[{"name": "Matthew McConaughey", "character": "Cooper"}, {"name": "Anne Hathaway", "character": "Brand"}, {"name": "Michael Caine", "character": "Professor Brand"}, {"name": "Jessica Chastain", "character": "Murph"}, {"name": "Casey Affleck", "character": "Tom"}]', 'Christopher Nolan', NULL, '2026-07-13 21:28:15.372245');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (17, 'tt0133093', 603, 'The Matrix', 1999, '/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', '{28,878}', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', '[{"name": "Keanu Reeves", "character": "Neo"}, {"name": "Laurence Fishburne", "character": "Morpheus"}, {"name": "Carrie-Anne Moss", "character": "Trinity"}, {"name": "Hugo Weaving", "character": "Agent Smith"}, {"name": "Gloria Foster", "character": "Oracle"}]', 'Lana Wachowski', NULL, '2026-07-13 21:28:15.970188');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (18, 'tt0080684', 1891, 'The Empire Strikes Back', 1980, '/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', '{12,28,878}', 'The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.', '[{"name": "Mark Hamill", "character": "Luke Skywalker"}, {"name": "Harrison Ford", "character": "Han Solo"}, {"name": "Carrie Fisher", "character": "Princess Leia"}, {"name": "Billy Dee Williams", "character": "Lando Calrissian"}, {"name": "Anthony Daniels", "character": "C-3PO"}]', 'Irvin Kershner', NULL, '2026-07-13 21:28:16.559112');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (19, 'tt0099685', 769, 'GoodFellas', 1990, '/9OkCLM73MIU2CrKZbqiT8Ln1wY2.jpg', '{18,80}', 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age and climbs the ranks of a Mafia family under the guidance of Jimmy Conway.', '[{"name": "Robert De Niro", "character": "James Conway"}, {"name": "Ray Liotta", "character": "Henry Hill"}, {"name": "Joe Pesci", "character": "Tommy DeVito"}, {"name": "Lorraine Bracco", "character": "Karen Hill"}, {"name": "Paul Sorvino", "character": "Paul Cicero"}]', 'Martin Scorsese', NULL, '2026-07-13 21:28:17.112916');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (20, 'tt0114369', 807, 'Se7en', 1995, '/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', '{80,9648,53}', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.', '[{"name": "Morgan Freeman", "character": "Somerset"}, {"name": "Brad Pitt", "character": "Mills"}, {"name": "Gwyneth Paltrow", "character": "Tracy"}, {"name": "John Cassini", "character": "Officer Davis"}, {"name": "Peter Crombie", "character": "Dr. O''Neill"}]', 'David Fincher', NULL, '2026-07-13 21:28:17.677175');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (21, 'tt0102926', 274, 'The Silence of the Lambs', 1991, '/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg', '{80,53,18}', 'Clarice Starling is a top student at the FBI''s training academy.  Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath, serving life behind bars for various acts of murder and cannibalism.  Crawford believes that Lecter may have insight into a case and that Starling, as an attractive young woman, may be just the bait to draw him out.', '[{"name": "Jodie Foster", "character": "Clarice Starling"}, {"name": "Anthony Hopkins", "character": "Dr. Hannibal Lecter"}, {"name": "Scott Glenn", "character": "Jack Crawford"}, {"name": "Ted Levine", "character": "Jame Gumb"}, {"name": "Anthony Heald", "character": "Dr. Frederick Chilton"}]', 'Jonathan Demme', NULL, '2026-07-13 21:28:18.300759');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (22, 'tt0120815', 857, 'Saving Private Ryan', 1998, '/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg', '{10752,18,36}', 'As U.S. troops storm the beaches of Normandy, three brothers lie dead on the battlefield, with a fourth trapped behind enemy lines. Ranger captain John Miller and seven men are tasked with penetrating German-held territory and bringing the boy home.', '[{"name": "Tom Hanks", "character": "Captain Miller"}, {"name": "Tom Sizemore", "character": "Sergeant Horvath"}, {"name": "Edward Burns", "character": "Private Reiben"}, {"name": "Barry Pepper", "character": "Private Jackson"}, {"name": "Adam Goldberg", "character": "Private Mellish"}]', 'Steven Spielberg', NULL, '2026-07-13 21:28:18.874129');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (24, 'tt0120689', 497, 'The Green Mile', 1999, '/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg', '{14,18,80}', 'A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments. When the cell block''s head guard, Paul Edgecomb, recognizes Coffey''s miraculous gift, he tries desperately to help stave off the condemned man''s execution.', '[{"name": "Tom Hanks", "character": "Paul Edgecomb"}, {"name": "David Morse", "character": "Brutus ''Brutal'' Howell"}, {"name": "Bonnie Hunt", "character": "Jan Edgecomb"}, {"name": "Michael Clarke Duncan", "character": "John Coffey"}, {"name": "James Cromwell", "character": "Warden Hal Moores"}]', 'Frank Darabont', NULL, '2026-07-13 21:28:20.007222');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (25, 'tt0103064', 280, 'Terminator 2: Judgment Day', 1991, '/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg', '{28,53,878}', 'Ten years after the events of the original, a reprogrammed T-800 is sent back in time to protect young John Connor from the shape-shifting T-1000. Together with his mother Sarah, he fights to stop Skynet from triggering a nuclear apocalypse.', '[{"name": "Arnold Schwarzenegger", "character": "The Terminator"}, {"name": "Linda Hamilton", "character": "Sarah Connor"}, {"name": "Edward Furlong", "character": "John Connor"}, {"name": "Robert Patrick", "character": "T-1000"}, {"name": "Earl Boen", "character": "Dr. Silberman"}]', 'James Cameron', NULL, '2026-07-13 21:28:20.58126');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (27, 'tt0245429', 129, 'Spirited Away', 2001, '/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg', '{16,10751,14}', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', '[{"name": "Rumi Hiiragi", "character": "Chihiro (voice)"}, {"name": "Miyu Irino", "character": "Haku (voice)"}, {"name": "Mari Natsuki", "character": "Yubaba / Zeniba (voice)"}, {"name": "Takashi Naito", "character": "Father (voice)"}, {"name": "Yasuko Sawaguchi", "character": "Mother (voice)"}]', 'Hayao Miyazaki', NULL, '2026-07-13 21:28:21.723945');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (28, 'tt0317248', 598, 'City of God', 2002, '/k7eYdWvhYQyRQoU2TB2A2Xu2TfD.jpg', '{18,80}', 'In the poverty-stricken favelas of Rio de Janeiro in the 1970s, two young men choose different paths. Rocket is a budding photographer who documents the increasing drug-related violence of his neighborhood, while José “Zé” Pequeno is an ambitious drug dealer diving into a dangerous life of crime.', '[{"name": "Alexandre Rodrigues", "character": "Buscapé - Rocket"}, {"name": "Leandro Firmino", "character": "Zé Pequeno - Li''l Zé"}, {"name": "Phellipe Haagensen", "character": "Bené - Benny"}, {"name": "Douglas Silva", "character": "Dadinho - Li''l Dice"}, {"name": "Jonathan Haagensen", "character": "Cabeleira - Shaggy"}]', 'Fernando Meirelles', NULL, '2026-07-13 21:28:22.292757');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (29, 'tt0118799', 637, 'Life Is Beautiful', 1997, '/74hLDKjD5aGYOotO6esUVaeISa2.jpg', '{35,18}', 'A touching story of an Italian book seller of Jewish ancestry who lives in his own little fairy tale. His creative and happy life would come to an abrupt halt when his entire family is deported to a concentration camp during World War II. While locked up he tries to convince his son that the whole thing is just a game.', '[{"name": "Roberto Benigni", "character": "Guido"}, {"name": "Nicoletta Braschi", "character": "Dora"}, {"name": "Giorgio Cantarini", "character": "Giosué"}, {"name": "Giustino Durano", "character": "Zio"}, {"name": "Sergio Bini Bustric", "character": "Ferruccio"}]', 'Roberto Benigni', NULL, '2026-07-13 21:28:22.850657');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (32, 'tt1853728', 68718, 'Django Unchained', 2012, '/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg', '{18,37}', 'With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.', '[{"name": "Jamie Foxx", "character": "Django Freeman"}, {"name": "Christoph Waltz", "character": "Dr. King Schultz"}, {"name": "Leonardo DiCaprio", "character": "Calvin J. Candie"}, {"name": "Kerry Washington", "character": "Broomhilda von Shaft"}, {"name": "Samuel L. Jackson", "character": "Stephen"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:28:24.60594');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (33, 'tt0172495', 98, 'Gladiator', 2000, '/wN2xWp1eIwCKOD0BHTcErTBv1Uq.jpg', '{28,18,12}', 'After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.', '[{"name": "Russell Crowe", "character": "Maximus"}, {"name": "Joaquin Phoenix", "character": "Commodus"}, {"name": "Connie Nielsen", "character": "Lucilla"}, {"name": "Oliver Reed", "character": "Proximo"}, {"name": "Richard Harris", "character": "Marcus Aurelius"}]', 'Ridley Scott', NULL, '2026-07-13 21:28:25.187667');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (34, 'tt0482571', 1124, 'The Prestige', 2006, '/Ag2B2KHKQPukjH7WutmgnnSNurZ.jpg', '{18,9648,878}', 'A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences.', '[{"name": "Hugh Jackman", "character": "Robert Angier"}, {"name": "Christian Bale", "character": "Alfred Borden"}, {"name": "Michael Caine", "character": "Cutter"}, {"name": "Piper Perabo", "character": "Julia McCullough"}, {"name": "Rebecca Hall", "character": "Sarah"}]', 'Christopher Nolan', NULL, '2026-07-13 21:28:25.77766');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (35, 'tt0407887', 1422, 'The Departed', 2006, '/nT97ifVT2J1yMQmeq20Qblg61T.jpg', '{18,53,80}', 'To take down South Boston''s Irish Mafia, the police send in one of their own to infiltrate the underworld, not realizing the syndicate has done likewise. While an undercover cop curries favor with the mob kingpin, a career criminal rises through the police ranks. But both sides soon discover there''s a mole among them.', '[{"name": "Leonardo DiCaprio", "character": "Billy"}, {"name": "Matt Damon", "character": "Colin"}, {"name": "Jack Nicholson", "character": "Costello"}, {"name": "Mark Wahlberg", "character": "Dignam"}, {"name": "Martin Sheen", "character": "Queenan"}]', 'Martin Scorsese', NULL, '2026-07-13 21:28:26.357732');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (36, 'tt0088763', 105, 'Back to the Future', 1985, '/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg', '{12,35,878}', 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.', '[{"name": "Michael J. Fox", "character": "Marty McFly"}, {"name": "Christopher Lloyd", "character": "Emmett Brown"}, {"name": "Crispin Glover", "character": "George McFly"}, {"name": "Lea Thompson", "character": "Lorraine Baines"}, {"name": "Claudia Wells", "character": "Jennifer Parker"}]', 'Robert Zemeckis', NULL, '2026-07-13 21:28:26.927723');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (37, 'tt0110413', 101, 'Léon: The Professional', 1994, '/bxB2q91nKYp8JNzqE7t7TWBVupB.jpg', '{80,18,28}', 'Léon, the top hit man in New York, has earned a rep as an effective "cleaner". But when his next-door neighbors are wiped out by a loose-cannon DEA agent, he becomes the unwilling custodian of 12-year-old Mathilda. Before long, Mathilda''s thoughts turn to revenge, and she considers following in Léon''s footsteps.', '[{"name": "Jean Reno", "character": "Léon Montana"}, {"name": "Natalie Portman", "character": "Mathilda Lando"}, {"name": "Gary Oldman", "character": "Norman Stansfield"}, {"name": "Danny Aiello", "character": "Old Tony"}, {"name": "Peter Appel", "character": "Agent Malky"}]', 'Luc Besson', NULL, '2026-07-13 21:28:27.485144');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (38, 'tt0120586', 73, 'American History X', 1998, '/x2drgoXYZ8484lqyDj7L1CEVR4T.jpg', '{18}', 'Derek Vineyard is paroled after serving 3 years in prison for killing two African-American men. Through his brother, Danny Vineyard''s narration, we learn that before going to prison, Derek was a skinhead and the leader of a violent white supremacist gang that committed acts of racial crime throughout L.A. and his actions greatly influenced Danny. Reformed and fresh out of prison, Derek severs contact with the gang and becomes determined to keep Danny from going down the same violent path as he did.', '[{"name": "Edward Norton", "character": "Derek"}, {"name": "Edward Furlong", "character": "Danny"}, {"name": "Beverly D''Angelo", "character": "Doris"}, {"name": "Jennifer Lien", "character": "Davina"}, {"name": "Ethan Suplee", "character": "Seth"}]', 'Tony Kaye', NULL, '2026-07-13 21:28:28.058498');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (39, 'tt0110357', 8587, 'The Lion King', 1994, '/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg', '{16,10751,18}', 'Young lion prince Simba, eager to one day become king of the Pride Lands, grows up under the watchful eye of his father Mufasa; all the while his villainous uncle Scar conspires to take the throne for himself. Amid betrayal and tragedy, Simba must confront his past and find his rightful place in the Circle of Life.', '[{"name": "Matthew Broderick", "character": "Simba (voice)"}, {"name": "Moira Kelly", "character": "Nala (voice)"}, {"name": "Jeremy Irons", "character": "Scar (voice)"}, {"name": "Nathan Lane", "character": "Timon (voice)"}, {"name": "Ernie Sabella", "character": "Pumbaa (voice)"}]', 'Roger Allers', NULL, '2026-07-13 21:28:28.641055');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (40, 'tt0114814', 629, 'The Usual Suspects', 1995, '/99X2SgyFunJFXGAYnDv3sb9pnUD.jpg', '{18,80,53}', 'Held in an L.A. interrogation room, Verbal Kint attempts to convince the feds that a mythic crime lord, Keyser Soze, not only exists, but was also responsible for drawing him and his four partners into a multi-million dollar heist that ended with an explosion in San Pedro harbor – leaving few survivors. Verbal lures his interrogators with an incredible story of the crime lord''s almost supernatural prowess.', '[{"name": "Stephen Baldwin", "character": "McManus"}, {"name": "Gabriel Byrne", "character": "Keaton"}, {"name": "Benicio del Toro", "character": "Fenster"}, {"name": "Kevin Pollak", "character": "Hockney"}, {"name": "Kevin Spacey", "character": "Verbal"}]', 'Bryan Singer', NULL, '2026-07-13 21:28:29.20948');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (41, 'tt6751668', 496243, 'Parasite', 2019, '/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', '{35,53,18}', 'All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.', '[{"name": "Song Kang-ho", "character": "Kim Ki-taek"}, {"name": "Lee Sun-kyun", "character": "Park Dong-ik"}, {"name": "Cho Yeo-jeong", "character": "Yeon-kyo"}, {"name": "Choi Woo-shik", "character": "Ki-woo"}, {"name": "Park So-dam", "character": "Ki-jung"}]', 'Bong Joon Ho', NULL, '2026-07-13 21:28:29.783241');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (42, 'tt2582802', 244786, 'Whiplash', 2014, '/7fn624j5lj3xTme2SgiLCeuedmO.jpg', '{18,10402,53}', 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.', '[{"name": "Miles Teller", "character": "Andrew"}, {"name": "J.K. Simmons", "character": "Fletcher"}, {"name": "Paul Reiser", "character": "Jim"}, {"name": "Melissa Benoist", "character": "Nicole"}, {"name": "Austin Stowell", "character": "Ryan"}]', 'Damien Chazelle', NULL, '2026-07-13 21:28:30.352258');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (43, 'tt1675434', 77338, 'The Intouchables', 2011, '/1QU7HKgsQbGpzsJbJK4pAVQV9F5.jpg', '{18,35}', 'A true story of two men who should never have met – a quadriplegic aristocrat who was injured in a paragliding accident and a young man from the projects.', '[{"name": "François Cluzet", "character": "Philippe"}, {"name": "Omar Sy", "character": "Driss"}, {"name": "Anne Le Ny", "character": "Yvonne"}, {"name": "Audrey Fleurot", "character": "Magalie"}, {"name": "Joséphine de Meaux", "character": "La DRH société de courses"}]', 'Éric Toledano', NULL, '2026-07-13 21:28:30.922313');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (44, 'tt0253474', 423, 'The Pianist', 2002, '/2hFvxCCWrTmCYwfy7yum0GKRi3Y.jpg', '{18,10752}', 'The true story of pianist Władysław Szpilman''s experiences in Warsaw during the Nazi occupation. When the Jews of the city find themselves forced into a ghetto, Szpilman finds work playing in a café; and when his family is deported in 1942, he stays behind, works for a while as a laborer, and eventually goes into hiding in the ruins of the war-torn city.', '[{"name": "Adrien Brody", "character": "Władysław ''Władek'' Szpilman"}, {"name": "Thomas Kretschmann", "character": "Captain Wilm Hosenfeld"}, {"name": "Frank Finlay", "character": "Father"}, {"name": "Maureen Lipman", "character": "Mother"}, {"name": "Emilia Fox", "character": "Dorota"}]', 'Roman Polanski', NULL, '2026-07-13 21:28:31.564587');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (45, 'tt23849204', 1163258, '12th Fail', 2023, '/eebUPRI4Z5e1Z7Hev4JZAwMIFkX.jpg', '{18}', 'Based on the true story of IPS officer Manoj Kumar Sharma, 12th Fail sheds limelight on fearlessly embracing the idea of restarting the academic journey despite the setbacks and challenges and reclaiming one''s destiny at a place where millions of students attempt the world''s toughest competitive exam: UPSC.', '[{"name": "Vikrant Massey", "character": "Manoj Kumar Sharma"}, {"name": "Medha Shankr", "character": "Shraddha Joshi"}, {"name": "Anant Joshi", "character": "Pritam Pandey"}, {"name": "Anshumaan Pushkar", "character": "Gaurinandan"}, {"name": "Priyanshu Chatterjee", "character": "Dushyant Singh"}]', 'Vidhu Vinod Chopra', NULL, '2026-07-13 21:28:32.162082');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (48, 'tt10811166', 900783, 'The Kashmir Files', 2022, '/2VvjJFDBFYkVgr89BjqbUl26QyW.jpg', '{36,18}', 'Based on a true tragedy, the emotionally triggering film sheds light on the plight of Kashmiri Pandits (Hindus), a religious minority in the 1990s Kashmir valley, who were compelled to flee their homes by the Islamic militants.', '[{"name": "Mithun Chakraborty", "character": "IAS Brahma Dutt"}, {"name": "Anupam Kher", "character": "Pushkar Nath Pandit"}, {"name": "Darshan Kumaar", "character": "Krishna Pandit"}, {"name": "Pallavi Joshi", "character": "Radhika Menon"}, {"name": "Chinmay Mandlekar", "character": "Farooq Malik Bitta"}]', 'Vivek Agnihotri', NULL, '2026-07-13 21:28:33.913223');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (49, 'tt9362722', 569094, 'Spider-Man: Across the Spider-Verse', 2023, '/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', '{16,28,12,878}', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.', '[{"name": "Shameik Moore", "character": "Miles Morales (voice)"}, {"name": "Hailee Steinfeld", "character": "Gwen Stacy (voice)"}, {"name": "Brian Tyree Henry", "character": "Jeff Morales (voice)"}, {"name": "Luna Lauren Vélez", "character": "Rio Morales (voice)"}, {"name": "Jake Johnson", "character": "Peter B. Parker (voice)"}]', 'Justin K. Thompson', NULL, '2026-07-13 21:28:34.580043');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (477, 'tt2283748', 135718, 'OMG: Oh My God!', 2012, '/iTPzC3H2iG49xFIcMs01UfZeBXv.jpg', '{35,18}', 'A shopkeeper takes God to court when his shop is destroyed by an earthquake.', '[{"name": "Paresh Rawal", "character": "Kanjibhai"}, {"name": "Akshay Kumar", "character": "Krishna"}, {"name": "Mithun Chakraborty", "character": "Leeladhar Swamy"}, {"name": "Om Puri", "character": "Hanif Qureshi"}, {"name": "Mahesh Manjrekar", "character": "Lawyer Sardesai"}]', 'Umesh Shukla', NULL, '2026-07-13 21:32:43.03887');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (50, 'tt15097216', 855400, 'Jai Bhim', 2021, '/ehybiOtBUtrMkmtB39zQEtq1Jie.jpg', '{80,18,9648,36}', 'A pregnant woman from a primitive tribal community, searches desperately for her husband, who is missing from police custody. So as to find her husband and seek justice for them, as their voice, a High Court advocate rises in support. Will their battle for justice succeed?', '[{"name": "Suriya", "character": "Chandru"}, {"name": "Lijomol Jose", "character": "Sengani Rajakannu"}, {"name": "Baby Joshika Maya", "character": "Alli Rajakannu"}, {"name": "Manikandan", "character": "Rajakannu"}, {"name": "Rajisha Vijayan", "character": "Mythra"}]', 'T. J. Gnanavel', NULL, '2026-07-13 21:28:35.148438');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (51, 'tt0095327', 12477, 'Grave of the Fireflies', 1988, '/k9tv1rXZbOhH7eiCk378x61kNQ1.jpg', '{16,18,10752}', 'In the final months of World War II, 14-year-old Seita and his sister Setsuko are orphaned when their mother is killed during an air raid in Kobe, Japan. After a falling out with their aunt, they move into an abandoned bomb shelter. With no surviving relatives and their emergency rations depleted, Seita and Setsuko struggle to survive.', '[{"name": "Tsutomu Tatsumi", "character": "Seita (voice)"}, {"name": "Ayano Shiraishi", "character": "Setsuko (voice)"}, {"name": "Yoshiko Shinohara", "character": "Mother (voice)"}, {"name": "Akemi Yamaguchi", "character": "Auntie (voice)"}, {"name": "Masayo Sakai", "character": "Woman who takes care of Setsuko (voice)"}]', 'Isao Takahata', NULL, '2026-07-13 21:28:35.768359');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (53, 'tt1345836', 49026, 'The Dark Knight Rises', 2012, '/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', '{28,80,18,53}', 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.', '[{"name": "Christian Bale", "character": "Bruce Wayne"}, {"name": "Gary Oldman", "character": "Commissioner Gordon"}, {"name": "Tom Hardy", "character": "Bane"}, {"name": "Joseph Gordon-Levitt", "character": "Blake"}, {"name": "Anne Hathaway", "character": "Selina"}]', 'Christopher Nolan', NULL, '2026-07-13 21:28:36.925058');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (54, 'tt0361748', 16869, 'Inglourious Basterds', 2009, '/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', '{18,53,10752}', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as "The Basterds" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.', '[{"name": "Brad Pitt", "character": "LT. Aldo Raine"}, {"name": "Mélanie Laurent", "character": "Shosanna"}, {"name": "Christoph Waltz", "character": "COL. Hans Landa"}, {"name": "Eli Roth", "character": "SGT. Donny Donowitz"}, {"name": "Michael Fassbender", "character": "LT. Archie Hicox"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:28:37.493765');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (55, 'tt4154796', 299534, 'Avengers: Endgame', 2019, '/ulzhLuWrPK07P1YkdWQLZnQh1JL.jpg', '{12,878,28}', 'After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark / Iron Man"}, {"name": "Chris Evans", "character": "Steve Rogers / Captain America"}, {"name": "Mark Ruffalo", "character": "Bruce Banner / Hulk"}, {"name": "Chris Hemsworth", "character": "Thor"}, {"name": "Scarlett Johansson", "character": "Natasha Romanoff / Black Widow"}]', 'Joe Russo', NULL, '2026-07-13 21:28:38.154351');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (56, 'tt0209144', 77, 'Memento', 2000, '/fKTPH2WvH8nHTXeBYBVhawtRqtR.jpg', '{9648,53}', 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.', '[{"name": "Guy Pearce", "character": "Leonard"}, {"name": "Carrie-Anne Moss", "character": "Natalie"}, {"name": "Joe Pantoliano", "character": "Teddy"}, {"name": "Mark Boone Junior", "character": "Burt"}, {"name": "Russ Fega", "character": "Waiter"}]', 'Christopher Nolan', NULL, '2026-07-13 21:28:38.707022');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (57, 'tt4154756', 299536, 'Avengers: Infinity War', 2018, '/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', '{12,28,878}', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark / Iron Man"}, {"name": "Chris Evans", "character": "Steve Rogers / Captain America"}, {"name": "Chris Hemsworth", "character": "Thor"}, {"name": "Josh Brolin", "character": "Thanos"}, {"name": "Mark Ruffalo", "character": "Bruce Banner / Hulk"}]', 'Joe Russo', NULL, '2026-07-13 21:28:39.280014');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (58, 'tt0910970', 10681, 'WALL·E', 2008, '/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', '{16,10751,878}', 'After hundreds of years doing what he was built for, WALL•E— a robot designed to clean up the earth—discovers a new purpose in life when he meets a sleek search robot named EVE. EVE comes to realize that WALL•E has inadvertently stumbled upon the key to the planet''s future, and races back to space to report to the humans. Meanwhile, WALL•E chases EVE across the galaxy and sets into motion one of the most imaginative adventures ever brought to the big screen.', '[{"name": "Ben Burtt", "character": "WALL·E / M-O (voice)"}, {"name": "Elissa Knight", "character": "EVE (voice)"}, {"name": "Jeff Garlin", "character": "Captain (voice)"}, {"name": "Fred Willard", "character": "Shelby Forthright, BnL CEO"}, {"name": "John Ratzenberger", "character": "John (voice)"}]', 'Andrew Stanton', NULL, '2026-07-13 21:28:39.83979');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (59, 'tt0095765', 11216, 'Cinema Paradiso', 1988, '/gCI2AeMV4IHSewhJkzsur5MEp6R.jpg', '{18,10749}', 'A filmmaker recalls his childhood, when he fell in love with the movies at his village''s theater and formed a deep friendship with the theater''s projectionist.', '[{"name": "Philippe Noiret", "character": "Alfredo"}, {"name": "Jacques Perrin", "character": "Salvatore ''Totò'' Di Vita (adult)"}, {"name": "Marco Leonardi", "character": "Salvatore ''Totò'' Di Vita (teen)"}, {"name": "Salvatore Cascio", "character": "Salvatore ''Totò'' Di Vita (child)"}, {"name": "Agnese Nano", "character": "Elena Mendola (teen) / Elena''s daughter (in Director''s cut)"}]', 'Giuseppe Tornatore', NULL, '2026-07-13 21:28:40.398885');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (60, 'tt0081505', 694, 'The Shining', 1980, '/uAR0AWqhQL1hQa69UDEbb2rE5Wx.jpg', '{27,53}', 'Jack Torrance accepts a caretaker job at the Overlook Hotel, where he, along with his wife Wendy and their son Danny, must live isolated from the rest of the world for the winter. But they aren''t prepared for the madness that lurks within.', '[{"name": "Jack Nicholson", "character": "Jack Torrance"}, {"name": "Shelley Duvall", "character": "Wendy Torrance"}, {"name": "Danny Lloyd", "character": "Danny"}, {"name": "Scatman Crothers", "character": "Hallorann"}, {"name": "Barry Nelson", "character": "Ullman"}]', 'Stanley Kubrick', NULL, '2026-07-13 21:28:40.979435');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (61, 'tt0119217', 489, 'Good Will Hunting', 1997, '/z2FnLKpFi1HPO7BEJxdkv6hpJSU.jpg', '{18}', 'Will Hunting is a headstrong, working-class genius who is failing the lessons of life. After one too many run-ins with the law, Will''s last chance is a psychology professor, who might be the only man who can reach him.', '[{"name": "Matt Damon", "character": "Will Hunting"}, {"name": "Robin Williams", "character": "Sean Maguire"}, {"name": "Ben Affleck", "character": "Chuckie Sullivan"}, {"name": "Stellan Skarsgård", "character": "Gerald Lambeau"}, {"name": "Minnie Driver", "character": "Skylar"}]', 'Gus Van Sant', NULL, '2026-07-13 21:28:41.619127');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (62, 'tt0082971', 85, 'Raiders of the Lost Ark', 1981, '/ceG9VzoRAVGwivFU403Wc3AHRys.jpg', '{12,28}', 'When Dr. Indiana Jones – the tweed-suited professor who just happens to be a celebrated archaeologist – is hired by the government to locate the legendary Ark of the Covenant, he finds himself up against the entire Nazi regime.', '[{"name": "Harrison Ford", "character": "Indiana Jones"}, {"name": "Karen Allen", "character": "Marion Ravenwood"}, {"name": "Paul Freeman", "character": "Dr. René Belloq"}, {"name": "John Rhys-Davies", "character": "Sallah"}, {"name": "Ronald Lacey", "character": "Major Arnold Toht"}]', 'Steven Spielberg', NULL, '2026-07-13 21:28:42.18711');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (65, 'tt0090605', 679, 'Aliens', 1986, '/r1x5JGpyqZU8PYhbs4UcrO1Xb6x.jpg', '{28,53,878}', 'Ripley, the sole survivor of the Nostromo''s deadly encounter with the monstrous Alien, returns to Earth after drifting through space in hypersleep for 57 years. Although her story is initially met with skepticism, she agrees to accompany a team of Colonial Marines back to LV-426.', '[{"name": "Sigourney Weaver", "character": "Ripley"}, {"name": "Carrie Henn", "character": "Newt"}, {"name": "Michael Biehn", "character": "Corporal Hicks"}, {"name": "Paul Reiser", "character": "Burke"}, {"name": "Lance Henriksen", "character": "Bishop"}]', 'James Cameron', NULL, '2026-07-13 21:28:43.880488');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (66, 'tt4633694', 324857, 'Spider-Man: Into the Spider-Verse', 2018, '/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', '{16,28,12,878}', 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.', '[{"name": "Shameik Moore", "character": "Miles Morales (voice)"}, {"name": "Jake Johnson", "character": "Peter B. Parker (voice)"}, {"name": "Hailee Steinfeld", "character": "Gwen Stacy (voice)"}, {"name": "Mahershala Ali", "character": "Uncle Aaron (voice)"}, {"name": "Brian Tyree Henry", "character": "Jefferson Davis (voice)"}]', 'Bob Persichetti', NULL, '2026-07-13 21:28:44.440332');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (68, 'tt15239678', 693134, 'Dune: Part Two', 2024, '/heM4XKC0jA8fTSNe8F7oUkcJV7Z.jpg', '{878,12}', 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.', '[{"name": "Timothée Chalamet", "character": "Paul Atreides"}, {"name": "Zendaya", "character": "Chani"}, {"name": "Rebecca Ferguson", "character": "Jessica"}, {"name": "Javier Bardem", "character": "Stilgar"}, {"name": "Josh Brolin", "character": "Gurney Halleck"}]', 'Denis Villeneuve', NULL, '2026-07-13 21:28:45.582362');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (69, 'tt2380307', 354912, 'Coco', 2017, '/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', '{10751,16,10402,12}', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', '[{"name": "Anthony Gonzalez", "character": "Miguel Rivera (voice)"}, {"name": "Gael García Bernal", "character": "Héctor (voice)"}, {"name": "Benjamin Bratt", "character": "Ernesto de la Cruz (voice)"}, {"name": "Alanna Ubach", "character": "Mamá Imelda (voice)"}, {"name": "Renée Victor", "character": "Abuelita (voice)"}]', 'Lee Unkrich', NULL, '2026-07-13 21:28:46.183655');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (71, 'tt1187043', 20453, '3 Idiots', 2009, '/66A9MqXOyVFCssoloscw79z8Tew.jpg', '{18,35}', 'Rascal. Joker. Dreamer. Genius... You''ve never met a college student quite like "Rancho." From the moment he arrives at India''s most prestigious university, Rancho''s outlandish schemes turn the campus upside down—along with the lives of his two newfound best friends. Together, they make life miserable for "Virus," the school’s uptight and heartless dean. But when Rancho catches the eye of the dean''s daughter, Virus sets his sights on flunking out the "3 idiots" once and for all.', '[{"name": "Aamir Khan", "character": "Ranchoddas \"Rancho\" Chanchad"}, {"name": "R. Madhavan", "character": "Farhan Qureshi"}, {"name": "Sharman Joshi", "character": "Raju Rastogi"}, {"name": "Kareena Kapoor Khan", "character": "Pia Sahastrabudhhe"}, {"name": "Boman Irani", "character": "Viru \"Virus\" Sahastrabudhhe"}]', 'Rajkumar Hirani', NULL, '2026-07-13 21:28:47.334228');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (72, 'tt0086879', 279, 'Amadeus', 1984, '/gQRfiyfGvr1az0quaYyMram3Aqt.jpg', '{18,36,10402}', 'Disciplined Italian composer Antonio Salieri becomes consumed by jealousy and resentment towards the hedonistic and remarkably talented young Salzburger composer Wolfgang Amadeus Mozart.', '[{"name": "F. Murray Abraham", "character": "Antonio Salieri"}, {"name": "Tom Hulce", "character": "Wolfgang Amadeus Mozart"}, {"name": "Elizabeth Berridge", "character": "Constanze Mozart"}, {"name": "Simon Callow", "character": "Emanuel Schikaneder"}, {"name": "Roy Dotrice", "character": "Leopold Mozart"}]', 'Miloš Forman', NULL, '2026-07-13 21:28:47.918977');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (74, 'tt0405094', 582, 'The Lives of Others', 2006, '/cVUDMnskSc01rdbyH0tLATTJUdP.jpg', '{18,53}', 'In 1984 East Berlin, dedicated Stasi officer Gerd Wiesler begins spying on a famous playwright and his actress-lover Christa-Maria. Wiesler becomes unexpectedly sympathetic to the couple, and faces conflicting loyalties when his superior takes a liking to Christa-Maria.', '[{"name": "Martina Gedeck", "character": "Christa-Maria Sieland"}, {"name": "Ulrich Mühe", "character": "Gerd Wiesler"}, {"name": "Sebastian Koch", "character": "Georg Dreyman"}, {"name": "Ulrich Tukur", "character": "Anton Grubitz"}, {"name": "Thomas Thieme", "character": "Bruno Hempf"}]', 'Florian Henckel von Donnersmarck', NULL, '2026-07-13 21:28:49.080966');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (75, 'tt5311514', 372058, 'Your Name.', 2016, '/q719jXXEzOoYaps6babgKnONONX.jpg', '{16,10749,18}', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.', '[{"name": "Ryunosuke Kamiki", "character": "Taki Tachibana (voice)"}, {"name": "Mone Kamishiraishi", "character": "Mitsuha Miyamizu (voice)"}, {"name": "Ryo Narita", "character": "Katsuhiko Teshigawara (voice)"}, {"name": "Aoi Yuuki", "character": "Sayaka Natori (voice)"}, {"name": "Nobunaga Shimazaki", "character": "Tsukasa Fujii (voice)"}]', 'Makoto Shinkai', NULL, '2026-07-13 21:28:49.664753');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (76, 'tt10189514', 595228, 'Soorarai Pottru', 2020, '/5uimlxPCgAei8JfQUDFEUQLoyyh.jpg', '{18,28}', 'Nedumaaran Rajangam "Maara" sets out to make the common man fly and in the process takes on the world''s most capital intensive industry and several enemies who stand in his way.', '[{"name": "Suriya", "character": "Nedumaaran ''Maara'' Rajangam"}, {"name": "Aparna Balamurali", "character": "Sundari ''Bommi'' Nedumaaran"}, {"name": "Paresh Rawal", "character": "Paresh Goswami"}, {"name": "Mohan Babu", "character": "M. Bhaktavatsalam Naidu"}, {"name": "Urvashi", "character": "Pechi Rajangam"}]', 'Sudha Kongara Prasad', NULL, '2026-07-13 21:28:50.233522');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (77, 'tt7286456', 475557, 'Joker', 2019, '/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', '{80,53,18}', 'During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.', '[{"name": "Joaquin Phoenix", "character": "Arthur Fleck"}, {"name": "Robert De Niro", "character": "Murray Franklin"}, {"name": "Zazie Beetz", "character": "Sophie Dumond"}, {"name": "Frances Conroy", "character": "Penny Fleck"}, {"name": "Brett Cullen", "character": "Thomas Wayne"}]', 'Todd Phillips', NULL, '2026-07-13 21:28:50.794145');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (78, 'tt0169547', 14, 'American Beauty', 1999, '/wby9315QzVKdW9BonAefg8jGTTb.jpg', '{18}', 'Lester Burnham, a depressed suburban father in a mid-life crisis, decides to turn his hectic life around after developing an infatuation with his daughter''s attractive friend.', '[{"name": "Kevin Spacey", "character": "Lester Burnham"}, {"name": "Annette Bening", "character": "Carolyn Burnham"}, {"name": "Thora Birch", "character": "Jane Burnham"}, {"name": "Wes Bentley", "character": "Ricky Fitts"}, {"name": "Mena Suvari", "character": "Angela Hayes"}]', 'Sam Mendes', NULL, '2026-07-13 21:28:51.398796');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (79, 'tt1049413', 14160, 'Up', 2009, '/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', '{16,35,10751,12}', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.', '[{"name": "Ed Asner", "character": "Carl Fredricksen (voice)"}, {"name": "Christopher Plummer", "character": "Charles Muntz (voice)"}, {"name": "Jordan Nagai", "character": "Russell (voice)"}, {"name": "Bob Peterson", "character": "Dug / Alpha (voice)"}, {"name": "Delroy Lindo", "character": "Beta (voice)"}]', 'Pete Docter', NULL, '2026-07-13 21:28:51.963954');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (80, 'tt0086190', 1892, 'Return of the Jedi', 1983, '/jQYlydvHm3kUix1f8prMucrplhm.jpg', '{12,28,878}', 'Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.', '[{"name": "Mark Hamill", "character": "Luke Skywalker"}, {"name": "Harrison Ford", "character": "Han Solo"}, {"name": "Carrie Fisher", "character": "Princess Leia"}, {"name": "Billy Dee Williams", "character": "Lando Calrissian"}, {"name": "Anthony Daniels", "character": "C-3PO"}]', 'Richard Marquand', NULL, '2026-07-13 21:28:52.539525');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (81, 'tt0338013', 38, 'Eternal Sunshine of the Spotless Mind', 2004, '/5MwkWH9tYHv3mV9OdYTMR5qreIz.jpg', '{878,18,10749}', 'Joel Barish, heartbroken that his girlfriend underwent a procedure to erase him from her memory, decides to do the same. However, as he watches his memories of her fade away, he realises that he still loves her, and may be too late to correct his mistake.', '[{"name": "Jim Carrey", "character": "Joel Barish"}, {"name": "Kate Winslet", "character": "Clementine Kruczynski"}, {"name": "Kirsten Dunst", "character": "Mary"}, {"name": "Mark Ruffalo", "character": "Stan"}, {"name": "Elijah Wood", "character": "Patrick"}]', 'Michel Gondry', NULL, '2026-07-13 21:28:53.102321');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (82, 'tt0114709', 862, 'Toy Story', 1995, '/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', '{10751,35,16,12}', 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.', '[{"name": "Tom Hanks", "character": "Woody (voice)"}, {"name": "Tim Allen", "character": "Buzz Lightyear (voice)"}, {"name": "Don Rickles", "character": "Mr. Potato Head (voice)"}, {"name": "Jim Varney", "character": "Slinky Dog (voice)"}, {"name": "Wallace Shawn", "character": "Rex (voice)"}]', 'John Lasseter', NULL, '2026-07-13 21:28:53.663319');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (83, 'tt0112573', 197, 'Braveheart', 1995, '/or1gBugydmjToAEq7OZY0owwFk.jpg', '{28,18,36,10752}', 'Enraged at the slaughter of Murron, his new bride and childhood love, Scottish warrior William Wallace slays a platoon of the local English lord''s soldiers. This leads the village to revolt and, eventually, the entire country to rise up against English rule.', '[{"name": "Mel Gibson", "character": "William Wallace"}, {"name": "Catherine McCormack", "character": "Murron MacClannough"}, {"name": "Sophie Marceau", "character": "Princess Isabelle"}, {"name": "Patrick McGoohan", "character": "King Edward"}, {"name": "Angus Macfadyen", "character": "Robert the Bruce"}]', 'Mel Gibson', NULL, '2026-07-13 21:28:54.235933');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (84, 'tt0086250', 111, 'Scarface', 1983, '/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', '{28,80,18}', 'After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.', '[{"name": "Al Pacino", "character": "Tony Montana"}, {"name": "Steven Bauer", "character": "Manny Ray"}, {"name": "Michelle Pfeiffer", "character": "Elvira"}, {"name": "Mary Elizabeth Mastrantonio", "character": "Gina"}, {"name": "Robert Loggia", "character": "Frank Lopez"}]', 'Brian De Palma', NULL, '2026-07-13 21:28:54.812024');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (85, 'tt0435761', 10193, 'Toy Story 3', 2010, '/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg', '{16,10751,35}', 'Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.', '[{"name": "Tom Hanks", "character": "Woody (voice)"}, {"name": "Tim Allen", "character": "Buzz Lightyear (voice)"}, {"name": "Joan Cusack", "character": "Jessie (voice)"}, {"name": "Don Rickles", "character": "Mr. Potato Head (voice)"}, {"name": "Wallace Shawn", "character": "Rex (voice)"}]', 'Lee Unkrich', NULL, '2026-07-13 21:28:55.447924');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (86, 'tt0180093', 641, 'Requiem for a Dream', 2000, '/9BTwsLaMVHOGFlmsSlx5QYCaXb.jpg', '{80,18}', 'The drug-induced utopias of four Coney Island residents are shattered when their addictions run deep.', '[{"name": "Ellen Burstyn", "character": "Sara Goldfarb"}, {"name": "Jared Leto", "character": "Harry Goldfarb"}, {"name": "Jennifer Connelly", "character": "Marion Silver"}, {"name": "Marlon Wayans", "character": "Tyrone C. Love"}, {"name": "Christopher McDonald", "character": "Tappy Tibbons"}]', 'Darren Aronofsky', NULL, '2026-07-13 21:28:56.018845');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (88, 'tt0113277', 949, 'Heat', 1995, '/e09dLw1Ljtccd2P4NsuUvVtS5du.jpg', '{80,18,28}', 'Obsessive master thief Neil McCauley leads a top-notch crew on various daring heists throughout Los Angeles while determined detective Vincent Hanna pursues him without rest. Each man recognizes and respects the ability and the dedication of the other even though they are aware their cat-and-mouse game may end in violence.', '[{"name": "Al Pacino", "character": "Lt. Vincent Hanna"}, {"name": "Robert De Niro", "character": "Neil McCauley"}, {"name": "Val Kilmer", "character": "Chris Shiherlis"}, {"name": "Jon Voight", "character": "Nate"}, {"name": "Tom Sizemore", "character": "Michael Cheritto"}]', 'Michael Mann', NULL, '2026-07-13 21:28:57.164051');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (92, 'tt0364569', 670, 'Oldboy', 2003, '/pWDtjs568ZfOTMbURQBYuT4Qxka.jpg', '{53,9648}', 'With no clue how he came to be imprisoned, drugged and tortured for 15 years, a desperate man seeks revenge on his captors.', '[{"name": "Choi Min-sik", "character": "Oh Dae-su"}, {"name": "Yoo Ji-tae", "character": "Lee Woo-jin"}, {"name": "Kang Hye-jung", "character": "Mi-do"}, {"name": "Kim Byeong-ok", "character": "Mr. Han"}, {"name": "Ji Dae-han", "character": "No Joo-hwan"}]', 'Park Chan-wook', NULL, '2026-07-13 21:28:59.56024');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (95, 'tt0119698', 128, 'Princess Mononoke', 1997, '/cMYCDADoLKLbB83g4WnJegaZimC.jpg', '{12,14,16}', 'Ashitaka, a prince of the disappearing Emishi people, is cursed by a demonized boar god and must journey to the west to find a cure. Along the way, he encounters San, a young human woman fighting to protect the forest, and Lady Eboshi, who is trying to destroy it. Ashitaka must find a way to bring balance to this conflict.', '[{"name": "Yoji Matsuda", "character": "Ashitaka (voice)"}, {"name": "Yuriko Ishida", "character": "San / Kaya (voice)"}, {"name": "Yuko Tanaka", "character": "Eboshi Gozen (voice)"}, {"name": "Kaoru Kobayashi", "character": "Jikobo (voice)"}, {"name": "Masahiko Nishimura", "character": "Kouroku (voice)"}]', 'Hayao Miyazaki', NULL, '2026-07-13 21:29:01.281816');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (96, 'tt2106476', 103663, 'The Hunt', 2012, '/jkixsXzRh28q3PCqFoWcf7unghT.jpg', '{18}', 'A teacher lives a lonely life, all the while struggling over his son’s custody. His life slowly gets better as he finds love and receives good news from his son, but his new luck is about to be brutally shattered by an innocent little lie.', '[{"name": "Mads Mikkelsen", "character": "Lucas"}, {"name": "Thomas Bo Larsen", "character": "Theo"}, {"name": "Annika", "character": "Klara"}, {"name": "Lasse Fogelstrøm", "character": "Marcus"}, {"name": "Susse Wold", "character": "Grethe"}]', 'Thomas Vinterberg', NULL, '2026-07-13 21:29:01.846848');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (97, 'tt0087843', 311, 'Once Upon a Time in America', 1984, '/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg', '{18,80}', 'A former Prohibition-era Jewish gangster returns to the Lower East Side of Manhattan over thirty years later, where he once again must confront the ghosts and regrets of his old life.', '[{"name": "Robert De Niro", "character": "Noodles"}, {"name": "James Woods", "character": "Max"}, {"name": "Elizabeth McGovern", "character": "Deborah"}, {"name": "Joe Pesci", "character": "Frankie"}, {"name": "Burt Young", "character": "Joe"}]', 'Sergio Leone', NULL, '2026-07-13 21:29:02.397539');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (101, 'tt0993846', 106646, 'The Wolf of Wall Street', 2013, '/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg', '{80,18,35}', 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.', '[{"name": "Leonardo DiCaprio", "character": "Jordan Belfort"}, {"name": "Jonah Hill", "character": "Donnie Azoff"}, {"name": "Margot Robbie", "character": "Naomi Lapaglia"}, {"name": "Matthew McConaughey", "character": "Mark Hanna"}, {"name": "Kyle Chandler", "character": "Agent Patrick Denham"}]', 'Martin Scorsese', NULL, '2026-07-13 21:29:04.717298');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (102, 'tt0372784', 272, 'Batman Begins', 2005, '/sPX89Td70IDDjVr85jdSBb4rWGr.jpg', '{18,80,28}', 'Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.', '[{"name": "Christian Bale", "character": "Bruce Wayne / Batman"}, {"name": "Michael Caine", "character": "Alfred"}, {"name": "Liam Neeson", "character": "Ducard"}, {"name": "Katie Holmes", "character": "Rachel Dawes"}, {"name": "Gary Oldman", "character": "Jim Gordon"}]', 'Christopher Nolan', NULL, '2026-07-13 21:29:05.306594');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (103, 'tt1130884', 11324, 'Shutter Island', 2010, '/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg', '{18,53,9648}', 'World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by troubling visions and a mysterious doctor.', '[{"name": "Leonardo DiCaprio", "character": "Teddy Daniels"}, {"name": "Mark Ruffalo", "character": "Chuck Aule"}, {"name": "Ben Kingsley", "character": "Dr. Cawley"}, {"name": "Max von Sydow", "character": "Dr. Naehring"}, {"name": "Michelle Williams", "character": "Dolores"}]', 'Martin Scorsese', NULL, '2026-07-13 21:29:05.881387');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (104, 'tt0120382', 37165, 'The Truman Show', 1998, '/vuza0WqY239yBXOadKlGwJsZJFE.jpg', '{35,18}', 'In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.', '[{"name": "Jim Carrey", "character": "Truman Burbank"}, {"name": "Laura Linney", "character": "Meryl Burbank / Hannah Gill"}, {"name": "Noah Emmerich", "character": "Marlon / Louis Coltrane"}, {"name": "Natascha McElhone", "character": "Lauren Garland / Sylvia"}, {"name": "Holland Taylor", "character": "Angela Montclair / Alanis Montclair"}]', 'Peter Weir', NULL, '2026-07-13 21:29:06.45445');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (106, 'tt0266697', 24, 'Kill Bill: Vol. 1', 2003, '/v7TaX8kXMXs5yFFGR41guUDNcnB.jpg', '{28,80}', 'An assassin is shot by her ruthless employer, Bill, and other members of their assassination circle – but she lives to plot her vengeance.', '[{"name": "Uma Thurman", "character": "The Bride"}, {"name": "Lucy Liu", "character": "O-Ren Ishii"}, {"name": "Vivica A. Fox", "character": "Vernita Green"}, {"name": "Daryl Hannah", "character": "Elle Driver"}, {"name": "David Carradine", "character": "Bill"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:29:07.579224');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (107, 'tt0082096', 387, 'Das Boot', 1981, '/u8FhQPncOAkwcei2OI9orPWhV6K.jpg', '{18,36,10752}', 'A German submarine hunts allied ships during the Second World War, but it soon becomes the hunted. The crew tries to survive below the surface, while stretching both the boat and themselves to their limits.', '[{"name": "Jürgen Prochnow", "character": "Captain Lieutenant ''Der Alte''"}, {"name": "Herbert Grönemeyer", "character": "Lieutenant Werner"}, {"name": "Klaus Wennemann", "character": "Chief Engineer"}, {"name": "Hubertus Bengsch", "character": "First Watch Officer"}, {"name": "Martin Semmelrogge", "character": "Second Watch Officer"}]', 'Wolfgang Petersen', NULL, '2026-07-13 21:29:08.143463');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (109, 'tt0266543', 12, 'Finding Nemo', 2003, '/5lc6nQc0VhWFYFbNv016xze8Jvy.jpg', '{16,10751,12}', 'Nemo, an adventurous young clownfish, is unexpectedly taken from his Great Barrier Reef home to a dentist''s office aquarium. It''s up to his worrisome father Marlin and a friendly but forgetful fish Dory to bring Nemo home -- meeting vegetarian sharks, surfer dude turtles, hypnotic jellyfish, hungry seagulls, and more along the way.', '[{"name": "Albert Brooks", "character": "Marlin (voice)"}, {"name": "Ellen DeGeneres", "character": "Dory (voice)"}, {"name": "Alexander Gould", "character": "Nemo (voice)"}, {"name": "Willem Dafoe", "character": "Gill (voice)"}, {"name": "Geoffrey Rush", "character": "Nigel (voice)"}]', 'Andrew Stanton', NULL, '2026-07-13 21:29:09.32917');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (110, 'tt0477348', 6977, 'No Country for Old Men', 2007, '/uB7RDZby43Wvu8SKGHHTwGyTDBX.jpg', '{80,53,37}', 'Llewelyn Moss stumbles upon dead bodies, $2 million and a hoard of heroin in a Texas desert, but methodical killer Anton Chigurh comes looking for it, with local sheriff Ed Tom Bell hot on his trail. The roles of prey and predator blur as the violent pursuit of money and justice collide.', '[{"name": "Javier Bardem", "character": "Anton Chigurh"}, {"name": "Tommy Lee Jones", "character": "Ed Tom Bell"}, {"name": "Josh Brolin", "character": "Llewelyn Moss"}, {"name": "Woody Harrelson", "character": "Carson Wells"}, {"name": "Kelly Macdonald", "character": "Carla Jean Moss"}]', 'Joel Coen', NULL, '2026-07-13 21:29:09.898864');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (111, 'tt0107290', 329, 'Jurassic Park', 1993, '/63viWuPfYQjRYLSZSZNq7dglJP5.jpg', '{12,878}', 'A wealthy entrepreneur secretly creates a theme park featuring living dinosaurs drawn from prehistoric DNA. Before opening day, he invites a team of experts and his two eager grandchildren to experience the park and help calm anxious investors. However, the park is anything but amusing as the security systems go off-line and the dinosaurs escape.', '[{"name": "Sam Neill", "character": "Grant"}, {"name": "Laura Dern", "character": "Ellie"}, {"name": "Jeff Goldblum", "character": "Malcolm"}, {"name": "Richard Attenborough", "character": "Hammond"}, {"name": "Bob Peck", "character": "Muldoon"}]', 'Steven Spielberg', NULL, '2026-07-13 21:29:10.49799');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (112, 'tt0105236', 500, 'Reservoir Dogs', 1992, '/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg', '{80,53}', 'A botched robbery indicates a police informant, and the pressure mounts in the aftermath at a warehouse. Crime begets violence as the survivors -- veteran Mr. White, newcomer Mr. Orange, psychopathic parolee Mr. Blonde, bickering weasel Mr. Pink and Nice Guy Eddie -- unravel.', '[{"name": "Harvey Keitel", "character": "Mr. White / Larry Dimmick"}, {"name": "Tim Roth", "character": "Mr. Orange / Freddy Newandyke"}, {"name": "Michael Madsen", "character": "Mr. Blonde / Vic Vega"}, {"name": "Chris Penn", "character": "\"Nice Guy\" Eddie Cabot"}, {"name": "Steve Buscemi", "character": "Mr. Pink"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:29:11.06211');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (113, 'tt0167404', 745, 'The Sixth Sense', 1999, '/vOyfUXNFSnaTk7Vk5AjpsKTUWsu.jpg', '{9648,53,18}', 'Following an unexpected tragedy, child psychologist Malcolm Crowe meets a nine year old boy named Cole Sear, who is hiding a dark secret.', '[{"name": "Bruce Willis", "character": "Malcolm Crowe"}, {"name": "Haley Joel Osment", "character": "Cole Sear"}, {"name": "Toni Collette", "character": "Lynn Sear"}, {"name": "Olivia Williams", "character": "Anna Crowe"}, {"name": "Trevor Morgan", "character": "Tommy Tammisimo"}]', 'M. Night Shyamalan', NULL, '2026-07-13 21:29:11.614714');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (114, 'tt1832382', 60243, 'A Separation', 2011, '/xQadpnoLokxzN3hRpCPbBGpxsiz.jpg', '{18}', 'A married couple are faced with a difficult decision - to improve the life of their child by moving to another country or to stay in Iran and look after a deteriorating parent who has Alzheimer''s disease.', '[{"name": "Leila Hatami", "character": "Simin"}, {"name": "Payman Maadi", "character": "Nader"}, {"name": "Sareh Bayat", "character": "Razieh"}, {"name": "Sarina Farhadi", "character": "Termeh"}, {"name": "Shahab Hosseini", "character": "Hojjat"}]', 'Asghar Farhadi', NULL, '2026-07-13 21:29:12.184893');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (115, 'tt15398776', 872585, 'Oppenheimer', 2023, '/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', '{18,36}', 'The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.', '[{"name": "Cillian Murphy", "character": "J. Robert Oppenheimer"}, {"name": "Emily Blunt", "character": "Kitty Oppenheimer"}, {"name": "Matt Damon", "character": "Leslie Groves"}, {"name": "Robert Downey Jr.", "character": "Lewis Strauss"}, {"name": "Florence Pugh", "character": "Jean Tatlock"}]', 'Christopher Nolan', NULL, '2026-07-13 21:29:12.78097');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (116, 'tt0268978', 453, 'A Beautiful Mind', 2001, '/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg', '{18,10749}', 'From the heights of notoriety to the depths of depravity, John Forbes Nash Jr. experiences it all. As a brilliant but socially awkward mathematician, he made a groundbreaking discovery early in his career and stands on the brink of international acclaim. But as the handsome and arrogant Nash accepts secret work in cryptography, he becomes entangled in a mysterious conspiracy. His life takes a nightmarish turn and he soon finds himself on a painful and harrowing journey of self-discovery.', '[{"name": "Russell Crowe", "character": "John Nash"}, {"name": "Jennifer Connelly", "character": "Alicia Nash"}, {"name": "Ed Harris", "character": "William Parcher"}, {"name": "Paul Bettany", "character": "Charles Herman"}, {"name": "Christopher Plummer", "character": "Dr. Rosen"}]', 'Ron Howard', NULL, '2026-07-13 21:29:13.354294');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (117, 'tt0095016', 562, 'Die Hard', 1988, '/7Bjd8kfmDSOzpmhySpEhkUyK2oH.jpg', '{28,53}', 'High above the city of L.A. a team of terrorists has seized a building, taken hostages, and declared war. One man has manages to escape... An off-duty cop hiding somewhere inside. He''s alone, tired... and the only chance anyone has got.', '[{"name": "Bruce Willis", "character": "John McClane"}, {"name": "Alan Rickman", "character": "Hans Gruber"}, {"name": "Alexander Godunov", "character": "Karl"}, {"name": "Bonnie Bedelia", "character": "Holly Gennaro McClane"}, {"name": "Reginald VelJohnson", "character": "Al Powell"}]', 'John McTiernan', NULL, '2026-07-13 21:29:13.915801');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (119, 'tt0208092', 107, 'Snatch', 2000, '/kJZoAHq1SLDdWjeNGtlHAnGpmFV.jpg', '{80,35}', 'Unscrupulous boxing promoters, violent bookies, a Russian gangster, incompetent amateur robbers, and supposedly Jewish jewellers fight to track down a priceless stolen diamond.', '[{"name": "Jason Statham", "character": "Turkish"}, {"name": "Alan Ford", "character": "Brick Top"}, {"name": "Stephen Graham", "character": "Tommy"}, {"name": "Brad Pitt", "character": "Mickey O''Neil"}, {"name": "Dennis Farina", "character": "Avi"}]', 'Guy Ritchie', NULL, '2026-07-13 21:29:15.113087');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (120, 'tt1392214', 146233, 'Prisoners', 2013, '/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg', '{18,53,80}', 'After his six-year-old daughter is abducted, a desperate father takes justice into his own hands when he loses faith in the detective leading the investigation, setting both men on a collision course as the search descends into obsession and moral compromise.', '[{"name": "Hugh Jackman", "character": "Keller Dover"}, {"name": "Jake Gyllenhaal", "character": "Detective Loki"}, {"name": "Viola Davis", "character": "Nancy Birch"}, {"name": "Maria Bello", "character": "Grace Dover"}, {"name": "Terrence Howard", "character": "Franklin Birch"}]', 'Denis Villeneuve', NULL, '2026-07-13 21:29:15.742939');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (141, 'tt8267604', 517814, 'Capernaum', 2018, '/mFnfTVADj8yOxwzprYOmTPselk8.jpg', '{18}', 'After running away from his negligent parents, committing a violent crime and being sentenced to five years in jail, a hardened, streetwise 12-year-old Lebanese boy sues his parents in protest of the life they have given him.', '[{"name": "Zain Al Rafeea", "character": "Zain"}, {"name": "Yordanos Shifera", "character": "Rahil"}, {"name": "Boluwatife Treasure Bankole", "character": "Yonas"}, {"name": "Kawsar Al Haddad", "character": "Souad"}, {"name": "Fadi Kamel Yousef", "character": "Selim"}]', 'Nadine Labaki', NULL, '2026-07-13 21:29:27.752039');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (122, 'tt1745960', 361743, 'Top Gun: Maverick', 2022, '/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', '{28,18}', 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.', '[{"name": "Tom Cruise", "character": "Capt. Pete ''Maverick'' Mitchell"}, {"name": "Miles Teller", "character": "Lt. Bradley ''Rooster'' Bradshaw"}, {"name": "Jennifer Connelly", "character": "Penny Benjamin"}, {"name": "Bashir Salahuddin", "character": "Wo-1. Bernie ''Hondo'' Coleman"}, {"name": "Jon Hamm", "character": "Adm. Beau ''Cyclone'' Simpson"}]', 'Joseph Kosinski', NULL, '2026-07-13 21:29:16.898453');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (123, 'tt0097576', 89, 'Indiana Jones and the Last Crusade', 1989, '/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg', '{12,28}', 'In 1938, an art collector appeals to eminent archaeologist Dr. Indiana Jones to embark on a search for the Holy Grail. Indy learns that a medieval historian has vanished while searching for it, and the missing man is his own father, Dr. Henry Jones Sr.. He sets out to rescue his father by following clues in the old man''s notebook, which his father had mailed to him before he went missing. Indy arrives in Venice, where he enlists the help of a beautiful academic, Dr. Elsa Schneider, along with Marcus Brody and Sallah. Together they must stop the Nazis from recovering the power of eternal life and taking over the world!', '[{"name": "Harrison Ford", "character": "Indiana Jones"}, {"name": "Sean Connery", "character": "Professor Henry Jones"}, {"name": "Denholm Elliott", "character": "Marcus Brody"}, {"name": "Alison Doody", "character": "Elsa"}, {"name": "John Rhys-Davies", "character": "Sallah"}]', 'Steven Spielberg', NULL, '2026-07-13 21:29:17.457906');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (124, 'tt0093058', 600, 'Full Metal Jacket', 1987, '/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg', '{18,10752}', 'A pragmatic U.S. Marine observes the dehumanizing effects the U.S.-Vietnam War has on his fellow recruits from their brutal boot camp training to the bloody street fighting in Hue.', '[{"name": "Matthew Modine", "character": "Pvt. Joker"}, {"name": "Adam Baldwin", "character": "Animal Mother"}, {"name": "Vincent D''Onofrio", "character": "Pvt. Pyle"}, {"name": "R. Lee Ermey", "character": "Gny. Sgt. Hartman"}, {"name": "Dorian Harewood", "character": "Eightball"}]', 'Stanley Kubrick', NULL, '2026-07-13 21:29:18.015988');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (125, 'tt0211915', 194, 'Amélie', 2001, '/nSxDa3M9aMvGVLoItzWTepQ5h5d.jpg', '{35,10749}', 'At a tiny Parisian café, the adorable yet painfully shy Amélie accidentally discovers a gift for helping others. Soon Amelie is spending her days as a matchmaker, guardian angel, and all-around do-gooder. But when she bumps into a handsome stranger, will she find the courage to become the star of her very own love story?', '[{"name": "Audrey Tautou", "character": "Amélie Poulain"}, {"name": "Mathieu Kassovitz", "character": "Nino Quincampoix"}, {"name": "Rufus", "character": "Raphaël Poulain"}, {"name": "Serge Merlin", "character": "Raymond Dufayel"}, {"name": "Jamel Debbouze", "character": "Lucien"}]', 'Jean-Pierre Jeunet', NULL, '2026-07-13 21:29:18.571054');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (126, 'tt1255953', 46738, 'Incendies', 2010, '/yH6DAQVgbyj72S66gN4WWVoTjuf.jpg', '{18,10752,9648}', 'A mother''s last wishes send twins Jeanne and Simon on a journey to Middle East in search of their tangled roots. Adapted from Wajdi Mouawad''s acclaimed play, Incendies tells the powerful and moving tale of two young adults'' voyage to the core of deep-rooted hatred, never-ending wars and enduring love.', '[{"name": "Lubna Azabal", "character": "Nawal"}, {"name": "Mélissa Désormeaux-Poulin", "character": "Jeanne Marwan"}, {"name": "Maxim Gaudette", "character": "Simon Marwan"}, {"name": "Rémy Girard", "character": "Notary Lebel"}, {"name": "Allen Altman", "character": "Notaire Maddad"}]', 'Denis Villeneuve', NULL, '2026-07-13 21:29:19.129548');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (127, 'tt8579674', 530915, '1917', 2019, '/iZf0KyrE25z1sage4SYFLCCrMi9.jpg', '{10752,36,18}', 'At the height of the First World War, two young British soldiers must cross enemy territory and deliver a message that will stop a deadly attack on hundreds of soldiers.', '[{"name": "George MacKay", "character": "Lance Corporal Schofield"}, {"name": "Dean-Charles Chapman", "character": "Lance Corporal Blake"}, {"name": "Mark Strong", "character": "Captain Smith"}, {"name": "Andrew Scott", "character": "Lieutenant Leslie"}, {"name": "Richard Madden", "character": "Lieutenant Blake"}]', 'Sam Mendes', NULL, '2026-07-13 21:29:19.691868');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (128, 'tt0457430', 1417, 'Pan''s Labyrinth', 2006, '/z7xXihu5wHuSMWymq5VAulPVuvg.jpg', '{14,18,10752}', 'In post–civil war Spain, 10-year-old Ofelia moves with her pregnant mother to live under the control of her cruel stepfather. Drawn into a mysterious labyrinth, she meets a faun who reveals that she may be a lost princess from an underground kingdom. To return to her true father, she must complete a series of surreal and perilous tasks that blur the line between reality and fantasy.', '[{"name": "Ivana Baquero", "character": "Ofelia"}, {"name": "Sergi López", "character": "Capitán Vidal"}, {"name": "Maribel Verdú", "character": "Mercedes"}, {"name": "Doug Jones", "character": "Fauno / Pale Man"}, {"name": "Ariadna Gil", "character": "Carmen"}]', 'Guillermo del Toro', NULL, '2026-07-13 21:29:20.253462');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (129, 'tt5074352', 360814, 'Dangal', 2016, '/cJRPOLEexI7qp2DKtFfCh7YaaUG.jpg', '{18,10751,35}', 'Dangal is an extraordinary true story based on the life of Mahavir Singh and his two daughters, Geeta and Babita Phogat. The film traces the inspirational journey of a father who trains his daughters to become world class wrestlers.', '[{"name": "Aamir Khan", "character": "Mahavir Singh Phogat"}, {"name": "Fatima Sana Shaikh", "character": "Geeta Phogat"}, {"name": "Sanya Malhotra", "character": "Babita Kumari"}, {"name": "Zaira Wasim", "character": "Young Geeta"}, {"name": "Suhani Bhatnagar", "character": "Young Babita"}]', 'Nitesh Tiwari', NULL, '2026-07-13 21:29:20.810244');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (130, 'tt0469494', 7345, 'There Will Be Blood', 2007, '/fa0RDkAlCec0STeMNAhPaF89q6U.jpg', '{18}', 'Ruthless silver miner, turned oil prospector, Daniel Plainview, moves to oil-rich California. Using his son to project a trustworthy, family-man image, Plainview cons local landowners into selling him their valuable properties for a pittance. However, local preacher Eli Sunday suspects Plainview''s motives and intentions, starting a slow-burning feud that threatens both their lives.', '[{"name": "Daniel Day-Lewis", "character": "Daniel Plainview"}, {"name": "Paul Dano", "character": "Paul Sunday / Eli Sunday"}, {"name": "Kevin J. O''Connor", "character": "Henry"}, {"name": "Ciarán Hinds", "character": "Fletcher Hamilton"}, {"name": "Dillon Freasier", "character": "H.W. Plainview"}]', 'Paul Thomas Anderson', NULL, '2026-07-13 21:29:21.370161');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (131, 'tt6966692', 490132, 'Green Book', 2018, '/7BsvSuDQuoqhWmU2fL7W2GOcZHU.jpg', '{18,35,36}', 'Tony Lip, a bouncer in 1962, is hired to drive pianist Don Shirley on a tour through the Deep South in the days when African Americans, forced to find alternate accommodations and services due to segregation laws below the Mason-Dixon Line, relied on a guide called The Negro Motorist Green Book.', '[{"name": "Viggo Mortensen", "character": "Tony Lip"}, {"name": "Mahershala Ali", "character": "Dr. Don Shirley"}, {"name": "Linda Cardellini", "character": "Dolores"}, {"name": "Sebastian Maniscalco", "character": "Johnny Venere"}, {"name": "Dimiter D. Marinov", "character": "Oleg"}]', 'Peter Farrelly', NULL, '2026-07-13 21:29:21.984164');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (132, 'tt0119488', 2118, 'L.A. Confidential', 1997, '/lWCgf5sD5FpMljjpkRhcC8pXcch.jpg', '{80,9648,53}', 'Three detectives in the corrupt and brutal L.A. police force of the 1950s use differing methods to uncover a conspiracy behind the shotgun slayings of the patrons at an all-night diner.', '[{"name": "Kevin Spacey", "character": "Jack Vincennes"}, {"name": "Russell Crowe", "character": "Wendell ''Bud'' White"}, {"name": "Guy Pearce", "character": "Edmund ''Ed'' Exley"}, {"name": "James Cromwell", "character": "Dudley Smith"}, {"name": "Kim Basinger", "character": "Lynn Bracken"}]', 'Curtis Hanson', NULL, '2026-07-13 21:29:22.564861');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (133, 'tt0986264', 7508, 'Like Stars on Earth', 2007, '/puHRt6Raovm5ujGCdwLWvRv4NHU.jpg', '{18}', 'Ishaan Awasthi is an eight-year-old whose world is filled with wonders that no one else seems to appreciate. Colours, fish, dogs, and kites don''t seem important to the adults, who are much more interested in things like homework, marks, and neatness. Ishaan cannot seem to get anything right in class; he is then sent to boarding school, where his life changes forever.', '[{"name": "Darsheel Safary", "character": "Ishaan Nandkishore Awasthi"}, {"name": "Aamir Khan", "character": "Ram Shankar Nikumbh"}, {"name": "Tisca Chopra", "character": "Maya Awasthi"}, {"name": "Vipin Sharma", "character": "Nandkishore Awasthi"}, {"name": "Tanay Chheda", "character": "Rajan Damodaran"}]', 'Aamir Khan', NULL, '2026-07-13 21:29:23.147549');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (134, 'tt0112641', 524, 'Casino', 1995, '/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg', '{80,18}', 'In Las Vegas, two best friends--a casino executive and a Mafia enforcer--compete for a gambling empire and a fast-living, fast-loving socialite.', '[{"name": "Robert De Niro", "character": "Sam \"Ace\" Rothstein"}, {"name": "Sharon Stone", "character": "Ginger McKenna"}, {"name": "Joe Pesci", "character": "Nicky Santoro"}, {"name": "James Woods", "character": "Lester Diamond"}, {"name": "Don Rickles", "character": "Billy Sherbert"}]', 'Martin Scorsese', NULL, '2026-07-13 21:29:23.722177');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (136, 'tt0084787', 1091, 'The Thing', 1982, '/tzGY49kseSE9QAKk47uuDGwnSCu.jpg', '{27,9648,878}', 'A research team in Antarctica is hunted by a shape-shifting alien that assumes the appearance of its victims.', '[{"name": "Kurt Russell", "character": "MacReady"}, {"name": "Wilford Brimley", "character": "Blair"}, {"name": "T.K. Carter", "character": "Nauls"}, {"name": "David Clennon", "character": "Palmer"}, {"name": "Keith David", "character": "Childs"}]', 'John Carpenter', NULL, '2026-07-13 21:29:24.849879');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (137, 'tt0347149', 4935, 'Howl''s Moving Castle', 2004, '/13kOl2v0nD2OLbVSHnHk8GUFEhO.jpg', '{14,16,12}', 'Sophie, a young milliner, is turned into an elderly woman by a witch who enters her shop and curses her. She encounters a wizard named Howl and gets caught up in his resistance to fighting for the king.', '[{"name": "Chieko Baisho", "character": "Sophie (voice)"}, {"name": "Takuya Kimura", "character": "Howl (voice)"}, {"name": "Akihiro Miwa", "character": "Witch of the Waste (voice)"}, {"name": "Tatsuya Gashuin", "character": "Calcifer (voice)"}, {"name": "Ryunosuke Kamiki", "character": "Markl (voice)"}]', 'Hayao Miyazaki', NULL, '2026-07-13 21:29:25.406723');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (139, 'tt0105695', 33, 'Unforgiven', 1992, '/54roTwbX9fltg85zjsmrooXAs12.jpg', '{37}', 'William Munny is a retired, once-ruthless killer turned gentle widower and hog farmer. To help support his two motherless children, he accepts one last bounty-hunter mission to find the men who brutalized a prostitute. Joined by his former partner and a cocky greenhorn, he takes on a corrupt sheriff.', '[{"name": "Clint Eastwood", "character": "William Munny"}, {"name": "Gene Hackman", "character": "''Little'' Bill Daggett"}, {"name": "Morgan Freeman", "character": "Ned Logan"}, {"name": "Jaimz Woolvett", "character": "The Schofield Kid"}, {"name": "Richard Harris", "character": "English Bob"}]', 'Clint Eastwood', NULL, '2026-07-13 21:29:26.544401');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (142, 'tt12042730', 687163, 'Project Hail Mary', 2026, '/yihdXomYb5kTeSivtFndMy5iDmf.jpg', '{878,12}', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '[{"name": "Ryan Gosling", "character": "Ryland Grace"}, {"name": "Sandra Hüller", "character": "Eva Stratt"}, {"name": "James Ortiz", "character": "Rocky (voice)"}, {"name": "Lionel Boyce", "character": "Carl"}, {"name": "Milana Vayntrub", "character": "Olesya Ilyukhina"}]', 'Phil Lord', NULL, '2026-07-13 21:29:28.329764');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (143, 'tt0363163', 613, 'Downfall', 2004, '/cP1ElGjBhbZAAqmueXjHDKlSwiP.jpg', '{18,36,10752}', 'In April of 1945, Germany stands at the brink of defeat with the Russian Army closing in from the east and the Allied Expeditionary Force attacking from the west. In Berlin, capital of the Third Reich, Adolf Hitler proclaims that Germany will still achieve victory and orders his generals and advisers to fight to the last man. When the end finally does come, and Hitler lies dead by his own hand, what is left of his military must find a way to end the killing that is the Battle of Berlin, and lay down their arms in surrender.', '[{"name": "Bruno Ganz", "character": "Adolf Hitler"}, {"name": "Alexandra Maria Lara", "character": "Traudl Junge"}, {"name": "Corinna Harfouch", "character": "Magda Goebbels"}, {"name": "Ulrich Matthes", "character": "Joseph Goebbels"}, {"name": "Juliane Köhler", "character": "Eva Braun"}]', 'Oliver Hirschbiegel', NULL, '2026-07-13 21:29:28.904691');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (148, 'tt20850406', 894803, 'Sita Ramam', 2022, '/t1O94ZBzsQXJihtVkrsStRLyUDR.jpg', '{36,10749,18}', 'Afreen, a rebellious Pakistani student sets ablaze the car of an Indian in London. Angered Afreen returns to Pakistan to ask for money from her grandfather that she has to pay in a month''s time as damages. However, she gets to know that he is no more and the only thing he has left for her is a letter-delivering task, written by Ram to Sita. As Afreen sets out to find Ram, there begins her journey of discovering the secret behind the 20-year-old letter.', '[{"name": "Dulquer Salmaan", "character": "Lieutenant Ram"}, {"name": "Mrunal Thakur", "character": "Sita Mahalakshmi"}, {"name": "Rashmika Mandanna", "character": "Afreen"}, {"name": "Sumanth", "character": "Brigadier Vishnu Sharma"}, {"name": "Gautham Vasudev Menon", "character": "Major Selvan"}]', 'Hanu Raghavapudi', NULL, '2026-07-13 21:29:31.761036');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (152, 'tt0080678', 1955, 'The Elephant Man', 1980, '/u0wpPYjuSt8DIe1Y3Vapnh8jcKE.jpg', '{18,36}', 'A Victorian surgeon rescues a heavily disfigured man being mistreated by his "owner" as a side-show freak. Behind his monstrous façade, there is revealed a person of great intelligence and sensitivity. Based on the true story of Joseph Merrick (called John Merrick in the film), a severely deformed man in 19th century London.', '[{"name": "Anthony Hopkins", "character": "Frederick Treves"}, {"name": "John Hurt", "character": "John Merrick"}, {"name": "Anne Bancroft", "character": "Mrs Kendal"}, {"name": "John Gielgud", "character": "Carr Gomm"}, {"name": "Wendy Hiller", "character": "Mothershead"}]', 'David Lynch', NULL, '2026-07-13 21:29:34.084231');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (154, 'tt0325980', 22, 'Pirates of the Caribbean: The Curse of the Black Pearl', 2003, '/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', '{12,14,28}', 'When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead.', '[{"name": "Johnny Depp", "character": "Jack Sparrow"}, {"name": "Geoffrey Rush", "character": "Barbossa"}, {"name": "Orlando Bloom", "character": "Will Turner"}, {"name": "Keira Knightley", "character": "Elizabeth Swann"}, {"name": "Jack Davenport", "character": "Norrington"}]', 'Gore Verbinski', NULL, '2026-07-13 21:29:35.277011');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (155, 'tt0434409', 752, 'V for Vendetta', 2005, '/1avD1JeaRiJX5M4ahPdZPypGoGN.jpg', '{28,53,878}', 'In a world in which Great Britain has become a fascist state, a masked vigilante known only as “V” conducts guerrilla warfare against the oppressive British government. When V rescues a young woman from the secret police, he finds in her an ally with whom he can continue his fight to free the people of Britain.', '[{"name": "Natalie Portman", "character": "Evey"}, {"name": "Hugo Weaving", "character": "V / William Rookwood"}, {"name": "Stephen Rea", "character": "Finch"}, {"name": "Stephen Fry", "character": "Deitrich"}, {"name": "John Hurt", "character": "Adam Sutler"}]', 'James McTeigue', NULL, '2026-07-13 21:29:35.839748');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (156, 'tt0264464', 640, 'Catch Me If You Can', 2002, '/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg', '{18,80}', 'A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.', '[{"name": "Leonardo DiCaprio", "character": "Frank Abagnale Jr."}, {"name": "Tom Hanks", "character": "Carl Hanratty"}, {"name": "Christopher Walken", "character": "Frank Abagnale"}, {"name": "Martin Sheen", "character": "Roger Strong"}, {"name": "Nathalie Baye", "character": "Paula Abagnale"}]', 'Steven Spielberg', NULL, '2026-07-13 21:29:36.438184');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (157, 'tt1392190', 76341, 'Mad Max: Fury Road', 2015, '/hA2ple9q4qnwxp3hKVNhroipsir.jpg', '{28,12,878}', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.', '[{"name": "Tom Hardy", "character": "Max Rockatansky"}, {"name": "Charlize Theron", "character": "Imperator Furiosa"}, {"name": "Nicholas Hoult", "character": "Nux"}, {"name": "Hugh Keays-Byrne", "character": "Immortan Joe"}, {"name": "Josh Helman", "character": "Slit"}]', 'George Miller', NULL, '2026-07-13 21:29:36.999124');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (158, 'tt2267998', 210577, 'Gone Girl', 2014, '/ts996lKsxvjkO2yiYG0ht4qAicO.jpg', '{9648,53,18}', 'With his wife''s disappearance having become the focus of an intense media circus, a man sees the spotlight turned on him when it''s suspected that he may not be innocent.', '[{"name": "Ben Affleck", "character": "Nick Dunne"}, {"name": "Rosamund Pike", "character": "Amy Dunne"}, {"name": "Neil Patrick Harris", "character": "Desi Collings"}, {"name": "Tyler Perry", "character": "Tanner Bolt"}, {"name": "Carrie Coon", "character": "Margo Dunne"}]', 'David Fincher', NULL, '2026-07-13 21:29:37.623042');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (159, 'tt24082438', 1058616, '20 Days in Mariupol', 2023, '/zIRp1IeuPh4GgqFCH3y0DQuY9xP.jpg', '{99,10752}', 'As the Russian invasion begins, a team of Ukrainian journalists trapped in the besieged city of Mariupol struggle to continue their work documenting the war''s atrocities.', '[{"name": "Mstyslav Chernov", "character": "Self - Narrator and Interviewer"}, {"name": "Evgeniy Maloletka", "character": "Self"}, {"name": "Liudmyla Amelkina", "character": "Self"}, {"name": "Zhanna Homa", "character": "Self"}, {"name": "Oleksandr Ivanov", "character": "Self"}]', 'Mstyslav Chernov', NULL, '2026-07-13 21:29:38.179512');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (160, 'tt0198781', 585, 'Monsters, Inc.', 2001, '/wFSpyMsp7H0ttERbxY7Trlv8xry.jpg', '{16,35,10751,14}', 'Lovable Sulley and his wisecracking sidekick Mike Wazowski are the top scare team at Monsters, Inc., the scream-processing factory in Monstropolis. When a little girl named Boo wanders into their world, it''s the monsters who are scared silly, and it''s up to Sulley and Mike to keep her out of sight and get her back home.', '[{"name": "John Goodman", "character": "Sullivan (voice)"}, {"name": "Billy Crystal", "character": "Mike (voice)"}, {"name": "Mary Gibbs", "character": "Boo (voice)"}, {"name": "Steve Buscemi", "character": "Randall (voice)"}, {"name": "James Coburn", "character": "Waternoose (voice)"}]', 'Pete Docter', NULL, '2026-07-13 21:29:38.747881');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (161, 'tt1201607', 12445, 'Harry Potter and the Deathly Hallows: Part 2', 2011, '/c54HpQmuwXjHq2C9wmoACjxoom3.jpg', '{12,14}', 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort''s formidable skills.', '[{"name": "Daniel Radcliffe", "character": "Harry Potter"}, {"name": "Emma Watson", "character": "Hermione Granger"}, {"name": "Rupert Grint", "character": "Ron Weasley"}, {"name": "Ralph Fiennes", "character": "Lord Voldemort"}, {"name": "Alan Rickman", "character": "Severus Snape"}]', 'David Yates', NULL, '2026-07-13 21:29:39.314842');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (162, 'tt10872600', 634649, 'Spider-Man: No Way Home', 2021, '/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', '{28,12,878}', 'Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.', '[{"name": "Tom Holland", "character": "Peter Parker / Spider-Man"}, {"name": "Zendaya", "character": "MJ"}, {"name": "Benedict Cumberbatch", "character": "Doctor Strange"}, {"name": "Jacob Batalon", "character": "Ned Leeds"}, {"name": "Jon Favreau", "character": "Happy Hogan"}]', 'Jon Watts', NULL, '2026-07-13 21:29:39.882693');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (163, 'tt0088247', 218, 'The Terminator', 1984, '/qvktm0BHcnmDpul4Hz01GIazWPr.jpg', '{28,53,878}', 'In the post-apocalyptic future, reigning tyrannical supercomputers teleport a cyborg assassin known as the "Terminator" back to 1984 to kill Sarah Connor, whose unborn son is destined to lead insurgents against 21st century mechanical hegemony. Meanwhile, the human-resistance movement dispatches a lone warrior to safeguard Sarah. Can he stop the virtually indestructible killing machine?', '[{"name": "Arnold Schwarzenegger", "character": "Terminator"}, {"name": "Michael Biehn", "character": "Kyle Reese"}, {"name": "Linda Hamilton", "character": "Sarah Connor"}, {"name": "Paul Winfield", "character": "Traxler"}, {"name": "Lance Henriksen", "character": "Vukovich"}]', 'James Cameron', NULL, '2026-07-13 21:29:40.472148');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (164, 'tt33014583', 1291608, 'Dhurandhar', 2025, '/snBOuXDdhmTvlzMUvP9Em3Pp1u1.jpg', '{28,80,53}', 'A mysterious traveler slips into the heart of Karachi''s underbelly and rises through its ranks with lethal precision, only to tear the notorious ISI-Underworld nexus apart from within.', '[{"name": "Ranveer Singh", "character": "Hamza Ali Mazari / Jaskirat Singh Rangi"}, {"name": "Akshaye Khanna", "character": "Rehman Dakait"}, {"name": "R. Madhavan", "character": "Ajay Sanyal"}, {"name": "Arjun Rampal", "character": "Major Iqbal"}, {"name": "Sanjay Dutt", "character": "SP Chaudhary Aslam"}]', 'Aditya Dhar', NULL, '2026-07-13 21:29:41.084589');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (165, 'tt2278388', 120467, 'The Grand Budapest Hotel', 2014, '/zOVCqKUzjFKqa1eDMcOzvXwthY4.jpg', '{35,18}', 'The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.', '[{"name": "Ralph Fiennes", "character": "M. Gustave"}, {"name": "F. Murray Abraham", "character": "Mr. Moustafa"}, {"name": "Mathieu Amalric", "character": "Serge X."}, {"name": "Adrien Brody", "character": "Dmitri"}, {"name": "Willem Dafoe", "character": "Jopling"}]', 'Wes Anderson', NULL, '2026-07-13 21:29:41.646081');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (166, 'tt0382932', 2062, 'Ratatouille', 2007, '/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', '{16,35,10751,14}', 'Remy, a rat, possesses a palate far more refined than that of his fellow comrades. He dreams of becoming a chef, one who creates rather than scavenges. When fate deposits him in the sewers beneath one of Paris’s most famous restaurants, he finds himself ideally placed to fulfill his dream. Forming an unusual alliance with a hapless young kitchen worker, Remy begins a daring culinary double life.  As Remy pursues his vision, he must navigate the suspicions of the calculating Head Chef Skinner, the disapproval of Remy’s own colony, and the foreboding presence of renowned food critic Anton Ego, who strikes fear in the hearts of chefs all throughout France.', '[{"name": "Patton Oswalt", "character": "Remy (voice)"}, {"name": "Ian Holm", "character": "Skinner (voice)"}, {"name": "Lou Romano", "character": "Linguini (voice)"}, {"name": "Brian Dennehy", "character": "Django (voice)"}, {"name": "Peter Sohn", "character": "Emile (voice)"}]', 'Brad Bird', NULL, '2026-07-13 21:29:42.224889');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (167, 'tt3315342', 263115, 'Logan', 2017, '/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg', '{28,18,878}', 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan''s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.', '[{"name": "Hugh Jackman", "character": "Logan / X-24"}, {"name": "Dafne Keen", "character": "Laura"}, {"name": "Patrick Stewart", "character": "Charles"}, {"name": "Elizabeth Rodriguez", "character": "Gabriela"}, {"name": "Boyd Holbrook", "character": "Pierce"}]', 'James Mangold', NULL, '2026-07-13 21:29:42.792134');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (168, 'tt2096673', 150540, 'Inside Out', 2015, '/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', '{16,10751,12,18,35}', 'When 11-year-old Riley moves to a new city, her Emotions team up to help her through the transition. Joy, Fear, Anger, Disgust and Sadness work together, but when Joy and Sadness get lost, they must journey through unfamiliar places to get back home.', '[{"name": "Amy Poehler", "character": "Joy (voice)"}, {"name": "Phyllis Smith", "character": "Sadness (voice)"}, {"name": "Richard Kind", "character": "Bing Bong (voice)"}, {"name": "Bill Hader", "character": "Fear (voice)"}, {"name": "Lewis Black", "character": "Anger (voice)"}]', 'Pete Docter', NULL, '2026-07-13 21:29:43.381035');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (169, 'tt0118715', 115, 'The Big Lebowski', 1998, '/3bv6WAp6BSxxYvB5ozKFUYuRA8C.jpg', '{35,80}', 'Jeffrey ''The Dude'' Lebowski, a Los Angeles slacker who only wants to bowl and drink White Russians, is mistaken for another Jeffrey Lebowski, a wheelchair-bound millionaire, and finds himself dragged into a strange series of events involving nihilists, adult film producers, ferrets, errant toes, and large sums of money.', '[{"name": "Jeff Bridges", "character": "The Dude"}, {"name": "John Goodman", "character": "Walter Sobchak"}, {"name": "Julianne Moore", "character": "Maude Lebowski"}, {"name": "Steve Buscemi", "character": "Donny"}, {"name": "David Huddleston", "character": "The Big Lebowski"}]', 'Joel Coen', NULL, '2026-07-13 21:29:43.982169');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (170, 'tt0892769', 10191, 'How to Train Your Dragon', 2010, '/ygGmAO60t8GyqUo9xYeYxSZAR3b.jpg', '{14,12,16,10751}', 'As the son of a Viking leader on the cusp of manhood, shy Hiccup Horrendous Haddock III faces a rite of passage: he must kill a dragon to prove his warrior mettle. But after downing a feared dragon, he realizes that he no longer wants to destroy it, and instead befriends the beast – which he names Toothless – much to the chagrin of his warrior father.', '[{"name": "Jay Baruchel", "character": "Hiccup (voice)"}, {"name": "Gerard Butler", "character": "Stoick (voice)"}, {"name": "Craig Ferguson", "character": "Gobber (voice)"}, {"name": "America Ferrera", "character": "Astrid (voice)"}, {"name": "Jonah Hill", "character": "Snotlout (voice)"}]', 'Chris Sanders', NULL, '2026-07-13 21:29:44.590918');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (171, 'tt0083658', 78, 'Blade Runner', 1982, '/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg', '{878,18,53}', 'In the smog-choked dystopian Los Angeles of 2019, blade runner Rick Deckard is called out of retirement to terminate a quartet of replicants who have escaped to Earth seeking their creator for a way to extend their short life spans.', '[{"name": "Harrison Ford", "character": "Deckard"}, {"name": "Rutger Hauer", "character": "Batty"}, {"name": "Sean Young", "character": "Rachael"}, {"name": "Edward James Olmos", "character": "Gaff"}, {"name": "M. Emmet Walsh", "character": "Bryant"}]', 'Ridley Scott', NULL, '2026-07-13 21:29:45.210593');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (172, 'tt10272386', 600354, 'The Father', 2020, '/pr3bEQ517uMb5loLvjFQi8uLAsp.jpg', '{18}', 'A man refuses all assistance from his daughter as he ages and, as he tries to make sense of his changing circumstances, he begins to doubt his loved ones, his own mind and even the fabric of his reality.', '[{"name": "Anthony Hopkins", "character": "Anthony"}, {"name": "Olivia Colman", "character": "Anne"}, {"name": "Mark Gatiss", "character": "The Man"}, {"name": "Olivia Williams", "character": "The Woman"}, {"name": "Imogen Poots", "character": "Laura"}]', 'Florian Zeller', NULL, '2026-07-13 21:29:45.775762');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (173, 'tt1205489', 13223, 'Gran Torino', 2008, '/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg', '{18}', 'Disgruntled Korean War veteran Walt Kowalski sets out to reform his neighbor, Thao Lor, a Hmong teenager who tried to steal Kowalski''s prized possession: a 1972 Gran Torino.', '[{"name": "Clint Eastwood", "character": "Walt Kowalski"}, {"name": "Christopher Carley", "character": "Father Janovich"}, {"name": "Bee Vang", "character": "Thao"}, {"name": "Ahney Her", "character": "Sue"}, {"name": "Brian Haley", "character": "Mitch Kowalski"}]', 'Clint Eastwood', NULL, '2026-07-13 21:29:46.335823');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (174, 'tt1305806', 25376, 'The Secret in Their Eyes', 2009, '/r3FctmAMk2tbrwxuWdpeLrZLwIz.jpg', '{9648,53,18}', 'Hoping to put to rest years of unease concerning a past case, retired criminal investigator Benjamín begins writing a novel based on the unsolved mystery of a newlywed’s rape and murder. With the help of a former colleague, judge Irene, he attempts to make sense of the past.', '[{"name": "Ricardo Darín", "character": "Benjamín Espósito"}, {"name": "Soledad Villamil", "character": "Irene Menéndez Hastings"}, {"name": "Pablo Rago", "character": "Ricardo Morales"}, {"name": "Javier Godino", "character": "Isidoro Gómez"}, {"name": "Guillermo Francella", "character": "Pablo Sandoval"}]', 'Juan José Campanella', NULL, '2026-07-13 21:29:46.916234');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (175, 'tt8503618', 556574, 'Hamilton', 2020, '/h1B7tW0t399VDjAcWJh8m87469b.jpg', '{36,18}', 'Presenting the tale of American founding father Alexander Hamilton, this filmed version of the original Broadway smash hit is the story of America then, told by America now.', '[{"name": "Lin-Manuel Miranda", "character": "Alexander Hamilton"}, {"name": "Leslie Odom Jr.", "character": "Aaron Burr"}, {"name": "Renée Elise Goldsberry", "character": "Angelica Schuyler"}, {"name": "Phillipa Soo", "character": "Eliza Hamilton"}, {"name": "Daveed Diggs", "character": "Marquis de Lafayette / Thomas Jefferson"}]', 'Thomas Kail', NULL, '2026-07-13 21:29:47.495995');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (176, 'tt4729430', 508965, 'Klaus', 2019, '/q125RHUDgR4gjwh1QkfYuJLYkL.jpg', '{16,10751,35}', 'A selfish postman and a reclusive toymaker form an unlikely friendship, delivering joy to a cold, dark town that desperately needs it.', '[{"name": "Jason Schwartzman", "character": "Jesper (voice)"}, {"name": "J.K. Simmons", "character": "Klaus (voice)"}, {"name": "Rashida Jones", "character": "Alva (voice)"}, {"name": "Joan Cusack", "character": "Mrs. Krum (voice)"}, {"name": "Norm Macdonald", "character": "Mogens (voice)"}]', 'Sergio Pablos', NULL, '2026-07-13 21:29:48.047557');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (177, 'tt0116282', 275, 'Fargo', 1996, '/rt7cpEr1uP6RTZykBFhBTcRaKvG.jpg', '{80,18,53}', 'Jerry, a small-town Minnesota car salesman is bursting at the seams with debt... but he''s got a plan. He''s going to hire two thugs to kidnap his wife in a scheme to collect a hefty ransom from his wealthy father-in-law. It''s going to be a snap and nobody''s going to get hurt... until people start dying. Enter Police Chief Marge, a coffee-drinking, parka-wearing - and extremely pregnant - investigator who''ll stop at nothing to get her man. And if you think her small-time investigative skills will give the crooks a run for their ransom... you betcha!', '[{"name": "Frances McDormand", "character": "Marge Gunderson"}, {"name": "William H. Macy", "character": "Jerry Lundegaard"}, {"name": "Steve Buscemi", "character": "Carl Showalter"}, {"name": "Peter Stormare", "character": "Gaear Grimsrud"}, {"name": "Harve Presnell", "character": "Wade Gustafson"}]', 'Joel Coen', NULL, '2026-07-13 21:29:48.606577');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (178, 'tt2024544', 76203, '12 Years a Slave', 2013, '/xdANQijuNrJaw1HA61rDccME4Tm.jpg', '{18,36}', 'In the pre-Civil War United States, Solomon Northup, a free black man from upstate New York, is abducted and sold into slavery. Facing cruelty as well as unexpected kindnesses Solomon struggles not only to stay alive, but to retain his dignity. In the twelfth year of his unforgettable odyssey, Solomon’s chance meeting with a Canadian abolitionist will forever alter his life.', '[{"name": "Chiwetel Ejiofor", "character": "Solomon Northup"}, {"name": "Michael Fassbender", "character": "Edwin Epps"}, {"name": "Lupita Nyong''o", "character": "Patsey"}, {"name": "Benedict Cumberbatch", "character": "William Ford"}, {"name": "Paul Dano", "character": "John Tibeats"}]', 'Steve McQueen', NULL, '2026-07-13 21:29:49.182471');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (179, 'tt0117951', 627, 'Trainspotting', 1996, '/1jUC02qsqS2NxBMFarbIhcQtazV.jpg', '{18,80}', 'Heroin addict Mark Renton stumbles through bad ideas and sobriety attempts with his unreliable friends --Sick Boy, Begbie, Spud and Tommy. He also has an underage girlfriend, Diane, along for the ride. After cleaning up and moving from Edinburgh to London, Mark finds he can''t escape the life he left behind as Begbie and Sick Boy come knocking.', '[{"name": "Ewan McGregor", "character": "Renton"}, {"name": "Ewen Bremner", "character": "Spud"}, {"name": "Jonny Lee Miller", "character": "Sick Boy"}, {"name": "Kevin McKidd", "character": "Tommy"}, {"name": "Robert Carlyle", "character": "Begbie"}]', 'Danny Boyle', NULL, '2026-07-13 21:29:49.778958');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (180, 'tt0405159', 70, 'Million Dollar Baby', 2004, '/jcfEqKdWF1zeyvECPqp3mkWLct2.jpg', '{18}', 'Despondent over a painful estrangement from his daughter, trainer Frankie Dunn isn''t prepared for boxer Maggie Fitzgerald to enter his life. But Maggie''s determined to go pro and to convince Dunn and his cohort to help her.', '[{"name": "Clint Eastwood", "character": "Frankie Dunn"}, {"name": "Hilary Swank", "character": "Maggie Fitzgerald"}, {"name": "Morgan Freeman", "character": "Eddie Scrap-Iron Dupris"}, {"name": "Jay Baruchel", "character": "Danger Barch"}, {"name": "Mike Colter", "character": "Big Willie Little"}]', 'Clint Eastwood', NULL, '2026-07-13 21:29:50.348742');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (182, 'tt9263550', 607145, 'Rocketry: The Nambi Effect', 2022, '/o7A1agEoXvwyyOmIbHnUhfnC34j.jpg', '{18,36}', 'The story of the great Indian rocket scientist, Shri Nambi Narayanan''s life, a true patriot, who was turned into a villain in the blink of an eye after being falsely accused of treason.', '[{"name": "R. Madhavan", "character": "Nambi Narayanan"}, {"name": "Simran", "character": "Meena"}, {"name": "Misha Ghoshal", "character": "Geeta Narayanan"}, {"name": "Jagan", "character": "Scientist"}, {"name": "Dinesh Prabhakar", "character": "L. D. Gopal"}]', 'R. Madhavan', NULL, '2026-07-13 21:29:51.483594');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (183, 'tt8110330', 645484, 'Dil Bechara', 2020, '/lMFjMrc8Bn0CQhtJDORfspXrWrK.jpg', '{18,10749}', 'Kizie and Manny, two ordinary people brought together by a tragic twist, embark on a bittersweet and extraordinary journey into the heart of that crazy little thing called ''life''.', '[{"name": "Sushant Singh Rajput", "character": "Immanuel ''Manny'' Rajkumar Junior"}, {"name": "Sanjana Sanghi", "character": "Kizie Basu"}, {"name": "Sahil Vaid", "character": "Jagdish Pandey (JP)"}, {"name": "Saswata Chatterjee", "character": "Kizie''s Father"}, {"name": "Swastika Mukherjee", "character": "Kizie''s Mother"}]', 'Mukesh Chhabra', NULL, '2026-07-13 21:29:52.095132');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (184, 'tt29623480', 1184918, 'The Wild Robot', 2024, '/eG9lz41mJqsI4J6ubMtVqD26q2J.jpg', '{10751,16,878,12}', 'After a shipwreck, an intelligent robot called Roz is stranded on an uninhabited island. To survive the harsh environment, Roz bonds with the island''s animals and cares for an orphaned baby goose.', '[{"name": "Lupita Nyong''o", "character": "Roz / Rummage (voice)"}, {"name": "Pedro Pascal", "character": "Fink (voice)"}, {"name": "Kit Connor", "character": "Brightbill (voice)"}, {"name": "Bill Nighy", "character": "Longneck (voice)"}, {"name": "Stephanie Hsu", "character": "Vontra (voice)"}]', 'Chris Sanders', NULL, '2026-07-13 21:29:52.659618');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (185, 'tt10295212', 599925, 'Shershaah', 2021, '/zGvFnwoXJKrYnKhoVPytqkqCJ8V.jpg', '{28,18,53,10752}', 'Inspired by the life of Captain Vikram Batra (PVC), the film celebrates his bravery, valiant spirit and honors his invaluable sacrifice during the Kargil War of 1999, at the age of 24.', '[{"name": "Sidharth Malhotra", "character": "Captain Vikram Batra / Vishal Batra"}, {"name": "Kiara Advani", "character": "Dimple Cheema"}, {"name": "Shataf Figar", "character": "Lt. Colonel Y.K. Joshi"}, {"name": "Shiv Panditt", "character": "Capt. Sanjeev Jamwal"}, {"name": "Nikitin Dheer", "character": "Major Ajay Jasrotia"}]', 'Vishnu Varadhan', NULL, '2026-07-13 21:29:53.217805');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (187, 'tt2119532', 324786, 'Hacksaw Ridge', 2016, '/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', '{18,36,10752}', 'WWII American Army Medic Desmond T. Doss, who served during the Battle of Okinawa, refuses to kill people and becomes the first Conscientious Objector in American history to receive the Congressional Medal of Honor.', '[{"name": "Andrew Garfield", "character": "Desmond T. Doss"}, {"name": "Sam Worthington", "character": "Captain Glover"}, {"name": "Vince Vaughn", "character": "Sgt Howell"}, {"name": "Teresa Palmer", "character": "Dorothy Schuttle"}, {"name": "Luke Bracey", "character": "Smitty Ryker"}]', 'Mel Gibson', NULL, '2026-07-13 21:29:54.36698');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (188, 'tt0097165', 207, 'Dead Poets Society', 1989, '/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg', '{18}', 'At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.', '[{"name": "Robin Williams", "character": "John Keating"}, {"name": "Robert Sean Leonard", "character": "Neil Perry"}, {"name": "Ethan Hawke", "character": "Todd Anderson"}, {"name": "Josh Charles", "character": "Knox Overstreet"}, {"name": "Gale Hansen", "character": "Charlie Dalton"}]', 'Peter Weir', NULL, '2026-07-13 21:29:54.938568');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (189, 'tt0120735', 100, 'Lock, Stock and Two Smoking Barrels', 1998, '/6pJB2t3MbQUy9m5pFIBHXLqnqNd.jpg', '{35,80}', 'A card shark and his unwillingly-enlisted friends need to make a lot of cash quick after losing a sketchy poker match. To do this they decide to pull a heist on a small-time gang who happen to be operating out of the flat next door.', '[{"name": "Vinnie Jones", "character": "Big Chris"}, {"name": "Jason Flemyng", "character": "Tom"}, {"name": "Dexter Fletcher", "character": "Soap"}, {"name": "Nick Moran", "character": "Eddy"}, {"name": "Jason Statham", "character": "Bacon"}]', 'Guy Ritchie', NULL, '2026-07-13 21:29:55.513111');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (190, 'tt5027774', 359940, 'Three Billboards Outside Ebbing, Missouri', 2017, '/bRYLt8fV82tdVoDppSFTZIcJiLN.jpg', '{80,18}', 'After seven months have passed without a culprit in her daughter''s murder case, Mildred Hayes makes a bold move, painting three signs leading into her town with a controversial message directed at Bill Willoughby, the town''s revered chief of police. When his second-in-command Officer Jason Dixon, an immature mother''s boy with a penchant for violence, gets involved, the battle between Mildred and Ebbing''s law enforcement is only exacerbated.', '[{"name": "Frances McDormand", "character": "Mildred"}, {"name": "Woody Harrelson", "character": "Willoughby"}, {"name": "Sam Rockwell", "character": "Dixon"}, {"name": "Abbie Cornish", "character": "Anne"}, {"name": "Lucas Hedges", "character": "Robbie"}]', 'Martin McDonagh', NULL, '2026-07-13 21:29:56.0896');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (219, 'tt0089881', 11645, 'Ran', 1985, '/dGgiXMWDcS5aJTBEFu7bmaQPNox.jpg', '{28,18,36}', 'Shakespeare''s King Lear is reimagined as a singular historical epic set in sixteenth-century Japan where an aging warlord divides his kingdom between his three sons.', '[{"name": "Tatsuya Nakadai", "character": "Lord Hidetora Ichimonji"}, {"name": "Akira Terao", "character": "Taro Takatora Ichimonji"}, {"name": "Jinpachi Nezu", "character": "Jiro Masatora Ichimonji"}, {"name": "Daisuke Ryū", "character": "Saburo Naotora Ichimonji"}, {"name": "Mieko Harada", "character": "Lady Kaede"}]', 'Akira Kurosawa', NULL, '2026-07-13 21:30:13.16612');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (192, 'tt1950186', 359724, 'Ford v Ferrari', 2019, '/dR1Ju50iudrOh3YgfwkAU1g2HZe.jpg', '{18,36,28}', 'American car designer Carroll Shelby and the British-born driver Ken Miles work together to battle corporate interference, the laws of physics, and their own personal demons to build a revolutionary race car for Ford Motor Company and take on the dominating race cars of Enzo Ferrari at the 24 Hours of Le Mans in France in 1966.', '[{"name": "Matt Damon", "character": "Carroll Shelby"}, {"name": "Christian Bale", "character": "Ken Miles"}, {"name": "Jon Bernthal", "character": "Lee Iacocca"}, {"name": "Caitríona Balfe", "character": "Mollie Miles"}, {"name": "Josh Lucas", "character": "Leo Beebe"}]', 'James Mangold', NULL, '2026-07-13 21:29:57.212692');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (193, 'tt1979320', 96721, 'Rush', 2013, '/95BDrWmcfJDEa2WCfjmLgi67jhi.jpg', '{18,28}', 'In the 1970s, a rivalry propels race car drivers Niki Lauda and James Hunt to fame and glory- until a horrible accident threatens to end it all.', '[{"name": "Chris Hemsworth", "character": "James Hunt"}, {"name": "Daniel Brühl", "character": "Niki Lauda"}, {"name": "Olivia Wilde", "character": "Suzy Miller"}, {"name": "Alexandra Maria Lara", "character": "Marlene Lauda"}, {"name": "Pierfrancesco Favino", "character": "Clay Regazzoni"}]', 'Ron Howard', NULL, '2026-07-13 21:29:57.783286');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (194, 'tt1895587', 314365, 'Spotlight', 2015, '/8DPGG400FgaFWaqcv11n8mRd2NG.jpg', '{18,36}', 'The true story of how the Boston Globe uncovered the massive scandal of child molestation and cover-up within the local Catholic Archdiocese, shaking the entire Catholic Church to its core.', '[{"name": "Mark Ruffalo", "character": "Michael Rezendes"}, {"name": "Michael Keaton", "character": "Walter ''Robby'' Robinson"}, {"name": "Rachel McAdams", "character": "Sacha Pfeiffer"}, {"name": "Liev Schreiber", "character": "Marty Baron"}, {"name": "John Slattery", "character": "Ben Bradlee, Jr."}]', 'Tom McCarthy', NULL, '2026-07-13 21:29:58.337735');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (195, 'tt1291584', 59440, 'Warrior', 2011, '/iM8n4nZJPR2abpnyZ36FUgHiRjr.jpg', '{18,28}', 'The youngest son of an alcoholic former boxer returns home, where he''s trained by his father for competition in a mixed martial arts tournament – a path that puts the fighter on a collision course with his estranged, older brother.', '[{"name": "Joel Edgerton", "character": "Brendan Conlon"}, {"name": "Tom Hardy", "character": "Tommy Conlon"}, {"name": "Nick Nolte", "character": "Paddy Conlon"}, {"name": "Jennifer Morrison", "character": "Tess Conlon"}, {"name": "Frank Grillo", "character": "Frank Campana"}]', 'Gavin O''Connor', NULL, '2026-07-13 21:29:58.896908');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (196, 'tt1454029', 50014, 'The Help', 2011, '/3kmfoWWEc9Vtyuaf9v5VipRgdjx.jpg', '{18}', 'Aibileen Clark is a middle-aged African-American maid who has spent her life raising white children and has recently lost her only son; Minny Jackson is an African-American maid who has often offended her employers despite her family''s struggles with money and her desperate need for jobs; and Eugenia "Skeeter" Phelan is a young white woman who has recently moved back home after graduating college to find out her childhood maid has mysteriously disappeared. These three stories intertwine to explain how life in Jackson, Mississippi revolves around "the help"; yet they are always kept at a certain distance because of racial lines.', '[{"name": "Emma Stone", "character": "Skeeter Phelan"}, {"name": "Viola Davis", "character": "Aibileen Clark"}, {"name": "Bryce Dallas Howard", "character": "Hilly Holbrook"}, {"name": "Octavia Spencer", "character": "Minny Jackson"}, {"name": "Jessica Chastain", "character": "Celia Foote"}]', 'Tate Taylor', NULL, '2026-07-13 21:29:59.45872');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (199, 'tt0092005', 235, 'Stand by Me', 1986, '/vz0w9BSehcqjDcJOjRaCk7fgJe7.jpg', '{80,18}', 'After learning that a boy their age has been accidentally killed near their rural homes, four boys decide to go see the body. Gordie, Vern, Chris, and Teddy encounter a mean junk man and a marsh full of leeches, but they also learn more about one another and their very different home lives. Just a lark at first, the boys'' adventure evolves into a defining event in their lives.', '[{"name": "Wil Wheaton", "character": "Gordie Lachance"}, {"name": "River Phoenix", "character": "Chris Chambers"}, {"name": "Corey Feldman", "character": "Teddy Duchamp"}, {"name": "Jerry O''Connell", "character": "Vern Tessio"}, {"name": "Kiefer Sutherland", "character": "Ace Merrill"}]', 'Rob Reiner', NULL, '2026-07-13 21:30:01.192181');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (200, 'tt0091251', 25237, 'Come and See', 1985, '/qNbMsKVzigERgJUbwf8pKyZogpb.jpg', '{18,10752}', 'The invasion of a village in Belarus by German forces sends young Florya into the forest to join the weary Resistance fighters, against his family''s wishes. There he meets a girl, Glasha, who accompanies him back to his village. On returning home, Florya finds his family and fellow peasants massacred. His continued survival amidst the brutal debris of war becomes increasingly nightmarish, a battle between despair and hope.', '[{"name": "Aleksei Kravchenko", "character": "Flyora Gayshun"}, {"name": "Olga Mironova", "character": "Glasha"}, {"name": "Liubomiras Laucevičius", "character": "Kosach"}, {"name": "Vladas Bagdonas", "character": "Rubezh"}, {"name": "Jüri Lumiste", "character": "Obersturmführer"}]', 'Elem Klimov', NULL, '2026-07-13 21:30:01.802443');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (201, 'tt3170832', 264644, 'Room', 2015, '/2hHDMeYyZjbGWn0BeNH1cTMxuM7.jpg', '{18,53}', 'Held captive for 7 years in an enclosed space, a woman and her young son finally gain their freedom, allowing the boy to experience the outside world for the first time.', '[{"name": "Brie Larson", "character": "Ma"}, {"name": "Jacob Tremblay", "character": "Jack"}, {"name": "Joan Allen", "character": "Nancy"}, {"name": "Sean Bridgers", "character": "Old Nick"}, {"name": "Tom McCamus", "character": "Leo"}]', 'Lenny Abrahamson', NULL, '2026-07-13 21:30:02.444616');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (204, 'tt0096283', 8392, 'My Neighbor Totoro', 1988, '/rtGDOeG9LzoerkDGZF9dnVeLppL.jpg', '{14,16,10751}', 'Two sisters move to the country with their father in order to be closer to their hospitalized mother, and discover the surrounding trees are inhabited by Totoros, magical spirits of the forest. When the youngest runs away from home, the older sister seeks help from the spirits to find her.', '[{"name": "Noriko Hidaka", "character": "Satsuki Kusakabe (voice)"}, {"name": "Chika Sakamoto", "character": "Mei Kusakabe (voice)"}, {"name": "Hitoshi Takagi", "character": "Totoro (voice)"}, {"name": "Shigesato Itoi", "character": "Tatsuo Kusakabe (voice)"}, {"name": "Sumi Shimamoto", "character": "Yasuko Kusakabe (voice)"}]', 'Hayao Miyazaki', NULL, '2026-07-13 21:30:04.16979');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (205, 'tt0081398', 1578, 'Raging Bull', 1980, '/1WV7WlTS8LI1L5NkCgjWT9GSW3O.jpg', '{18,36}', 'The life of boxer Jake LaMotta, whose violence and temper that led him to the top in the ring destroyed his life outside of it.', '[{"name": "Robert De Niro", "character": "Jake LaMotta"}, {"name": "Cathy Moriarty", "character": "Vickie LaMotta"}, {"name": "Joe Pesci", "character": "Joey LaMotta"}, {"name": "Frank Vincent", "character": "Salvy Batts"}, {"name": "Nicholas Colasanto", "character": "Tommy Como"}]', 'Martin Scorsese', NULL, '2026-07-13 21:30:04.742014');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (206, 'tt0395169', 205, 'Hotel Rwanda', 2004, '/p3pHw85UMZPegfMZBA6dZ06yarm.jpg', '{18,36,10752}', 'Inspired by true events, this film takes place in Rwanda in the 1990s when more than a million Tutsis were killed in a genocide that went mostly unnoticed by the rest of the world. Hotel owner Paul Rusesabagina houses over a thousand refuges in his hotel in attempt to save their lives.', '[{"name": "Don Cheadle", "character": "Paul Rusesabagina"}, {"name": "Sophie Okonedo", "character": "Tatiana Rusesabagina"}, {"name": "Nick Nolte", "character": "Colonel Oliver"}, {"name": "Fana Mokoena", "character": "General Bizimungu"}, {"name": "Desmond Dube", "character": "Dube"}]', 'Terry George', NULL, '2026-07-13 21:30:05.35446');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (208, 'tt0112471', 76, 'Before Sunrise', 1995, '/kf1Jb1c2JAOqjuzA3H4oDM263uB.jpg', '{18,10749}', 'An unexpected meeting on a train leads two travelers to spend an evening wandering through Vienna. As the night unfolds, they share stories and conversations about life and love, exploring new ideas while a quiet intimacy grows between them, knowing it may be their only night together.', '[{"name": "Ethan Hawke", "character": "Jesse"}, {"name": "Julie Delpy", "character": "Céline"}, {"name": "Andrea Eckert", "character": "Wife on Train"}, {"name": "Hanno Pöschl", "character": "Husband on Train"}, {"name": "Karl Bruckschwaiger", "character": "Guy on Bridge"}]', 'Richard Linklater', NULL, '2026-07-13 21:30:06.589757');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (210, 'tt7466810', 634120, '777 Charlie', 2022, '/qArPmXH0aWsT3SEtYl8XrU2Oz48.jpg', '{18,12,35}', 'Dharma is stuck in a rut with his negative and lonely lifestyle and spends each day in the comfort of his loneliness. A pup named Charlie who is naughty and energetic which is a complete contrast with the Dharma’s character enters his life and gives him a new perspective towards it.', '[{"name": "Rakshit Shetty", "character": "Dharma"}, {"name": "Raj B Shetty", "character": "Dr. Ashwin"}, {"name": "Bobby Simha", "character": "Vamsinadhan"}, {"name": "Sangeetha Sringeri", "character": "Devika"}, {"name": "Bhargavi Narayan"}]', 'Kiranraj K.', NULL, '2026-07-13 21:30:07.801316');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (211, 'tt1424432', 58496, 'Senna', 2010, '/nZbLCbRoP6iJq5sr8daHQzjnzFh.jpg', '{99}', 'The remarkable story of Brazilian racing driver Ayrton Senna, charting his physical and spiritual achievements on the track and off, his quest for perfection, and the mythical status he has since attained, is the subject of Senna, a documentary feature that spans the racing legend''s years as an F1 driver, from his opening season in 1984 to his untimely death a decade later.', '[{"name": "Ayrton Senna", "character": "Self (archive footage)"}, {"name": "Alain Prost", "character": "Self"}, {"name": "Frank Williams", "character": "Self"}, {"name": "Ron Dennis", "character": "Self"}, {"name": "Viviane Senna", "character": "Self"}]', 'Asif Kapadia', NULL, '2026-07-13 21:30:08.358497');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (212, 'tt10698680', 587412, 'K.G.F: Chapter 2', 2022, '/khNVygolU0TxLIDWff5tQlAhZ23.jpg', '{28,53,12,80}', 'The blood-soaked land of Kolar Gold Fields (KGF) has a new overlord now - Rocky, whose name strikes fear in the heart of his foes. His allies look up to Rocky as their Savior, the government sees him as a threat to law and order; enemies are clamoring for revenge and conspiring for his downfall. Bloodier battles and darker days await as Rocky continues on his quest for unchallenged supremacy.', '[{"name": "Yash", "character": "Raja Krishnappa Bairya ''Rocky''"}, {"name": "Sanjay Dutt", "character": "Adheera"}, {"name": "Raveena Tandon", "character": "Ramika Sen"}, {"name": "Srinidhi Shetty", "character": "Reena"}, {"name": "Archana Jois", "character": "Shanthamma"}]', 'Prashanth Neel', NULL, '2026-07-13 21:30:08.944983');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (213, 'tt1028532', 28178, 'Hachi: A Dog''s Tale', 2009, '/lsy3aEsEfYIHdLRk4dontZ4s85h.jpg', '{18,10751}', 'Professor Wilson discovers a lost Akita puppy on his way home. Despite objections from his wife, Hachi endears himself to the family and grows to be Parker''s loyal companion. As their bond grows deeper, a beautiful relationship unfolds.', '[{"name": "Richard Gere", "character": "Parker Wilson"}, {"name": "Joan Allen", "character": "Cate Wilson"}, {"name": "Sarah Roemer", "character": "Andy"}, {"name": "Cary-Hiroyuki Tagawa", "character": "Ken"}, {"name": "Erick Avari", "character": "Jasjeet"}]', 'Lasse Hallström', NULL, '2026-07-13 21:30:09.600145');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (214, 'tt6019206', 414419, 'Kill Bill: The Whole Bloody Affair', 2004, '/nSOJfWJCdVFZQwXQA7RXn7FIIiY.jpg', '{28,80}', 'A former assassin, known simply as The Bride, wakes from a coma four years after her jealous ex-lover Bill attempts to murder her on her wedding day. Fueled by an insatiable desire for revenge, she vows to get even with every person who contributed to the loss of her unborn child, her entire wedding party, and four years of her life.  After devising a hit list, The Bride sets off on her quest, enduring unspeakable injury and unscrupulous enemies.', '[{"name": "Uma Thurman", "character": "The Bride / Beatrix Kiddo (Black Mamba) / Mommy"}, {"name": "Lucy Liu", "character": "O-Ren Ishii (Cottonmouth)"}, {"name": "Vivica A. Fox", "character": "Vernita Green (Copperhead)"}, {"name": "Michael Madsen", "character": "Budd (Sidewinder)"}, {"name": "Daryl Hannah", "character": "Elle Driver (California Mountain Snake)"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:30:10.271776');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (215, 'tt11989890', 664280, 'David Attenborough: A Life on Our Planet', 2020, '/zSKwyUDKDHiFU5syTTvQRDcGBPS.jpg', '{99,18}', 'The story of life on our planet by the man who has seen more of the natural world than any other. In more than 90 years, Attenborough has visited every continent on the globe, exploring the wild places of our planet and documenting the living world in all its variety and wonder. Addressing the biggest challenges facing life on our planet, the film offers a powerful message of hope for future generations.', '[{"name": "David Attenborough", "character": "Self"}, {"name": "Max Hughes", "character": "Young David"}]', 'Alastair Fothergill', NULL, '2026-07-13 21:30:10.83778');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (217, 'tt33175825', 1333100, 'Attack on Titan: THE LAST ATTACK', 2024, '/wgwldDDlTDDMrluOMkpSA8lyKjv.jpg', '{16,28,12,18}', 'A colossal-sized omnibus film bringing together the last two episodes of Attack on Titan in the franchise''s first-ever theatrical experience. After venturing beyond the walls and separated from his comrades, Eren finds himself inspired by this new truth and plots the "Rumbling," a terrifying plan to eradicate every living thing in the world. With the fate of the world hanging in the balance, a motley crew of Eren''s former comrades and enemies scramble to halt his deadly mission. The only question is, can they stop him?', '[{"name": "Yuki Kaji", "character": "Eren Yeager (voice)"}, {"name": "Yui Ishikawa", "character": "Mikasa Ackerman (voice)"}, {"name": "Marina Inoue", "character": "Armin Arlert (voice)"}, {"name": "Hiroshi Kamiya", "character": "Levi Ackerman (voice)"}, {"name": "Yu Shimamura", "character": "Annie Leonheart (voice)"}]', 'Yuichiro Hayashi', NULL, '2026-07-13 21:30:12.025253');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (223, 'tt0353969', 11423, 'Memories of Murder', 2003, '/jcgUjx1QcupGzjntTVlnQ15lHqy.jpg', '{80,18,53}', 'A sadistic serial rapist and murderer of young women terrorizes a small province in 1980s South Korea. To prevent further crimes, three increasingly desperate detectives with conflicting methods race against time to unravel the violent mind of the killer in a futile effort to solve the case.', '[{"name": "Song Kang-ho", "character": "Detective Park Doo-man"}, {"name": "Kim Sang-kyung", "character": "Detective Seo Tae-yoon"}, {"name": "Kim Roi-ha", "character": "Detective Cho Yong-koo"}, {"name": "Song Jae-ho", "character": "Sergeant Shin Dong-chul"}, {"name": "Byun Hee-bong", "character": "Sergeant Koo Hee-bong"}]', 'Bong Joon Ho', NULL, '2026-07-13 21:30:15.443701');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (225, 'tt0848228', 24428, 'The Avengers', 2012, '/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', '{878,28,12}', 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!', '[{"name": "Robert Downey Jr.", "character": "Tony Stark / Iron Man"}, {"name": "Chris Evans", "character": "Steve Rogers / Captain America"}, {"name": "Mark Ruffalo", "character": "Bruce Banner / The Hulk"}, {"name": "Chris Hemsworth", "character": "Thor"}, {"name": "Scarlett Johansson", "character": "Natasha Romanoff / Black Widow"}]', 'Joss Whedon', NULL, '2026-07-13 21:30:16.598773');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (226, 'tt5323662', 378064, 'A Silent Voice: The Movie', 2016, '/tuFaWiqX0TXoWu7DGNcmX3UW7sT.jpg', '{16,18,10749}', 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?', '[{"name": "Miyu Irino", "character": "Shouya Ishida (voice)"}, {"name": "Saori Hayami", "character": "Shouko Nishimiya (voice)"}, {"name": "Aoi Yuuki", "character": "Yuzuru Nishimiya (voice)"}, {"name": "Kensho Ono", "character": "Tomohiro Nagatsuka (voice)"}, {"name": "Yuki Kaneko", "character": "Naoka Ueno (voice)"}]', 'Naoko Yamada', NULL, '2026-07-13 21:30:17.160003');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (227, 'tt0129167', 10386, 'The Iron Giant', 1999, '/ct04FCFLPImNG5thcPLRnVsZlmS.jpg', '{16,18,10751,878}', 'In the small town of Rockwell, Maine in October 1957, a giant metal machine befriends a nine-year-old boy and ultimately finds its humanity by unselfishly saving people from their own fears and prejudices.', '[{"name": "Jennifer Aniston", "character": "Annie Hughes (voice)"}, {"name": "Harry Connick Jr.", "character": "Dean McCoppin (voice)"}, {"name": "Vin Diesel", "character": "The Iron Giant (voice)"}, {"name": "James Gammon", "character": "Foreman Marv Loach / Floyd Turbeaux (voice)"}, {"name": "Cloris Leachman", "character": "Mrs. Lynley Tensedge (voice)"}]', 'Brad Bird', NULL, '2026-07-13 21:30:17.761987');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (228, 'tt0120338', 597, 'Titanic', 1997, '/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', '{18,10749}', '101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.', '[{"name": "Leonardo DiCaprio", "character": "Jack Dawson"}, {"name": "Kate Winslet", "character": "Rose DeWitt Bukater"}, {"name": "Billy Zane", "character": "Cal Hockley"}, {"name": "Kathy Bates", "character": "Molly Brown"}, {"name": "Frances Fisher", "character": "Ruth DeWitt Bukater"}]', 'James Cameron', NULL, '2026-07-13 21:30:18.342064');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (229, 'tt2015381', 118340, 'Guardians of the Galaxy', 2014, '/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg', '{28,878,12}', 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.', '[{"name": "Chris Pratt", "character": "Peter Quill"}, {"name": "Zoe Saldaña", "character": "Gamora"}, {"name": "Dave Bautista", "character": "Drax"}, {"name": "Vin Diesel", "character": "Groot (voice)"}, {"name": "Bradley Cooper", "character": "Rocket (voice)"}]', 'James Gunn', NULL, '2026-07-13 21:30:18.904408');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (231, 'tt1431045', 293660, 'Deadpool', 2016, '/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', '{28,12,35}', 'The origin story of former Special Forces operative turned mercenary Wade Wilson, who, after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', '[{"name": "Ryan Reynolds", "character": "Wade Wilson / Deadpool"}, {"name": "Morena Baccarin", "character": "Vanessa"}, {"name": "Ed Skrein", "character": "Ajax"}, {"name": "T.J. Miller", "character": "Weasel"}, {"name": "Gina Carano", "character": "Angel Dust"}]', 'Tim Miller', NULL, '2026-07-13 21:30:20.045445');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (233, 'tt32820897', 1311031, 'Demon Slayer: Kimetsu no Yaiba Infinity Castle', 2025, '/fWVSwgjpT2D78VUh6X8UBd2rorW.jpg', '{16,28,14}', 'The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.', '[{"name": "Natsuki Hanae", "character": "Tanjiro Kamado (voice)"}, {"name": "Takahiro Sakurai", "character": "Giyu Tomioka (voice)"}, {"name": "Akira Ishida", "character": "Akaza (voice)"}, {"name": "Hiro Shimono", "character": "Zenitsu Agatsuma (voice)"}, {"name": "Yoshimasa Hosoya", "character": "Kaigaku (voice)"}]', 'Haruo Sotozaki', NULL, '2026-07-13 21:30:21.226877');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (236, 'tt1160419', 438631, 'Dune', 2021, '/gDzOcq0pfeCeqMBwKIJlSmQpjkZ.jpg', '{878,12,10752}', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', '[{"name": "Timothée Chalamet", "character": "Paul Atreides"}, {"name": "Rebecca Ferguson", "character": "Lady Jessica Atreides"}, {"name": "Oscar Isaac", "character": "Duke Leto Atreides"}, {"name": "Jason Momoa", "character": "Duncan Idaho"}, {"name": "Stellan Skarsgård", "character": "Baron Vladimir Harkonnen"}]', 'Denis Villeneuve', NULL, '2026-07-13 21:30:22.928816');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (237, 'tt3659388', 286217, 'The Martian', 2015, '/fASz8A0yFE3QB6LgGoOfwvFSseV.jpg', '{878,18,12}', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.', '[{"name": "Matt Damon", "character": "Mark Watney"}, {"name": "Jessica Chastain", "character": "Melissa Lewis"}, {"name": "Kristen Wiig", "character": "Annie Montrose"}, {"name": "Jeff Daniels", "character": "Theodore \"Teddy\" Sanders"}, {"name": "Michael Peña", "character": "Rick Martinez"}]', 'Ridley Scott', NULL, '2026-07-13 21:30:23.514582');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (238, 'tt3011894', 265195, 'Wild Tales', 2014, '/bU7IUeTdYFOgeUPtwpWKQNhORMC.jpg', '{18,53,35}', 'Injustice and the demands of the world can cause stress for many people. Some of them, however, explode. This includes a waitress serving a grouchy loan shark, an altercation between two motorists, an ill-fated wedding reception, and a wealthy businessman who tries to buy his family out of trouble.', '[{"name": "Ricardo Darín", "character": "Simón Fisher (segment \"Bombita\")"}, {"name": "Leonardo Sbaraglia", "character": "Diego (segment \"El más fuerte\")"}, {"name": "Érica Rivas", "character": "Romina (segment \"Hasta que la muerte nos separe\")"}, {"name": "Oscar Martínez", "character": "Mauricio (segment \"La propuesta\")"}, {"name": "Rita Cortese", "character": "Cook (segment \"Las ratas\")"}]', 'Damián Szifron', NULL, '2026-07-13 21:30:24.086718');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (239, 'tt1663202', 281957, 'The Revenant', 2015, '/ji3ecJphATlVgWNY0B0RVXZizdf.jpg', '{37,18,12}', 'In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.', '[{"name": "Leonardo DiCaprio", "character": "Hugh Glass"}, {"name": "Tom Hardy", "character": "John Fitzgerald"}, {"name": "Domhnall Gleeson", "character": "Captain Andrew Henry"}, {"name": "Will Poulter", "character": "Jim Bridger"}, {"name": "Forrest Goodluck", "character": "Hawk"}]', 'Alejandro G. Iñárritu', NULL, '2026-07-13 21:30:24.645205');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (240, 'tt0246578', 141, 'Donnie Darko', 2001, '/j2AtZFsflxiluaNtajMTI0Avm8C.jpg', '{14,18,9648}', 'After narrowly escaping a bizarre accident, a troubled teenager is plagued by visions of a large bunny rabbit that manipulates him to commit a series of crimes.', '[{"name": "Jake Gyllenhaal", "character": "Donnie Darko"}, {"name": "Jena Malone", "character": "Gretchen Ross"}, {"name": "James Duval", "character": "Frank"}, {"name": "Drew Barrymore", "character": "Karen Pomeroy"}, {"name": "Beth Grant", "character": "Kitty Farmer"}]', 'Richard Kelly', NULL, '2026-07-13 21:30:25.208004');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (241, 'tt1010048', 12405, 'Slumdog Millionaire', 2008, '/5leCCi7ZF0CawAfM5Qo2ECKPprc.jpg', '{18,10749}', 'A teenager reflects on his life after being accused of cheating on the Indian version of "Who Wants to be a Millionaire?".', '[{"name": "Dev Patel", "character": "Older Jamal"}, {"name": "Freida Pinto", "character": "Older Latika"}, {"name": "Madhur Mittal", "character": "Older Salim"}, {"name": "Anil Kapoor", "character": "Prem"}, {"name": "Mahesh Manjrekar", "character": "Javed"}]', 'Danny Boyle', NULL, '2026-07-13 21:30:25.769398');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (242, 'tt0317705', 9806, 'The Incredibles', 2004, '/2LqaLgk4Z226KkgPJuiOQ58wvrm.jpg', '{28,12,16,10751}', 'Bob Parr has given up his superhero days to log in time as an insurance adjuster and raise his three children with his formerly heroic wife in suburbia. But when he receives a mysterious assignment, it''s time to get back into costume.', '[{"name": "Craig T. Nelson", "character": "Bob Parr / Mr. Incredible (voice)"}, {"name": "Holly Hunter", "character": "Helen Parr / Elastigirl (voice)"}, {"name": "Sarah Vowell", "character": "Violet Parr (voice)"}, {"name": "Spencer Fox", "character": "Dashiell ''Dash'' Parr (voice)"}, {"name": "Jason Lee", "character": "Buddy Pine / Syndrome (voice)"}]', 'Brad Bird', NULL, '2026-07-13 21:30:26.343128');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (243, 'tt4849438', 350312, 'Bāhubali 2: The Conclusion', 2017, '/21sC2assImQIYCEDA84Qh9d1RsK.jpg', '{28,12,14}', 'When Mahendra, the son of Bāhubali, learns about his heritage, he begins to look for answers. His story is juxtaposed with past events that unfolded in the Mahishmati Kingdom.', '[{"name": "Prabhas", "character": "Amarendra Bāhubali / Mahendra Bāhubali ''Shivudu''"}, {"name": "Rana Daggubati", "character": "Bhallaladeva"}, {"name": "Anushka Shetty", "character": "Devasena"}, {"name": "Sathyaraj", "character": "Karikala Kattappa Nadar"}, {"name": "Nassar", "character": "Bijjaladeva"}]', 'S. S. Rajamouli', NULL, '2026-07-13 21:30:26.907753');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (244, 'tt0947798', 44214, 'Black Swan', 2010, '/viWheBd44bouiLCHgNMvahLThqx.jpg', '{18,53,27}', 'A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s "Swan Lake."', '[{"name": "Natalie Portman", "character": "Nina Sayers / The Swan Queen"}, {"name": "Mila Kunis", "character": "Lily / The Black Swan"}, {"name": "Vincent Cassel", "character": "Thomas Leroy / The Gentleman"}, {"name": "Barbara Hershey", "character": "Erica Sayers / The Queen"}, {"name": "Winona Ryder", "character": "Beth Macintyre / The Dying Swan"}]', 'Darren Aronofsky', NULL, '2026-07-13 21:30:27.511509');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (245, 'tt2084970', 205596, 'The Imitation Game', 2014, '/zSqJ1qFq8NXFfi7JeIYMlzyR0dx.jpg', '{36,18,53,10752}', 'Based on the real life story of legendary cryptanalyst Alan Turing, the film portrays the nail-biting race against time by Turing and his brilliant team of code-breakers at Britain''s top-secret Government Code and Cypher School at Bletchley Park, during the darkest days of World War II.', '[{"name": "Benedict Cumberbatch", "character": "Alan Turing"}, {"name": "Keira Knightley", "character": "Joan Clarke"}, {"name": "Matthew Goode", "character": "Hugh Alexander"}, {"name": "Rory Kinnear", "character": "Detective Robert Nock"}, {"name": "Allen Leech", "character": "John Cairncross"}]', 'Morten Tyldum', NULL, '2026-07-13 21:30:28.070159');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (246, 'tt0378194', 393, 'Kill Bill: Vol. 2', 2004, '/2yhg0mZQMhDyvUQ4rG1IZ4oIA8L.jpg', '{28,80,53}', 'The Bride unwaveringly continues on her roaring rampage of revenge against the band of assassins who had tried to kill her and her unborn child. She visits each of her former associates one-by-one, checking off the victims on her Death List Five until there''s nothing left to do … but kill Bill.', '[{"name": "Uma Thurman", "character": "Beatrix Kiddo / The Bride / ''Black Mamba'' / Mommy"}, {"name": "David Carradine", "character": "Bill ''Snake Charmer''"}, {"name": "Daryl Hannah", "character": "Elle Driver ''California Mountain Snake''"}, {"name": "Michael Madsen", "character": "Budd ''Sidewinder''"}, {"name": "Gordon Liu Chia-Hui", "character": "Johnny Mo / Pai Mei"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:30:28.65402');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (247, 'tt0401792', 187, 'Sin City', 2005, '/i66G50wATMmPrvpP95f0XP6ZdVS.jpg', '{80,53}', 'Welcome to Sin City. This town beckons to the tough, the corrupt, the brokenhearted. Some call it dark… Hard-boiled. Then there are those who call it home- Crooked cops, sexy dames, desperate vigilantes. Some are seeking revenge, others lust after redemption, and then there are those hoping for a little of both. A universe of unlikely and reluctant heroes still trying to do the right thing in a city that refuses to care.', '[{"name": "Bruce Willis", "character": "Hartigan"}, {"name": "Jessica Alba", "character": "Nancy"}, {"name": "Clive Owen", "character": "Dwight"}, {"name": "Mickey Rourke", "character": "Marv"}, {"name": "Rutger Hauer", "character": "Cardinal Roark"}]', 'Robert Rodriguez', NULL, '2026-07-13 21:30:29.249786');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (249, 'tt0113247', 406, 'La Haine', 1995, '/hY4exng4s29RzDbtQInjx9MA3PZ.jpg', '{18}', 'After a chaotic night of rioting in a marginal suburb of Paris, three young friends, Vinz, Hubert and Saïd, wander around unoccupied waiting for news about the state of health of a mutual friend who has been seriously injured when confronting the police.', '[{"name": "Vincent Cassel", "character": "Vinz"}, {"name": "Hubert Koundé", "character": "Hubert"}, {"name": "Saïd Taghmaoui", "character": "Saïd"}, {"name": "Abdel Ahmed Ghili", "character": "Abdel"}, {"name": "Solo", "character": "Santo"}]', 'Mathieu Kassovitz', NULL, '2026-07-13 21:30:30.377814');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (250, 'tt3783958', 313369, 'La La Land', 2016, '/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', '{35,18,10749}', 'Mia, an aspiring actress, serves lattes to movie stars in between auditions and Sebastian, a jazz musician, scrapes by playing cocktail party gigs in dingy bars, but as success mounts they are faced with decisions that begin to fray the fragile fabric of their love affair, and the dreams they worked so hard to maintain in each other threaten to rip them apart.', '[{"name": "Ryan Gosling", "character": "Sebastian"}, {"name": "Emma Stone", "character": "Mia"}, {"name": "John Legend", "character": "Keith"}, {"name": "Rosemarie DeWitt", "character": "Laura"}, {"name": "Finn Wittrock", "character": "Greg"}]', 'Damien Chazelle', NULL, '2026-07-13 21:30:30.93418');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (251, 'tt2338151', 297222, 'PK', 2014, '/z2x2Y4tncefsIU7h82gmUM5vnBJ.jpg', '{35,18,878}', 'A stranger in the city asks questions no one has asked before. Known only by his initials, the man''s innocent questions and childlike curiosity take him on a journey of love, laughter and letting go.', '[{"name": "Aamir Khan", "character": "PK"}, {"name": "Anushka Sharma", "character": "Jagat ''Jaggu'' Janani Sahni"}, {"name": "Saurabh Shukla", "character": "Tapasvi Maharaj"}, {"name": "Boman Irani", "character": "Cherry Bajwa"}, {"name": "Sushant Singh Rajput", "character": "Sarfraz Yousuf"}]', 'Rajkumar Hirani', NULL, '2026-07-13 21:30:31.513797');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (252, 'tt1856101', 335984, 'Blade Runner 2049', 2017, '/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', '{878,18}', 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what''s left of society into chaos. K''s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.', '[{"name": "Ryan Gosling", "character": "''K''"}, {"name": "Harrison Ford", "character": "Rick Deckard"}, {"name": "Ana de Armas", "character": "Joi"}, {"name": "Dave Bautista", "character": "Sapper Morton"}, {"name": "Robin Wright", "character": "Lieutenant Joshi"}]', 'Denis Villeneuve', NULL, '2026-07-13 21:30:32.07737');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (253, 'tt0381061', 36557, 'Casino Royale', 2006, '/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', '{12,28,53}', 'Le Chiffre, a banker to the world''s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.', '[{"name": "Daniel Craig", "character": "James Bond"}, {"name": "Eva Green", "character": "Vesper Lynd"}, {"name": "Mads Mikkelsen", "character": "Le Chiffre"}, {"name": "Judi Dench", "character": "M"}, {"name": "Jeffrey Wright", "character": "Felix Leiter"}]', 'Martin Campbell', NULL, '2026-07-13 21:30:32.68286');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (254, 'tt0107048', 137, 'Groundhog Day', 1993, '/gCgt1WARPZaXnq523ySQEUKinCs.jpg', '{10749,14,35}', 'A cynical TV weatherman, along with his idealistic producer and his sardonic cameraman, is sent to report on Groundhog Day in the small town of Punxsutawney, where he finds himself repeating the same day over and over.', '[{"name": "Bill Murray", "character": "Phil Connors"}, {"name": "Andie MacDowell", "character": "Rita Hanson"}, {"name": "Chris Elliott", "character": "Larry"}, {"name": "Stephen Tobolowsky", "character": "Ned Ryerson"}, {"name": "Brian Doyle-Murray", "character": "Buster Green"}]', 'Harold Ramis', NULL, '2026-07-13 21:30:33.279179');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (255, 'tt1504320', 45269, 'The King''s Speech', 2010, '/pVNKXVQFukBaCz6ML7GH3kiPlQP.jpg', '{18,36}', 'The King''s Speech tells the story of the man who became King George VI, the father of Queen Elizabeth II. After his brother abdicates, George (''Bertie'') reluctantly assumes the throne. Plagued by a dreaded stutter and considered unfit to be king, Bertie engages the help of an unorthodox speech therapist named Lionel Logue. Through a set of unexpected techniques, and as a result of an unlikely friendship, Bertie is able to find his voice and boldly lead the country into war.', '[{"name": "Colin Firth", "character": "King George VI"}, {"name": "Geoffrey Rush", "character": "Lionel Logue"}, {"name": "Helena Bonham Carter", "character": "Queen Elizabeth"}, {"name": "Guy Pearce", "character": "King Edward VIII"}, {"name": "Timothy Spall", "character": "Winston Churchill"}]', 'Tom Hooper', NULL, '2026-07-13 21:30:33.842766');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (256, 'tt1798709', 152601, 'Her', 2013, '/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg', '{10749,878,18}', 'In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.', '[{"name": "Joaquin Phoenix", "character": "Theodore"}, {"name": "Scarlett Johansson", "character": "Samantha (voice)"}, {"name": "Lynn Adrianna", "character": "Letter Writer #1"}, {"name": "Lisa Renee Pitts", "character": "Letter Writer #2"}, {"name": "Gabe Gomez", "character": "Letter Writer #3"}]', 'Spike Jonze', NULL, '2026-07-13 21:30:34.475317');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (257, 'tt0758758', 5915, 'Into the Wild', 2007, '/jnLnLYP5pGDfri04gxtAqAvkHMw.jpg', '{12,18}', 'After graduating from Emory University in 1992, top student and athlete Christopher McCandless abandons his possessions, gives his entire $24,000 savings account to charity, and hitchhikes to Alaska to live in the wilderness.', '[{"name": "Emile Hirsch", "character": "Christopher McCandless / Alexander Supertramp"}, {"name": "Marcia Gay Harden", "character": "Billie McCandless"}, {"name": "William Hurt", "character": "Walt McCandless"}, {"name": "Jena Malone", "character": "Carine McCandless / Additional Narration (voice)"}, {"name": "Brian H. Dierker", "character": "Rainey"}]', 'Sean Penn', NULL, '2026-07-13 21:30:35.03372');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (258, 'tt0440963', 2503, 'The Bourne Ultimatum', 2007, '/15rMz5MRXFp7CP4VxhjYw4y0FUn.jpg', '{28,18,9648,53}', 'Bourne is brought out of hiding once again by reporter Simon Ross who is trying to unveil Operation Blackbriar, an upgrade to Project Treadstone, in a series of newspaper columns. Information from the reporter stirs a new set of memories, and Bourne must finally uncover his dark past while dodging The Company''s best efforts to eradicate him.', '[{"name": "Matt Damon", "character": "Jason Bourne"}, {"name": "Julia Stiles", "character": "Nicky Parsons"}, {"name": "David Strathairn", "character": "Noah Vosen"}, {"name": "Scott Glenn", "character": "CIA Director Ezra Kramer"}, {"name": "Paddy Considine", "character": "Simon Ross"}]', 'Paul Greengrass', NULL, '2026-07-13 21:30:35.6348');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (425, 'tt3460252', 273248, 'The Hateful Eight', 2015, '/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg', '{18,9648,37}', 'Bounty hunters seek shelter from a raging blizzard and get caught up in a plot of betrayal and deception.', '[{"name": "Samuel L. Jackson", "character": "Major Marquis Warren"}, {"name": "Kurt Russell", "character": "John ''The Hangman'' Ruth"}, {"name": "Jennifer Jason Leigh", "character": "Daisy Domergue"}, {"name": "Walton Goggins", "character": "Sheriff Chris Mannix"}, {"name": "Demián Bichir", "character": "Bob"}]', 'Quentin Tarantino', NULL, '2026-07-13 21:32:13.116853');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (260, 'tt0114746', 63, 'Twelve Monkeys', 1995, '/gt3iyguaCIw8DpQZI1LIN5TohM2.jpg', '{878,53,9648}', 'In the year 2035, convict James Cole reluctantly volunteers to be sent back in time to discover the origin of a deadly virus that wiped out nearly all of the earth''s population and forced the survivors into underground communities. But when Cole is mistakenly sent to 1990 instead of 1996, he''s arrested and locked up in a mental hospital. There he meets psychiatrist Dr. Kathryn Railly and the son of a famous virus expert who may hold the key to the Army of the 12 Monkeys; thought to be responsible for unleashing the killer disease.', '[{"name": "Bruce Willis", "character": "James Cole"}, {"name": "Madeleine Stowe", "character": "Dr. Kathryn Railly"}, {"name": "Brad Pitt", "character": "Jeffrey Goines"}, {"name": "Christopher Plummer", "character": "Dr. Goines"}, {"name": "David Morse", "character": "Dr. Peters"}]', 'Terry Gilliam', NULL, '2026-07-13 21:30:36.759243');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (261, 'tt2948356', 269149, 'Zootopia', 2016, '/hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg', '{16,12,10751,35}', 'Determined to prove herself, Officer Judy Hopps, the first bunny on Zootopia''s police force, jumps at the chance to crack her first case - even if it means partnering with scam-artist fox Nick Wilde to solve the mystery.', '[{"name": "Ginnifer Goodwin", "character": "Judy Hopps (voice)"}, {"name": "Jason Bateman", "character": "Nick Wilde (voice)"}, {"name": "Idris Elba", "character": "Chief Bogo (voice)"}, {"name": "Jenny Slate", "character": "Bellwether (voice)"}, {"name": "Nate Torrence", "character": "Clawhauser (voice)"}]', 'Byron Howard', NULL, '2026-07-13 21:30:37.322416');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (262, 'tt9179430', 743563, 'Vikram', 2022, '/774UV1aCURb4s4JfEFg3IEMu5Zj.jpg', '{28,80,53}', 'Amar is assigned to investigate a case of serial killings. When Amar investigates the case, he realizes it is not what it seems to be and following down this path will lead to nothing but war between everyone involved.', '[{"name": "Kamal Haasan", "character": "Karnan / Arun Kumar Vikram"}, {"name": "Suriya", "character": "Rolex"}, {"name": "Fahadh Faasil", "character": "Amar"}, {"name": "Vijay Sethupathi", "character": "Sandhanam"}, {"name": "Narain", "character": "Bejoy"}]', 'Lokesh Kanagaraj', NULL, '2026-07-13 21:30:37.916841');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (263, 'tt0450259', 1372, 'Blood Diamond', 2006, '/tnLxPpajkbVdbQl5B9CuD7sSpz9.jpg', '{18,53,28}', 'An ex-mercenary turned smuggler. A Mende fisherman. Amid the explosive civil war overtaking 1999 Sierra Leone, these men join for two desperate missions: recovering a rare pink diamond of immense value and rescuing the fisherman''s son, conscripted as a child soldier into the brutal rebel forces ripping a swath of torture and bloodshed countrywide.', '[{"name": "Leonardo DiCaprio", "character": "Danny Archer"}, {"name": "Djimon Hounsou", "character": "Solomon Vandy"}, {"name": "Jennifer Connelly", "character": "Maddy Bowen"}, {"name": "Kagiso Kuypers", "character": "Dia Vandy"}, {"name": "Arnold Vosloo", "character": "Colonel Coetzee"}]', 'Edward Zwick', NULL, '2026-07-13 21:30:38.486217');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (264, 'tt0454921', 1402, 'The Pursuit of Happyness', 2006, '/lBYOKAMcxIvuk9s9hMuecB9dPBV.jpg', '{18}', 'A struggling salesman takes custody of his son as he''s poised to begin a life-changing professional career.', '[{"name": "Will Smith", "character": "Chris Gardner"}, {"name": "Jaden Smith", "character": "Christopher"}, {"name": "Thandiwe Newton", "character": "Linda"}, {"name": "Brian Howe", "character": "Jay Twistle"}, {"name": "James Karen", "character": "Martin Frohm"}]', 'Gabriele Muccino', NULL, '2026-07-13 21:30:39.050399');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (266, 'tt4016934', 290098, 'The Handmaiden', 2016, '/dLlH4aNHdnmf62umnInL8xPlPzw.jpg', '{53,18,10749}', '1930s Korea, in the period of Japanese occupation, a new girl, Sook-hee, is hired as a handmaiden to a Japanese heiress, Hideko, who lives a secluded life on a large countryside estate with her domineering Uncle Kouzuki. But the maid has a secret. She is a pickpocket recruited by a swindler posing as a Japanese Count to help him seduce the Lady to steal her fortune.', '[{"name": "Kim Min-hee", "character": "Lady Hideko"}, {"name": "Kim Tae-ri", "character": "Sook-hee"}, {"name": "Ha Jung-woo", "character": "Count Fujiwara"}, {"name": "Cho Jin-woong", "character": "Uncle Kouzuki"}, {"name": "Kim Hae-sook", "character": "Ms. Sasaki"}]', 'Park Chan-wook', NULL, '2026-07-13 21:30:40.220641');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (268, 'tt0095953', 380, 'Rain Man', 1988, '/iTNHwO896WKkaoPtpMMS74d8VNi.jpg', '{18}', 'When car dealer Charlie Babbitt learns that his estranged father has died, he returns home to Cincinnati, where he discovers that he has a savant older brother named Raymond and that his father''s $3 million fortune is being left to the mental institution in which Raymond lives. Motivated by his father''s money, Charlie checks Raymond out of the facility in order to return with him to Los Angeles. The brothers'' cross-country trip ends up changing both their lives.', '[{"name": "Dustin Hoffman", "character": "Raymond Babbitt"}, {"name": "Tom Cruise", "character": "Charlie Babbitt"}, {"name": "Valeria Golino", "character": "Susanna"}, {"name": "Gerald R. Molen", "character": "Dr. Bruner"}, {"name": "Jack Murdock", "character": "John Mooney"}]', 'Barry Levinson', NULL, '2026-07-13 21:30:41.341194');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (269, 'tt0107207', 7984, 'In the Name of the Father', 1993, '/3NcIkKxaO2SmRVsG1v50XhtmL0f.jpg', '{18}', 'A small-time Belfast thief, Gerry Conlon, is wrongly convicted of an IRA bombing in London, along with his father and friends, and spends 15 years in prison fighting to prove his innocence.', '[{"name": "Daniel Day-Lewis", "character": "Gerry Conlon"}, {"name": "Pete Postlethwaite", "character": "Giuseppe Conlon"}, {"name": "Emma Thompson", "character": "Gareth Peirce"}, {"name": "John Lynch", "character": "Paul Hill"}, {"name": "Corin Redgrave", "character": "Robert Dixon"}]', 'Jim Sheridan', NULL, '2026-07-13 21:30:41.904852');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (270, 'tt0978762', 24238, 'Mary and Max', 2009, '/ebmsM382m9IClLUzKYY2U5biFwM.jpg', '{16,35,18}', 'A tale of friendship between two unlikely pen pals: Mary, a lonely, eight-year-old girl living in the suburbs of Melbourne, and Max, a forty-four-year old, severely obese man living in New York.', '[{"name": "Toni Collette", "character": "Mary (voice)"}, {"name": "Philip Seymour Hoffman", "character": "Max (voice)"}, {"name": "Barry Humphries", "character": "Narrator (voice)"}, {"name": "Eric Bana", "character": "Damien (voice)"}, {"name": "Bethany Whitmore", "character": "Young Mary (voice)"}]', 'Adam Elliot', NULL, '2026-07-13 21:30:42.508074');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (273, 'tt0101414', 10020, 'Beauty and the Beast', 1991, '/hUJ0UvQ5tgE2Z9WpfuduVSdiCiU.jpg', '{10749,10751,16,14}', 'Follow the adventures of Belle, a bright young woman who finds herself in the castle of a prince who''s been turned into a mysterious beast. With the help of the castle''s enchanted staff, Belle soon learns the most important lesson of all -- that true beauty comes from within.', '[{"name": "Paige O''Hara", "character": "Belle (voice)"}, {"name": "Robby Benson", "character": "Beast (voice)"}, {"name": "Richard White", "character": "Gaston (voice)"}, {"name": "Jerry Orbach", "character": "Lumiere (voice)"}, {"name": "David Ogden Stiers", "character": "Cogsworth (voice)"}]', 'Gary Trousdale', NULL, '2026-07-13 21:30:44.261143');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (274, 'tt0103639', 812, 'Aladdin', 1992, '/eLFfl7vS8dkeG1hKp5mwbm37V83.jpg', '{16,10751,12,14,10749}', 'In the boorish city of Agrabah, kind-hearted street urchin Aladdin and Princess Jasmine fall in love, although she can only marry a prince. He and power-hungry Grand Vizier Jafar vie for a magic lamp that can fulfill their wishes.', '[{"name": "Scott Weinger", "character": "Aladdin (voice)"}, {"name": "Robin Williams", "character": "Genie / Peddler (voice)"}, {"name": "Linda Larkin", "character": "Jasmine (voice)"}, {"name": "Jonathan Freeman", "character": "Jafar (voice)"}, {"name": "Gilbert Gottfried", "character": "Iago (voice)"}]', 'John Musker', NULL, '2026-07-13 21:30:44.81732');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (275, 'tt0093779', 2493, 'The Princess Bride', 1987, '/2FC9L9MrjBoGHYjYZjdWQdopVYb.jpg', '{12,14,10749,10751}', 'In this enchantingly cracked fairy tale, the beautiful Princess Buttercup and the dashing Westley must overcome staggering odds to find happiness amid six-fingered swordsmen, murderous princes, Sicilians and rodents of unusual size. But even death can''t stop these true lovebirds from triumphing.', '[{"name": "Cary Elwes", "character": "Westley"}, {"name": "Robin Wright", "character": "The Princess Bride"}, {"name": "Mandy Patinkin", "character": "Inigo Montoya"}, {"name": "Chris Sarandon", "character": "Prince Humperdinck"}, {"name": "Christopher Guest", "character": "Count Rugen"}]', 'Rob Reiner', NULL, '2026-07-13 21:30:45.42926');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (276, 'tt8108198', 534780, 'Andhadhun', 2018, '/dy3K6hNvwE05siGgiLJcEiwgpdO.jpg', '{80,9648,53,35}', 'A series of mysterious events changes the life of a blind pianist who now must report a crime that was actually never witnessed by him.', '[{"name": "Ayushmann Khurrana", "character": "Akash Sarraf"}, {"name": "Tabu", "character": "Simi Sinha"}, {"name": "Radhika Apte", "character": "Sophie"}, {"name": "Manav Vij", "character": "Inspector Manohar Jawanda"}, {"name": "Zakir Hussain", "character": "Dr. Swami"}]', 'Sriram Raghavan', NULL, '2026-07-13 21:30:46.038733');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (277, 'tt0091763', 792, 'Platoon', 1986, '/m3mmFkPQKvPZq5exmh0bDuXlD9T.jpg', '{18,10752,28}', 'As a young and naive recruit in Vietnam, Chris Taylor faces a moral crisis when confronted with the horrors of war and the duality of man.', '[{"name": "Charlie Sheen", "character": "Chris Taylor"}, {"name": "Willem Dafoe", "character": "Sergeant Elias Grodin"}, {"name": "Tom Berenger", "character": "Sergeant Robert \"Bob\" Barnes"}, {"name": "Kevin Dillon", "character": "Bunny"}, {"name": "Forest Whitaker", "character": "Big Harold"}]', 'Oliver Stone', NULL, '2026-07-13 21:30:46.610997');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (289, 'tt0099348', 581, 'Dances with Wolves', 1990, '/hw0ZEHAaTqTxSXGVwUFX7uvanSA.jpg', '{12,18,37}', 'Wounded Civil War soldier John Dunbar tries to commit suicide—and becomes a hero instead. As a reward, he''s assigned to his dream post, a remote junction on the Western frontier, and soon makes unlikely friends with the local Sioux tribe.', '[{"name": "Kevin Costner", "character": "Lieutenant Dunbar"}, {"name": "Mary McDonnell", "character": "Stands With A Fist"}, {"name": "Graham Greene", "character": "Kicking Bird"}, {"name": "Rodney A. Grant", "character": "Wind In His Hair"}, {"name": "Floyd ''Red Crow'' Westerman", "character": "Ten Bears"}]', 'Kevin Costner', NULL, '2026-07-13 21:30:53.416926');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (279, 'tt2948372', 508442, 'Soul', 2020, '/6jmppcaubzLF8wkXM36ganVISCo.jpg', '{16,10751,18,10402,14}', 'Joe Gardner is a middle school teacher with a love for jazz music. After a successful audition at the Half Note Club, he suddenly gets into an accident that separates his soul from his body and is transported to the You Seminar, a center in which souls develop and gain passions before being transported to a newborn child. Joe must enlist help from the other souls-in-training, like 22, a soul who has spent eons in the You Seminar, in order to get back to Earth.', '[{"name": "Jamie Foxx", "character": "Joe Gardner (voice)"}, {"name": "Tina Fey", "character": "22 (voice)"}, {"name": "Graham Norton", "character": "Moonwind (voice)"}, {"name": "Rachel House", "character": "Terry (voice)"}, {"name": "Alice Braga", "character": "Counselor Jerry (voice)"}]', 'Pete Docter', NULL, '2026-07-13 21:30:47.719768');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (280, 'tt1954470', 117691, 'Gangs of Wasseypur - Part 1', 2012, '/4nbvLoPDftqXV14w5Mv14iqgVrt.jpg', '{28,53,80}', 'In 1970s India, Sardar Khan vows to take revenge on the man who killed his father decades earlier.', '[{"name": "Manoj Bajpayee", "character": "Sardar Khan"}, {"name": "Richa Chadha", "character": "Nagma"}, {"name": "Tigmanshu Dhulia", "character": "Ramadhir Singh"}, {"name": "Nawazuddin Siddiqui", "character": "Faizal Khan"}, {"name": "Reema Sen", "character": "Durga"}]', 'Anurag Kashyap', NULL, '2026-07-13 21:30:48.290918');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (281, 'tt26548265', 1118224, 'Maharaja', 2024, '/s0m4TM1XRAftQStgKpw024RvkJo.jpg', '{28,53,9648}', 'A barber seeks vengeance after his home is burglarized, cryptically telling police his "Lakshmi" has been taken, leaving them uncertain if it''s a person or object, jeer at his request until they learn what they''re really looking for.', '[{"name": "Vijay Sethupathi", "character": "Maharaja"}, {"name": "Anurag Kashyap", "character": "Selvam"}, {"name": "Sachana Namidass", "character": "Jothi"}, {"name": "Natarajan Subramaniam", "character": "Inspector S. Varadharajan"}, {"name": "Abhirami", "character": "Kokila"}]', 'Nithilan Saminathan', NULL, '2026-07-13 21:30:48.855232');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (284, 'tt4430212', 352173, 'Drishyam', 2015, '/gIClWRv5OSe8rl5Koi0AeUcCZ9Z.jpg', '{9648,53,18}', 'When his family stares down the barrel of criminal charges, a commoner channels his street smarts and knowledge of action films to tie the long arm of the law into an investigative Gordian knot.', '[{"name": "Ajay Devgn", "character": "Vijay Salgaonkar"}, {"name": "Tabu", "character": "IG Meera Deshmukh"}, {"name": "Shriya Saran", "character": "Nandini Salgaonkar"}, {"name": "Ishita Dutta", "character": "Anju Salgaonkar"}, {"name": "Mrunal Jadhav", "character": "Anu Salgaonkar"}]', 'Nishikant Kamat', NULL, '2026-07-13 21:30:50.548159');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (285, 'tt14961016', 1000837, 'I''m Still Here', 2024, '/gZnsMbhCvhzAQlKaVpeFRHYjGyb.jpg', '{18,36}', 'A woman married to a former politician during the 1971 military dictatorship in Brazil is forced to reinvent herself and chart a new course for her family after a violent and arbitrary act.', '[{"name": "Fernanda Torres", "character": "Eunice Paiva"}, {"name": "Fernanda Montenegro", "character": "Eunice Paiva (Older)"}, {"name": "Selton Mello", "character": "Rubens Paiva"}, {"name": "Valentina Herszage", "character": "Veroca"}, {"name": "Maria Manoella", "character": "Veroca"}]', 'Walter Salles', NULL, '2026-07-13 21:30:51.110001');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (286, 'tt0105323', 9475, 'Scent of a Woman', 1992, '/4adI7IaveWb7EidYXfLb3MK3CgO.jpg', '{18}', 'Charlie Simms is a student at a private preparatory school who comes from a poor family. To earn the money for his flight home to Gresham, Oregon for Christmas, Charlie takes a job over Thanksgiving looking after retired U.S. Army officer Lieutenant Colonel Frank Slade, a cantankerous middle-aged man who lives with his niece and her family.', '[{"name": "Al Pacino", "character": "Lt. Col. Frank Slade"}, {"name": "Chris O''Donnell", "character": "Charlie Simms"}, {"name": "James Rebhorn", "character": "Mr. Trask"}, {"name": "Gabrielle Anwar", "character": "Donna"}, {"name": "Philip Seymour Hoffman", "character": "George Willis, Jr."}]', 'Martin Brest', NULL, '2026-07-13 21:30:51.687431');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (287, 'tt0367110', 15774, 'Swades', 2004, '/yUSL24kpHc9Nls4Pohia4shgcIM.jpg', '{18}', 'A successful Indian scientist returns home to his village to take his nanny back to America with him, and in the process rediscovers his roots.', '[{"name": "Shah Rukh Khan", "character": "Mohan Bhargav"}, {"name": "Gayatri Joshi", "character": "Gita"}, {"name": "Kishori Ballal", "character": "Kaveri Amma"}, {"name": "Smit Sheth", "character": "Chiku"}, {"name": "Lekh Tandon", "character": "Dadaji"}]', 'Ashutosh Gowariker', NULL, '2026-07-13 21:30:52.252381');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (288, 'tt0175880', 334, 'Magnolia', 1999, '/tpfC325Jk6S38VTe5dDWjWtoyxr.jpg', '{18}', 'On one random day in the San Fernando Valley, a dying father, a young wife, a male caretaker, a famous lost son, a police officer in love, a boy genius, an ex-boy genius, a game show host and an estranged daughter will each become part of a dazzling multiplicity of plots, but one story.', '[{"name": "Tom Cruise", "character": "Frank T.J. Mackey"}, {"name": "Philip Baker Hall", "character": "Jimmy Gator"}, {"name": "Philip Seymour Hoffman", "character": "Phil Parma"}, {"name": "Julianne Moore", "character": "Linda Partridge"}, {"name": "William H. Macy", "character": "Quiz Kid Donnie Smith"}]', 'Paul Thomas Anderson', NULL, '2026-07-13 21:30:52.826632');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (290, 'tt11032374', 635302, 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', 2020, '/h8Rb9gBr48ODIwYUttZNYeMWeUU.jpg', '{16,28,14}', 'Tanjiro Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar''s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyojuro Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!', '[{"name": "Natsuki Hanae", "character": "Tanjiro Kamado (voice)"}, {"name": "Akari Kito", "character": "Nezuko Kamado (voice)"}, {"name": "Hiro Shimono", "character": "Zenitsu Agatsuma (voice)"}, {"name": "Yoshitsugu Matsuoka", "character": "Inosuke Hashibira (voice)"}, {"name": "Satoshi Hino", "character": "Kyojuro Rengoku (voice)"}]', 'Haruo Sotozaki', NULL, '2026-07-13 21:30:53.969837');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (291, 'tt0476735', 13393, 'My Father and My Son', 2005, '/ephCcqJYZFUnkQC7Oudah2qUL6O.jpg', '{18}', 'A left-wing journalist whose wife died while giving birth to his son during a military coup returns to his family''s farm. Estranged from his father for turning his back on the family and wasting his life with political activism instead, he tries to reconnect with him so that his son will have a place to live as his health is deteriorating due to the extensive torture he had to endure.', '[{"name": "Fikret Kuşkan", "character": "Sadık"}, {"name": "Ege Tanman", "character": "Deniz"}, {"name": "Çetin Tekindor", "character": "Hüseyin"}, {"name": "Hümeyra", "character": "Nuran"}, {"name": "Şerif Sezer", "character": "Gülbeyaz"}]', 'Çağan Irmak', NULL, '2026-07-13 21:30:54.530379');
