INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (301, 'tt34365591', 1383072, 'Mahavatar Narsimha', 2024, '/uGTF87VyfjtwwqRlT2apQg5YnEp.jpg', '{16,28,14,18}', 'Tyrannical demon Hiranyakashyap challenges Vishnu, proclaiming himself a god. However, his son Prahlad remains devoted to Vishnu, who appears as Narsimha to defeat the demon.', '[{"name": "Harjeet Walia", "character": "Lord Narsimha (voice)"}, {"name": "Aditya Raj Sharma", "character": "Hiranyakashipu (voice)"}, {"name": "Haripriya Matta", "character": "Prahlad (voice)"}, {"name": "Sanket Jaiswal", "character": "Narrator (voice)"}, {"name": "Priyanka Bhandari", "character": "Kayadhu (voice)"}]', 'Ashwin Kumar', NULL, '2026-07-13 21:31:00.313702');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (302, 'tt0499549', 19995, 'Avatar', 2009, '/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg', '{878,28,12}', 'In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.', '[{"name": "Sam Worthington", "character": "Jake Sully"}, {"name": "Zoe Saldaña", "character": "Neytiri"}, {"name": "Sigourney Weaver", "character": "Dr. Grace Augustine"}, {"name": "Stephen Lang", "character": "Colonel Miles Quaritch"}, {"name": "Michelle Rodriguez", "character": "Trudy Chacon"}]', 'James Cameron', NULL, '2026-07-13 21:31:00.913568');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (303, 'tt0083987', 783, 'Gandhi', 1982, '/rOXftt7SluxskrFrvU7qFJa5zeN.jpg', '{18,36}', 'In the early years of the 20th century, Mohandas K. Gandhi, a British-trained lawyer, forsakes all worldly possessions to take up the cause of Indian independence. Faced with armed resistance from the British government, Gandhi adopts a policy of ''passive resistance'', endeavouring to win freedom for his people without resorting to bloodshed.', '[{"name": "Ben Kingsley", "character": "Mahatma Gandhi"}, {"name": "Candice Bergen", "character": "Margaret Bourke-White"}, {"name": "Edward Fox", "character": "General Dyer"}, {"name": "John Gielgud", "character": "Lord Irwin"}, {"name": "Trevor Howard", "character": "Judge Broomfield"}]', 'Richard Attenborough', NULL, '2026-07-13 21:31:01.483553');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (304, 'tt1220719', 14756, 'Ip Man', 2008, '/zyQQ7wFuCvH6MzJcUKy6N6ouMYs.jpg', '{18,28,36}', 'A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.', '[{"name": "Donnie Yen", "character": "Yip Man"}, {"name": "Simon Yam", "character": "Zhou Qing Quan"}, {"name": "Lynn Hung Doi-Lam", "character": "Zhang Yong Cheng"}, {"name": "Hiroyuki Ikeuchi", "character": "General Miura"}, {"name": "Gordon Lam Ka-Tung", "character": "Captain Li Zhao"}]', 'Wilson Yip', NULL, '2026-07-13 21:31:02.083583');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (305, 'tt0371746', 1726, 'Iron Man', 2008, '/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', '{28,878,12}', 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark"}, {"name": "Terrence Howard", "character": "Rhodey"}, {"name": "Jeff Bridges", "character": "Obadiah Stane"}, {"name": "Gwyneth Paltrow", "character": "Pepper Potts"}, {"name": "Leslie Bibb", "character": "Christine Everhart"}]', 'Jon Favreau', NULL, '2026-07-13 21:31:02.663517');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (307, 'tt0118849', 21334, 'Children of Heaven', 1997, '/jWqh1CJWAEcxckMRrf6ARhIEh0R.jpg', '{18,10751}', 'Zohre''s shoes are gone; her older brother Ali lost them. They are poor, there are no shoes for Zohre until they come up with an idea: they will share one pair of shoes. School awaits.', '[{"name": "Amir Farrokh Hashemian", "character": "Ali"}, {"name": "Bahare Seddiqi", "character": "Zahra"}, {"name": "Nafise Jafar-Mohammadi", "character": "Roya"}, {"name": "Reza Naji", "character": "Ali''s Father"}, {"name": "Fereshte Sarabandi", "character": "Ali''s Mother"}]', 'Majid Majidi', NULL, '2026-07-13 21:31:03.789988');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (308, 'tt0169102', 19666, 'Lagaan: Once Upon a Time in India', 2001, '/yNX9lFRAFeNLNRIXdqZK9gYrYKa.jpg', '{12,18,36}', 'The year is 1893 and India is under British occupation. In a small village, the tyrannical Captain Russell has imposed an unprecedented land tax on its citizens. Outraged, Bhuvan, a rebellious farmer, rallies the villagers to publicly oppose the tax. Russell offers a novel way to settle the dispute: he challenges Bhuvan and his men to a game of cricket, a sport completely foreign to India. If Bhuvan and his men can defeat Russell''s team, the tax will be repealed.', '[{"name": "Aamir Khan", "character": "Bhuvan"}, {"name": "Gracy Singh", "character": "Gauri"}, {"name": "Rachel Shelley", "character": "Elizabeth Russell"}, {"name": "Paul Blackthorne", "character": "Captain Andrew Russell"}, {"name": "Suhasini Mulay", "character": "Yashoda"}]', 'Ashutosh Gowariker', NULL, '2026-07-13 21:31:04.35138');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (310, 'tt10366460', 776503, 'CODA', 2021, '/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', '{18,10402,10749}', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family''s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.', '[{"name": "Emilia Jones", "character": "Ruby Rossi"}, {"name": "Marlee Matlin", "character": "Jackie Rossi"}, {"name": "Troy Kotsur", "character": "Frank Rossi"}, {"name": "Eugenio Derbez", "character": "Bernardo Villalobos"}, {"name": "Ferdia Walsh-Peelo", "character": "Miles"}]', 'Sian Heder', NULL, '2026-07-13 21:31:05.507112');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (372, 'tt2125608', 84334, 'Searching for Sugar Man', 2012, '/ucM98HuBHSWmn44oiE83hIDc6VB.jpg', '{10402,99}', 'Two South Africans set out to discover what happened to their unlikely musical hero, the mysterious 1970s rock ''n'' roller, Rodriguez.', '[{"name": "Stephen Segerman", "character": "Self"}, {"name": "Rodriguez", "character": "Self"}, {"name": "Regan Rodriguez", "character": "Self"}, {"name": "Eva Rodriguez", "character": "Self"}, {"name": "Mike Theodore", "character": "Self"}]', 'Malik Bendjelloul', NULL, '2026-07-13 21:31:41.858224');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (311, 'tt0094625', 149, 'Akira', 1988, '/neZ0ykEsPqxamsX6o5QNUFILQrz.jpg', '{16,878,28}', 'A secret military project endangers Neo-Tokyo when it turns a biker gang member into a rampaging psychic psychopath that only two teenagers and a group of psychics can stop.', '[{"name": "Mitsuo Iwata", "character": "Shotaro Kaneda (voice)"}, {"name": "Nozomu Sasaki", "character": "Tetsuo Shima (voice)"}, {"name": "Mami Koyama", "character": "Kei (voice)"}, {"name": "Taro Ishida", "character": "Colonel Shikishima"}, {"name": "Mizuho Suzuki", "character": "Doctor Ônishi"}]', 'Katsuhiro Otomo', NULL, '2026-07-13 21:31:06.10656');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (313, 'tt0405508', 7913, 'Rang De Basanti', 2006, '/f1bF8CHzEu621bPSIg6XiUNAabh.jpg', '{35,18,36,10749,28}', 'After a group of friends graduate from Delhi University, they listlessly haunt their old campus, until a British filmmaker casts them in a film she''s making about freedom fighters under British rule. Although the group is largely apolitical, the tragic death of a friend owing to local government corruption awakens their patriotism. Inspired by the freedom fighters they represent in the film, the friends collectively decide to avenge the killing.', '[{"name": "Aamir Khan", "character": "Daljit ''DJ'' Singh"}, {"name": "Siddharth", "character": "Karan Singhania"}, {"name": "Kunal Kapoor", "character": "Aslam Khan"}, {"name": "Sharman Joshi", "character": "Sukhi"}, {"name": "Atul Kulkarni", "character": "Laxman Pandey"}]', 'Rakeysh Omprakash Mehra', NULL, '2026-07-13 21:31:07.280744');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (314, 'tt3501632', 284053, 'Thor: Ragnarok', 2017, '/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', '{28,878,35}', 'Thor is imprisoned on the other side of the universe and finds himself in a race against time to get back to Asgard to stop Ragnarok, the destruction of his home-world and the end of Asgardian civilization, at the hands of a powerful new threat, the ruthless Hela.', '[{"name": "Chris Hemsworth", "character": "Thor"}, {"name": "Mark Ruffalo", "character": "Bruce Banner / Hulk"}, {"name": "Tom Hiddleston", "character": "Loki"}, {"name": "Cate Blanchett", "character": "Hela"}, {"name": "Idris Elba", "character": "Heimdall"}]', 'Taika Waititi', NULL, '2026-07-13 21:31:07.854037');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (315, 'tt8946378', 546554, 'Knives Out', 2019, '/pThyQovXQrw2m0s9x82twj48Jq4.jpg', '{35,80,9648}', 'When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.', '[{"name": "Daniel Craig", "character": "Benoit Blanc"}, {"name": "Chris Evans", "character": "Ransom Drysdale"}, {"name": "Ana de Armas", "character": "Marta Cabrera"}, {"name": "Jamie Lee Curtis", "character": "Linda Drysdale"}, {"name": "Michael Shannon", "character": "Walt Thrombey"}]', 'Rian Johnson', NULL, '2026-07-13 21:31:08.531195');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (316, 'tt2543164', 329865, 'Arrival', 2016, '/x2FJsf1ElAgr63Y3PNPtJrcmpoe.jpg', '{18,878,9648}', 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.', '[{"name": "Amy Adams", "character": "Louise Banks"}, {"name": "Jeremy Renner", "character": "Ian Donnelly"}, {"name": "Forest Whitaker", "character": "Colonel Weber"}, {"name": "Michael Stuhlbarg", "character": "Agent Halpern"}, {"name": "Mark O''Brien", "character": "Captain Marks"}]', 'Denis Villeneuve', NULL, '2026-07-13 21:31:09.102157');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (318, 'tt0126029', 808, 'Shrek', 2001, '/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', '{16,35,14,12,10751}', 'It ain''t easy bein'' green -- especially if you''re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.', '[{"name": "Mike Myers", "character": "Shrek / Blind Mouse (voice)"}, {"name": "Eddie Murphy", "character": "Donkey (voice)"}, {"name": "Cameron Diaz", "character": "Princess Fiona (voice)"}, {"name": "John Lithgow", "character": "Lord Farquaad (voice)"}, {"name": "Vincent Cassel", "character": "Monsieur Hood (voice)"}]', 'Andrew Adamson', NULL, '2026-07-13 21:31:10.294354');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (319, 'tt1631867', 137113, 'Edge of Tomorrow', 2014, '/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg', '{28,878}', 'Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.', '[{"name": "Tom Cruise", "character": "Cage"}, {"name": "Emily Blunt", "character": "Rita"}, {"name": "Brendan Gleeson", "character": "General Brigham"}, {"name": "Bill Paxton", "character": "Master Sergeant Farell"}, {"name": "Jonas Armstrong", "character": "Skinner"}]', 'Doug Liman', NULL, '2026-07-13 21:31:10.860878');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (320, 'tt4857264', 411088, 'The Invisible Guest', 2016, '/fptnZJbLzKUHeNlYrAynbyoL5YJ.jpg', '{18,9648,53}', 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.', '[{"name": "Mario Casas", "character": "Adrián Doria"}, {"name": "Ana Wagener", "character": "Elvira"}, {"name": "Jose Coronado", "character": "Tomás Garrido"}, {"name": "Bárbara Lennie", "character": "Laura Vidal"}, {"name": "Francesc Orella", "character": "Félix Leiva"}]', 'Oriol Paulo', NULL, '2026-07-13 21:31:11.426769');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (321, 'tt1877832', 127585, 'X-Men: Days of Future Past', 2014, '/tYfijzolzgoMOtegh1Y7j2Enorg.jpg', '{28,12,878}', 'The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.', '[{"name": "Hugh Jackman", "character": "Logan / Wolverine"}, {"name": "James McAvoy", "character": "Charles Xavier"}, {"name": "Michael Fassbender", "character": "Erik Lehnsherr"}, {"name": "Patrick Stewart", "character": "Professor X"}, {"name": "Ian McKellen", "character": "Magneto"}]', 'Bryan Singer', NULL, '2026-07-13 21:31:12.023401');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (322, 'tt1152758', 15584, 'Dear Zachary: A Letter to a Son About His Father', 2008, '/yYVHGe7U55Ojx11y5A82phPpCHv.jpg', '{99,80}', 'In 2001, Andrew Bagby, a medical resident, is murdered not long after breaking up with his girlfriend. Soon after, when she announces she''s pregnant, one of Andrew''s many close friends, Kurt Kuenne, begins this film, a gift to the child.', '[{"name": "Kurt Kuenne", "character": "Self (voice)"}, {"name": "Andrew Bagby", "character": "Self (archive footage)"}, {"name": "David Bagby", "character": "Self - Father"}, {"name": "Kathleen Bagby", "character": "Self - Mother"}, {"name": "Shirley Turner", "character": "Self - Ex-Girlfriend (archive footage)"}]', 'Kurt Kuenne', NULL, '2026-07-13 21:31:12.603738');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (323, 'tt0304141', 673, 'Harry Potter and the Prisoner of Azkaban', 2004, '/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg', '{12,14}', 'Harry Potter''s life is in danger once more as dangerous wizard Sirius Black has escaped from Azkaban Prison and is heading to Hogwarts.', '[{"name": "Daniel Radcliffe", "character": "Harry Potter"}, {"name": "Rupert Grint", "character": "Ron Weasley"}, {"name": "Emma Watson", "character": "Hermione Granger"}, {"name": "Robbie Coltrane", "character": "Rubeus Hagrid"}, {"name": "Michael Gambon", "character": "Albus Dumbledore"}]', 'Alfonso Cuarón', NULL, '2026-07-13 21:31:13.179318');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (324, 'tt7019842', 441717, '96', 2018, '/nrVloCa2hCFOztRF1DZU2jnWIiQ.jpg', '{10749}', 'Ram is a photographer and nature lover who travels all around India capturing moments. On a chance visit to his hometown Tanjavur, he goes into his school and begins to walk down memory lane to 1994 when he was a student harboring feelings for his classmate Janu.', '[{"name": "Vijay Sethupathi", "character": "Ramachandran \"Ram\" Krishnamoorthy"}, {"name": "Trisha Krishnan", "character": "Janaki \"Janu\" Devi"}, {"name": "Aditya Baskar", "character": "Younger Ram"}, {"name": "Gouri G Kishan", "character": "Younger Janu"}, {"name": "Devadarshini", "character": "Subhashini"}]', 'C. Prem Kumar', NULL, '2026-07-13 21:31:13.824197');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (325, 'tt1136608', 17654, 'District 9', 2009, '/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg', '{878}', 'Thirty years ago, aliens arrive on Earth. Not to conquer or give aid, but to find refuge from their dying planet. Separated from humans in a South African area called District 9, the aliens are managed by Multi-National United, which is unconcerned with the aliens'' welfare but will do anything to master their advanced technology. When a company field agent contracts a mysterious virus that begins to alter his DNA, there is only one place he can hide: District 9.', '[{"name": "Sharlto Copley", "character": "Wikus van de Merwe"}, {"name": "Jason Cope", "character": "Christopher Johnson / Grey Bradnam / Trent"}, {"name": "Nathalie Boltt", "character": "Sarah Livingstone - Sociologist"}, {"name": "Sylvaine Strike", "character": "Dr Katrina McKenzie"}, {"name": "Elizabeth Mkandawie", "character": "Interviewee"}]', 'Neill Blomkamp', NULL, '2026-07-13 21:31:14.506355');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (327, 'tt0352248', 921, 'Cinderella Man', 2005, '/wkeOjIcpuqLMW4GnVowlM9VI0JE.jpg', '{10749,18,36}', 'The true story of boxer Jim Braddock who, following his retirement in the 1930s, makes a surprise comeback in order to lift his family out of poverty.', '[{"name": "Russell Crowe", "character": "Jim Braddock"}, {"name": "Renée Zellweger", "character": "Mae Braddock"}, {"name": "Paul Giamatti", "character": "Joe Gould"}, {"name": "Craig Bierko", "character": "Max Baer"}, {"name": "Paddy Considine", "character": "Mike Wilson"}]', 'Ron Howard', NULL, '2026-07-13 21:31:15.627628');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (328, 'tt5354160', 418325, 'Mirror Game', 2016, '/1Cz5Q7PH2JklNV7OzMkTenPGrEf.jpg', '{80,9648,53}', 'Ayna is an actor and the prison is his stage. He slips into the characters of the powerful convicted in exchange of money and take their place in prison. This strange profession is borne out of a society that doesn''t give him a chance to follow his passion of acting, but forces him to act in the real life. Falling in love with the girl next door changes his life equation and he decides to end this career with one last performance. But this one takes him too deep in the rabbit hole. The story unfolds on how an underdog survives in a society that is merciless and struggles his way out from the clutch of crime game which he is a part too.', '[{"name": "Chanchal Chowdhury", "character": "Sharafat Karim Ayna / Nizam Sayeed Chowdhury"}, {"name": "Masuma Rahman Nabila", "character": "Hridi"}, {"name": "Partha Barua", "character": "Saber Hossain"}, {"name": "Lutfur Rahman George", "character": "Mr. Kuddus"}, {"name": "Gousul Alam Shaon", "character": "Gousul"}]', 'Amitabh Reza Chowdhury', NULL, '2026-07-13 21:31:16.199226');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (329, 'tt0454876', 87827, 'Life of Pi', 2012, '/iLgRu4hhSr6V1uManX6ukDriiSc.jpg', '{12,18}', 'The story of an Indian boy named Pi, a zookeeper''s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean.', '[{"name": "Suraj Sharma", "character": "Pi Patel"}, {"name": "Irrfan Khan", "character": "Adult Pi Patel"}, {"name": "Ayush Tandon", "character": "Pi Patel (11-12 Years)"}, {"name": "Gautam Belur", "character": "Pi Patel (5 Years)"}, {"name": "Adil Hussain", "character": "Santosh Patel"}]', 'Ang Lee', NULL, '2026-07-13 21:31:16.758414');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (331, 'tt37287335', 1339713, 'Obsession', 2025, '/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', '{27,53}', 'After breaking the mysterious "One Wish Willow" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.', '[{"name": "Michael Johnston", "character": "Bear"}, {"name": "Inde Navarrette", "character": "Nikki"}, {"name": "Cooper Tomlinson", "character": "Ian"}, {"name": "Megan Lawless", "character": "Sarah"}, {"name": "Andy Richter", "character": "Carter"}]', 'Curry Barker', NULL, '2026-07-13 21:31:17.90106');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (332, 'tt0120363', 863, 'Toy Story 2', 1999, '/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg', '{16,35,10751}', 'Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al''s Toy Barn kidnaps Woody. Andy''s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.', '[{"name": "Tom Hanks", "character": "Woody (voice)"}, {"name": "Tim Allen", "character": "Buzz Lightyear (voice)"}, {"name": "Joan Cusack", "character": "Jessie (voice)"}, {"name": "Kelsey Grammer", "character": "Prospector (voice)"}, {"name": "Don Rickles", "character": "Mr. Potato Head (voice)"}]', 'John Lasseter', NULL, '2026-07-13 21:31:18.467194');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (333, 'tt8291224', 554600, 'Uri: The Surgical Strike', 2019, '/yNySAgpAnWmPpYinim9E0tUzJWG.jpg', '{28,18,10752}', 'Following the roguish terrorist attacks at Uri Army Base camp in Kashmir, India takes the fight to the enemy, in its most successful covert operation till date with one and only one objective of avenging their fallen heroes.', '[{"name": "Vicky Kaushal", "character": "Major Vihan Singh Shergill"}, {"name": "Paresh Rawal", "character": "NSA Govind Bhardwaj"}, {"name": "Yami Gautam Dhar", "character": "Pallavi Sharma / Jasmine"}, {"name": "Mohit Raina", "character": "Major Karan Kashyap"}, {"name": "Kirti Kulhari", "character": "Fl. Lt. Seerat Kaur"}]', 'Aditya Dhar', NULL, '2026-07-13 21:31:19.026619');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (334, 'tt1727824', 424694, 'Bohemian Rhapsody', 2018, '/lHu1wtNaczFPGFDTrjCSzeLPTKN.jpg', '{10402,18}', 'Singer Freddie Mercury, guitarist Brian May, drummer Roger Taylor and bass guitarist John Deacon take the music world by storm when they form the rock ''n'' roll band Queen in 1970. Hit songs become instant classics. When Mercury''s increasingly wild lifestyle starts to spiral out of control, Queen soon faces its greatest challenge yet – finding a way to keep the band together amid the success and excess.', '[{"name": "Rami Malek", "character": "Freddie Mercury"}, {"name": "Gwilym Lee", "character": "Brian May"}, {"name": "Ben Hardy", "character": "Roger Taylor"}, {"name": "Joseph Mazzello", "character": "John Deacon"}, {"name": "Lucy Boynton", "character": "Mary Austin"}]', 'Bryan Singer', NULL, '2026-07-13 21:31:19.63375');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (335, 'tt0796366', 13475, 'Star Trek', 2009, '/9vaRPXj44Q2meHgt3VVfQufiHOJ.jpg', '{878,28,12}', 'The fate of the galaxy rests in the hands of bitter rivals. One, James Kirk, is a delinquent, thrill-seeking Iowa farm boy. The other, Spock, a Vulcan, was raised in a logic-based society that rejects all emotion. As fiery instinct clashes with calm reason, their unlikely but powerful partnership is the only thing capable of leading their crew through unimaginable danger, boldly going where no one has gone before. The human adventure has begun again.', '[{"name": "Chris Pine", "character": "Cadet James T. Kirk"}, {"name": "Zachary Quinto", "character": "Commander Spock"}, {"name": "Leonard Nimoy", "character": "Ambassador Spock"}, {"name": "Eric Bana", "character": "Captain Nero"}, {"name": "Bruce Greenwood", "character": "Captain Christopher Pike"}]', 'J.J. Abrams', NULL, '2026-07-13 21:31:20.293632');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (336, 'tt0092067', 10515, 'Castle in the Sky', 1986, '/41XxSsJc5OrulP0m7TrrUeO2hoz.jpg', '{12,14,16,28,10751}', 'A young boy and a girl with a magic crystal must race against pirates and foreign agents in a search for a legendary floating castle.', '[{"name": "Keiko Yokozawa", "character": "Sheeta (voice)"}, {"name": "Mayumi Tanaka", "character": "Pazu (voice)"}, {"name": "Minori Terada", "character": "Muska (voice)"}, {"name": "Kotoe Hatsui", "character": "Dola (voice)"}, {"name": "Fujio Tokita", "character": "Uncle Pomme (voice)"}]', 'Hayao Miyazaki', NULL, '2026-07-13 21:31:20.855721');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (337, 'tt0087544', 81, 'Warriors of the Wind', 1984, '/tcrkfB8SRPQCgwI88hQScua6nxh.jpg', '{12,16,14}', 'After a global war, the seaside kingdom known as the Valley of the Wind remains one of the last strongholds on Earth untouched by a poisonous jungle and the powerful insects that guard it. Led by the courageous Princess Nausicaä, the people of the Valley engage in an epic struggle to restore the bond between humanity and Earth.', '[{"name": "Sumi Shimamoto", "character": "Nausicaä (voice)"}, {"name": "Ichiro Nagai", "character": "Mito (voice)"}, {"name": "Gorō Naya", "character": "Yupa (voice)"}, {"name": "Yoji Matsuda", "character": "Asbel (voice)"}, {"name": "Yoshiko Sakakibara", "character": "Kushana (voice)"}]', 'Hayao Miyazaki', NULL, '2026-07-13 21:31:21.493448');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (338, 'tt15327088', 858485, 'Kantara', 2022, '/jIsKmkxMzdCZ0Ux1GVSnu8m6Na6.jpg', '{28,18,53}', 'Shiva, a tribal vagabond lives with his mother in hamlet, stays away from the traditional Daivaradhane and Bhoota Kola legacy due to an unforgettable childhood incident. He is happy loafing around with his friends and doing petty jobs for his landlord. When Forest officer Murali enters the scene, it gives a fresh dimension to the man-vs-nature fight. Can Shiva save the forest from Murali? Or is Murali just a dummy bait cast by bigger fish?', '[{"name": "Rishab Shetty", "character": "Kaadubettu Shiva / Shiva''s Father"}, {"name": "Sapthami Gowda", "character": "Leela"}, {"name": "Kishore", "character": "Murali"}, {"name": "Achyuth Kumar", "character": "Devendra Suttooru"}, {"name": "Pramod Shetty", "character": "Sudhakar"}]', 'Rishab Shetty', NULL, '2026-07-13 21:31:22.074188');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (340, 'tt1659337', 84892, 'The Perks of Being a Wallflower', 2012, '/aKCvdFFF5n80P2VdS7d8YBwbCjh.jpg', '{18}', 'Pittsburgh, Pennsylvania, 1991. High school freshman Charlie is a wallflower, always watching life from the sidelines, until two senior students, Sam and her stepbrother Patrick, become his mentors, helping him discover the joys of friendship, music and love.', '[{"name": "Logan Lerman", "character": "Charlie"}, {"name": "Emma Watson", "character": "Sam"}, {"name": "Ezra Miller", "character": "Patrick"}, {"name": "Mae Whitman", "character": "Mary Elizabeth"}, {"name": "Kate Walsh", "character": "Mother"}]', 'Stephen Chbosky', NULL, '2026-07-13 21:31:23.22209');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (341, 'tt0111495', 110, 'Three Colors: Red', 1994, '/JHmsBiX1tjCKqAul1lzC20WcAW.jpg', '{18,9648,10749}', 'Part-time model Valentine unexpectedly befriends a retired judge after she runs over his dog. At first, the grumpy man shows no concern about the dog, and Valentine decides to keep it. But the two form a bond when she returns to his house and catches him listening to his neighbors’ phone calls.', '[{"name": "Irène Jacob", "character": "Valentine"}, {"name": "Jean-Louis Trintignant", "character": "The Judge"}, {"name": "Frédérique Feder", "character": "Karin"}, {"name": "Jean-Pierre Lorit", "character": "Auguste"}, {"name": "Samuel Le Bihan", "character": "Photographer"}]', 'Krzysztof Kieślowski', NULL, '2026-07-13 21:31:23.776523');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (342, 'tt1313104', 23128, 'The Cove', 2009, '/miodcVtQv2YxpKjjHJWcV0EDfSP.jpg', '{99}', 'The Cove tells the amazing true story of how an elite team of individuals, films makers and free divers embarked on a covert mission to penetrate the hidden cove in Japan, shining light on a dark and deadly secret. The shocking discoveries were only the tip of the iceberg.', '[{"name": "Hayden Panettiere", "character": "Self"}, {"name": "Joe Chisholm", "character": "Self"}, {"name": "Mandy-Rae Cruikshank", "character": "Self"}, {"name": "Charles Hambleton", "character": "Self"}, {"name": "Simon Hutchins", "character": "Self"}]', 'Louie Psihoyos', NULL, '2026-07-13 21:31:24.337518');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (343, 'tt31514146', 1317149, 'I Swear', 2025, '/vUwyhNWBKkSwK8ELvEeBRwV724h.jpg', '{18,36}', 'Diagnosed with Tourette Syndrome at 15, John Davidson navigates his way against the odds through troubled teenage years and into adulthood, finding inspiration in the kindness of others to discover his true purpose in life.', '[{"name": "Robert Aramayo", "character": "John"}, {"name": "Maxine Peake", "character": "Dottie"}, {"name": "Peter Mullan", "character": "Tommy"}, {"name": "Shirley Henderson", "character": "Heather"}, {"name": "Scott Ellis Watson", "character": "Young John"}]', 'Kirk Jones', NULL, '2026-07-13 21:31:24.90245');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (344, 'tt1645089', 44639, 'Inside Job', 2010, '/7yXXIWec24htucjsZS1sDuPLqw8.jpg', '{99,80}', 'A film that exposes the shocking truth behind the economic crisis of 2008. The global financial meltdown, at a cost of over $20 trillion, resulted in millions of people losing their homes and jobs. Through extensive research and interviews with major financial insiders, politicians and journalists, Inside Job traces the rise of a rogue industry and unveils the corrosive relationships which have corrupted politics, regulation and academia.', '[{"name": "Matt Damon", "character": "Narrator"}, {"name": "Bill Ackman", "character": "Self - Hedge Fund Manager"}, {"name": "Jonathan Alpert", "character": "Self - Therapist"}, {"name": "Christine Lagarde", "character": "Self - Finance Minister, France"}, {"name": "Daniel Alpert", "character": "Self - Managing Director, Westwood Capital"}]', 'Charles Ferguson', NULL, '2026-07-13 21:31:25.456936');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (345, 'tt0206634', 9693, 'Children of Men', 2006, '/k9IAS4TehZFcKi4HVByxZNPfqex.jpg', '{878,53,28}', 'In 2027, in a chaotic world in which humans can no longer procreate, a former activist agrees to help transport a miraculously pregnant woman to a sanctuary at sea, where her child''s birth may help scientists save the future of humankind.', '[{"name": "Clive Owen", "character": "Theo Faron"}, {"name": "Clare-Hope Ashitey", "character": "Kee"}, {"name": "Chiwetel Ejiofor", "character": "Luke"}, {"name": "Julianne Moore", "character": "Julian"}, {"name": "Michael Caine", "character": "Jasper"}]', 'Alfonso Cuarón', NULL, '2026-07-13 21:31:26.012939');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (346, 'tt0118694', 843, 'In the Mood for Love', 2000, '/iYypPT4bhqXfq1b6EnmxvRt6b2Y.jpg', '{18,10749}', 'In 1960s Hong Kong, two neighbors form an intimate bond after making a discovery about their spouses in this visually stunning tale of unrequited love.', '[{"name": "Maggie Cheung", "character": "Su Li-zhen"}, {"name": "Tony Leung Chiu-wai", "character": "Chow Mo-wan"}, {"name": "Siu Ping-Lam", "character": "Ah Ping"}, {"name": "Rebecca Pan", "character": "Mrs. Suen"}, {"name": "Kelly Lai Chen", "character": "Mr. Ho"}]', 'Wong Kar-Wai', NULL, '2026-07-13 21:31:26.561616');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (347, 'tt0790636', 152532, 'Dallas Buyers Club', 2013, '/7Fdh7gUq3plvQqxRbNYhWvDABXA.jpg', '{18,36}', 'Loosely based on the true-life tale of Ron Woodroof, a drug-taking, women-loving, homophobic man who in 1986 was diagnosed with HIV/AIDS and given thirty days to live.', '[{"name": "Matthew McConaughey", "character": "Ron Woodroof"}, {"name": "Jennifer Garner", "character": "Eve"}, {"name": "Jared Leto", "character": "Rayon"}, {"name": "Denis O''Hare", "character": "Dr. Sevard"}, {"name": "Steve Zahn", "character": "Tucker"}]', 'Jean-Marc Vallée', NULL, '2026-07-13 21:31:27.140071');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (348, 'tt9900782', 587030, 'Kaithi', 2019, '/hOF9CgPsy9aLr5GJEBESC8MEXFy.jpg', '{28,53,80}', 'Dilli, a convicted criminal, is out on parole to meet his daughter. However, a drug bust sets him off on a mission to save the life of police officers.', '[{"name": "Karthi", "character": "Dilli"}, {"name": "Narain", "character": "Bejoy"}, {"name": "Arjun Das", "character": "Anbu"}, {"name": "Harish Uthaman", "character": "Adaikalam"}, {"name": "George Mariyan", "character": "Napoleon"}]', 'Lokesh Kanagaraj', NULL, '2026-07-13 21:31:27.74658');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (349, 'tt0327056', 322, 'Mystic River', 2003, '/hCHVDbo6XJGj3r2i4hVjKhE0GKF.jpg', '{53,18,9648}', 'The lives of three men who were childhood friends are shattered when one of them suffers a family tragedy.', '[{"name": "Sean Penn", "character": "Jimmy Markum"}, {"name": "Tim Robbins", "character": "Dave Boyle"}, {"name": "Kevin Bacon", "character": "Sean Devine"}, {"name": "Laurence Fishburne", "character": "Whitey Powers"}, {"name": "Marcia Gay Harden", "character": "Celeste Boyle"}]', 'Clint Eastwood', NULL, '2026-07-13 21:31:28.316527');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (350, 'tt0242519', 21614, 'Hera Pheri', 2000, '/23MKGUPT5laTStim4TaGhfgSltu.jpg', '{35,80}', 'Two tenants and a landlord, in desperate need of money, chance upon a ransom call via a cross connection. They hatch a plan to claim the ransom for themselves.', '[{"name": "Akshay Kumar", "character": "Raju"}, {"name": "Suniel Shetty", "character": "Shyam"}, {"name": "Paresh Rawal", "character": "Baburao Ganpatrao Apte"}, {"name": "Tabu", "character": "Anuradha Shivshankar Panikar"}, {"name": "Om Puri", "character": "Kharak Singh"}]', 'Priyadarshan', NULL, '2026-07-13 21:31:28.872301');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (351, 'tt5813916', 427008, 'The Mountain II', 2016, '/dYCqrxuCuzhfgbYJbO2HN4zTeqa.jpg', '{10752,18}', 'In a desolate war zone where screams of the innocent echo, on the very line between disaster and valor, 7 Maroon Berets will dance with death.', '[{"name": "Çağlar Ertuğrul", "character": "Üsteğmen Oğuz Çağlar"}, {"name": "Ufuk Bayraktar", "character": "Uzman Çavuş Bekir Özbey"}, {"name": "Murat Serezli", "character": "Kurmay Yarbay Veysel Gökmusa"}, {"name": "Ahu Türkpençe", "character": "Ceyda Balaban"}, {"name": "Atılgan Gümüş", "character": "Astsubay Kademeli Kıdemli Başçavuş Mustafa Şahin"}]', 'Alper Çağlar', NULL, '2026-07-13 21:31:29.465009');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (352, 'tt3863552', 348892, 'Bajrangi Bhaijaan', 2015, '/vhlliI7HZZlWfo5d6CiyfBAGLrW.jpg', '{35,18,12}', 'A young mute girl from Pakistan loses herself in India with no way to head back. A devoted man with a magnanimous spirit undertakes the task to get her back to her motherland and unite her with her family.', '[{"name": "Salman Khan", "character": "Pawan Kumar \"Bajarangi\" Chaturvedi"}, {"name": "Harshaali Malthotra", "character": "Shahida \"Munni\""}, {"name": "Nawazuddin Siddiqui", "character": "Chand Nawab"}, {"name": "Kareena Kapoor Khan", "character": "Rasika"}, {"name": "Sharat Saxena", "character": "Dayanand"}]', 'Kabir Khan', NULL, '2026-07-13 21:31:30.031046');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (353, 'tt7838252', 564147, 'K.G.F: Chapter 1', 2018, '/ltHlJwvxKv7d0ooCiKSAvfwV9tX.jpg', '{28,53,12,80}', 'A period drama set in the 1970s, KGF follows the story of a fierce rebel who rises against the brutal oppression in Kolar Gold Fields and becomes the symbol of hope to legions of downtrodden people.', '[{"name": "Yash", "character": "Rocky / Raja Krishnappa Bairya"}, {"name": "Srinidhi Shetty", "character": "Reena"}, {"name": "Ramachandra Raju", "character": "Garuda"}, {"name": "Archana Jois", "character": "Shanthamma / Rocky''s Mother"}, {"name": "Anant Nag", "character": "Anand Ingalagi"}]', 'Prashanth Neel', NULL, '2026-07-13 21:31:30.586928');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (354, 'tt0102138', 820, 'JFK', 1991, '/r0VWVTYlqdRCK5ZoOdNnHdqM2gt.jpg', '{18,53,36}', 'Follows the investigation into the assassination of President John F. Kennedy led by New Orleans district attorney Jim Garrison.', '[{"name": "Kevin Costner", "character": "Jim Garrison"}, {"name": "Tommy Lee Jones", "character": "Clay Shaw"}, {"name": "Gary Oldman", "character": "Lee Harvey Oswald"}, {"name": "Kevin Bacon", "character": "Willie O''Keefe"}, {"name": "Michael Rooker", "character": "Bill Broussard"}]', 'Oliver Stone', NULL, '2026-07-13 21:31:31.151283');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (355, 'tt0780536', 8321, 'In Bruges', 2008, '/vz3Vd6nfq9YZrVvyYx5RHFaYKV3.jpg', '{35,18,80}', 'Ray and Ken, two hit men, are in Bruges, Belgium, waiting for their next mission. While they are there they have time to think and discuss their previous assignment. When the mission is revealed to Ken, it is not what he expected.', '[{"name": "Colin Farrell", "character": "Ray"}, {"name": "Brendan Gleeson", "character": "Ken"}, {"name": "Ralph Fiennes", "character": "Harry"}, {"name": "Clémence Poésy", "character": "Chloë"}, {"name": "Thekla Reuten", "character": "Marie"}]', 'Martin McDonagh', NULL, '2026-07-13 21:31:31.709411');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (356, 'tt2584384', 515001, 'Jojo Rabbit', 2019, '/1mqL7VG4Ix8wmxwypmCA1HTHBky.jpg', '{35,10752,18}', 'Jojo, a lonely German boy during World War II has his world shaken when he learns that his single mother is hiding a Jewish girl in their home. Influenced by a buffoonish imaginary version of Adolf Hitler, he begins to question his beliefs and confront the conflict between propaganda and his own humanity.', '[{"name": "Roman Griffin Davis", "character": "Jojo"}, {"name": "Thomasin McKenzie", "character": "Elsa"}, {"name": "Scarlett Johansson", "character": "Rosie"}, {"name": "Taika Waititi", "character": "Adolf"}, {"name": "Sam Rockwell", "character": "Captain Klenzendorf"}]', 'Taika Waititi', NULL, '2026-07-13 21:31:32.281292');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (358, 'tt0319061', 587, 'Big Fish', 2003, '/tjK063yCgaBAluVU72rZ6PKPH2l.jpg', '{12,14,18}', 'Throughout his life Edward Bloom has always been a man of big appetites, enormous passions and tall tales. In his later years, he remains a huge mystery to his son, William. Now, to get to know the real man, Will begins piecing together a true picture of his father from flashbacks of his amazing adventures.', '[{"name": "Ewan McGregor", "character": "Ed Bloom (young)"}, {"name": "Albert Finney", "character": "Ed Bloom (senior)"}, {"name": "Billy Crudup", "character": "Will Bloom"}, {"name": "Jessica Lange", "character": "Sandra Bloom (senior)"}, {"name": "Helena Bonham Carter", "character": "Jenny (young & senior) / The Witch"}]', 'Tim Burton', NULL, '2026-07-13 21:31:33.45033');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (359, 'tt6791350', 447365, 'Guardians of the Galaxy Vol. 3', 2023, '/r2J02Z2OpNTctfOSN1Ydgii51I3.jpg', '{878,12,28}', 'Peter Quill, still reeling from the loss of Gamora, must rally his team around him to defend the universe along with protecting one of their own. A mission that, if not completed successfully, could quite possibly lead to the end of the Guardians as we know them.', '[{"name": "Chris Pratt", "character": "Peter Quill / Star-Lord"}, {"name": "Zoe Saldaña", "character": "Gamora"}, {"name": "Dave Bautista", "character": "Drax"}, {"name": "Karen Gillan", "character": "Nebula"}, {"name": "Pom Klementieff", "character": "Mantis"}]', 'James Gunn', NULL, '2026-07-13 21:31:34.100244');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (360, 'tt12361974', 791373, 'Zack Snyder''s Justice League', 2021, '/tnAuB8q5vv7Ax9UAEje5Xi4BXik.jpg', '{28,12,14}', 'Determined to ensure Superman''s ultimate sacrifice was not in vain, Bruce Wayne aligns forces with Diana Prince with plans to recruit a team of metahumans to protect the world from an approaching threat of catastrophic proportions.', '[{"name": "Ben Affleck", "character": "Batman / Bruce Wayne"}, {"name": "Henry Cavill", "character": "Superman / Clark Kent"}, {"name": "Gal Gadot", "character": "Wonder Woman / Diana Prince"}, {"name": "Ray Fisher", "character": "Cyborg / Victor Stone"}, {"name": "Jason Momoa", "character": "Aquaman / Arthur Curry"}]', 'Zack Snyder', NULL, '2026-07-13 21:31:34.83716');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (361, 'tt0083866', 601, 'E.T. the Extra-Terrestrial', 1982, '/an0nD6uq6byfxXCfk6lQBzdL2J1.jpg', '{12,878,10751}', 'An alien is left behind on Earth and saved by the 10-year-old Elliott who decides to keep him hidden in his home. While a task force hunts for the extra-terrestrial, Elliott, his brother, and his little sister Gertie form an emotional bond with their new friend, and try to help him find his way home.', '[{"name": "Henry Thomas", "character": "Elliott"}, {"name": "Drew Barrymore", "character": "Gertie"}, {"name": "Robert MacNaughton", "character": "Michael"}, {"name": "Peter Coyote", "character": "Keys"}, {"name": "Dee Wallace", "character": "Mary"}]', 'Steven Spielberg', NULL, '2026-07-13 21:31:35.39472');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (362, 'tt2356180', 206324, 'Bhaag Milkha Bhaag', 2013, '/bXywc0CEzS1fIshPWWi4V8A58U3.jpg', '{36,18}', 'The true story of the "Flying Sikh" world champion runner and Olympian Milkha Singh who overcame the massacre of his family, civil war during the India-Pakistan partition, and homelessness to become one of India''s most iconic athletes.', '[{"name": "Farhan Akhtar", "character": "Milkha Singh"}, {"name": "Sonam Kapoor Ahuja", "character": "Biro"}, {"name": "Divya Dutta", "character": "Ishri Kaur"}, {"name": "Pavan Malhotra", "character": "Hawaldar (Constable) Gurudev Singh"}, {"name": "Rebecca Breeds", "character": "Stella"}]', 'Rakeysh Omprakash Mehra', NULL, '2026-07-13 21:31:36.00278');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (363, 'tt0103767', 14002, 'Baraka', 1992, '/ldEuJQ4z7zEvL7iXraESWBUfQcz.jpg', '{99}', 'A paralysingly beautiful documentary with a global vision—an odyssey through landscape and time—that attempts to capture the essence of life.', '[{"name": "Patrick Disanto", "character": "Journeyman (uncredited)"}]', 'Ron Fricke', NULL, '2026-07-13 21:31:36.577617');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (364, 'tt30472557', 1218925, 'Chainsaw Man - The Movie: Reze Arc', 2025, '/xdzLBZjCVSEsic7m7nJc4jNJZVW.jpg', '{16,28,10749,14}', 'In a brutal war between devils, hunters, and secret enemies, a mysterious girl named Reze has stepped into Denji''s world, and he faces his deadliest battle yet, fueled by love in a world where survival knows no rules.', '[{"name": "Kikunosuke Toya", "character": "Denji (voice)"}, {"name": "Tomori Kusunoki", "character": "Makima (voice)"}, {"name": "Reina Ueda", "character": "Reze (voice)"}, {"name": "Shogo Sakata", "character": "Aki (voice)"}, {"name": "Karin Takahashi", "character": "Kobeni (voice)"}]', 'Tatsuya Yoshihara', NULL, '2026-07-13 21:31:37.137222');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (365, 'tt0166924', 1018, 'Mulholland Drive', 2001, '/x7A59t6ySylr1L7aubOQEA480vM.jpg', '{53,18,9648}', 'Blonde Betty Elms has only just arrived in Hollywood to become a movie star when she meets an enigmatic brunette with amnesia. Meanwhile, as the two set off to solve the second woman''s identity, filmmaker Adam Kesher runs into ominous trouble while casting his latest project.', '[{"name": "Naomi Watts", "character": "Betty Elms / Diane Selwyn"}, {"name": "Laura Harring", "character": "Rita / Camilla Rhodes"}, {"name": "Justin Theroux", "character": "Adam"}, {"name": "Ann Miller", "character": "Coco"}, {"name": "Mark Pellegrino", "character": "Joe"}]', 'David Lynch', NULL, '2026-07-13 21:31:37.703971');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (367, 'tt21626284', 1163194, 'Lost Ladies', 2023, '/yXt07MYeiyQRzS69PMHy0BPjCGP.jpg', '{35,18,10749}', 'In 2001, somewhere in rural India, two young brides get accidentally swapped on a train. In the ensuing chaos, they both encounter a host of colourful characters, resulting in hilarious and unexpected consequences.', '[{"name": "Nitanshi Goel", "character": "Phool"}, {"name": "Pratibha Ranta", "character": "Jaya"}, {"name": "Sparsh Shrivastava", "character": "Deepak Kumar"}, {"name": "Ravi Kishan", "character": "Sub-Inspector Shyam Manohar"}, {"name": "Chhaya Kadam", "character": "Manju Maai"}]', 'Kiran Rao', NULL, '2026-07-13 21:31:38.830585');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (368, 'tt0107688', 9479, 'The Nightmare Before Christmas', 1993, '/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', '{14,16,10751}', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', '[{"name": "Danny Elfman", "character": "Jack Skellington (singing) / Barrel / Clown with the Tear away Face (voice)"}, {"name": "Chris Sarandon", "character": "Jack Skellington (voice)"}, {"name": "Catherine O''Hara", "character": "Sally / Shock (voice)"}, {"name": "William Hickey", "character": "Dr. Finkelstein (voice)"}, {"name": "Glenn Shadix", "character": "Mayor (voice)"}]', 'Henry Selick', NULL, '2026-07-13 21:31:39.389768');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (369, 'tt0276919', 553, 'Dogville', 2003, '/lraVawavIXh5geMlVjpzCw9TGwR.jpg', '{80,18,53}', 'A woman on the run from the mob is reluctantly accepted in a small Colorado community in exchange for labor, but when a search visits the town, she learns that their support has a price.', '[{"name": "Nicole Kidman", "character": "Grace Margaret Mulligan"}, {"name": "Paul Bettany", "character": "Tom Edison"}, {"name": "John Hurt", "character": "Narrator (voice)"}, {"name": "Stellan Skarsgård", "character": "Chuck"}, {"name": "Philip Baker Hall", "character": "Tom Edison Sr."}]', 'Lars von Trier', NULL, '2026-07-13 21:31:40.050742');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (371, 'tt7060344', 412862, 'Ratsasan', 2018, '/mruUFlrVKiL994y3vvQBT8R2Vnf.jpg', '{53,80,9648}', 'A serial killer is murdering school girls, and a newbie cop has to track him down before the victim count increases.', '[{"name": "Vishnu Vishal", "character": "SI Arun Kumar"}, {"name": "Amala Paul", "character": "Vijayalakshmi \"Viji\""}, {"name": "Suzane George", "character": "ACP Lakshmi"}, {"name": "Munishkanth", "character": "Doss"}, {"name": "Kaali Venkat", "character": "Venkat"}]', 'Ram Kumar', NULL, '2026-07-13 21:31:41.292781');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (374, 'tt8239946', 538858, 'Tumbbad', 2018, '/vzjZAKozbDplHWcQXbXo0APKxst.jpg', '{14,27}', 'India, 1918. On the outskirts of Tumbbad, a cursed village where it always rains, Vinayak, along with his mother and his brother, care of a mysterious old woman who keeps the secret of an ancestral treasure that Vinayak gets obsessed with.', '[{"name": "Sohum Shah", "character": "Vinayak Rao"}, {"name": "Mohammad Samad", "character": "Pandurang / Grandmother"}, {"name": "Harsh K.", "character": "Hastar"}, {"name": "Jyoti Malshe", "character": "Vinayak''s Mother"}, {"name": "Dhundiraj Prabhakar Jogalekar", "character": "Young Vinayak"}]', 'Rahi Anil Barve', NULL, '2026-07-13 21:31:43.006963');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (375, 'tt1065073', 85350, 'Boyhood', 2014, '/2BvtvDUyxiMJ4dmKfiQf4qdOHQN.jpg', '{18}', 'The film tells a story of a divorced couple trying to raise their young son. The story follows the boy for twelve years, from first grade at age 6 through 12th grade at age 17-18, and examines his relationship with his parents as he grows.', '[{"name": "Ellar Coltrane", "character": "Mason"}, {"name": "Patricia Arquette", "character": "Mom"}, {"name": "Ethan Hawke", "character": "Dad"}, {"name": "Lorelei Linklater", "character": "Samantha"}, {"name": "Libby Villari", "character": "Grandma"}]', 'Richard Linklater', NULL, '2026-07-13 21:31:43.62009');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (377, 'tt7653254', 492188, 'Marriage Story', 2019, '/2JRyCKaRKyJAVpsIHeLvPw5nHmw.jpg', '{18}', 'A stage director and an actress struggle through a grueling, coast-to-coast divorce that pushes them to their personal extremes.', '[{"name": "Adam Driver", "character": "Charlie Barber"}, {"name": "Scarlett Johansson", "character": "Nicole Barber"}, {"name": "Laura Dern", "character": "Nora Fanshaw"}, {"name": "Alan Alda", "character": "Bert Spitz"}, {"name": "Ray Liotta", "character": "Jay Marotta"}]', 'Noah Baumbach', NULL, '2026-07-13 21:31:44.76102');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (378, 'tt3417422', 244049, 'Drishyam', 2013, '/7d8GLneJkF81q1POdK7VUrjWafX.jpg', '{53,80,18}', 'Georgekutty lives a happy life with his wife and daughters. Things take a turn when his daughter gets indecently filmed using a hidden camera, by the son of a police inspector.', '[{"name": "Mohanlal", "character": "Georgekutty"}, {"name": "Meena", "character": "Rani"}, {"name": "Asha Sarath", "character": "IG Geetha Prabhakar"}, {"name": "Kalabhavan Shajon", "character": "Constable Sahadevan"}, {"name": "Ansiba Hassan", "character": "Anju"}]', 'Jeethu Joseph', NULL, '2026-07-13 21:31:45.322411');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (379, 'tt0472043', 1579, 'Apocalypto', 2006, '/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg', '{28,18,36}', 'Set in the Mayan civilization, when a man''s idyllic presence is brutally disrupted by a violent invading force, he is taken on a perilous journey to a world ruled by fear and oppression where a harrowing end awaits him. Through a twist of fate and spurred by the power of his love for his woman and his family he will make a desperate break to return home and to ultimately save his way of life.', '[{"name": "Rudy Youngblood", "character": "Jaguar Paw"}, {"name": "Raoul Max Trujillo", "character": "Zero Wolf"}, {"name": "Gerardo Taracena", "character": "Middle Eye"}, {"name": "Iazua Larios", "character": "Sky Flower"}, {"name": "Antonio Monroy", "character": "Chilam"}]', 'Mel Gibson', NULL, '2026-07-13 21:31:46.1129');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (382, 'tt2631186', 256040, 'Bāhubali: The Beginning', 2015, '/9BAjt8nSSms62uOVYn1t3C3dVto.jpg', '{28,18}', 'The young Shivudu is left as a foundling in a small village by his mother. By the time he’s grown up, it has become apparent that he possesses exceptional gifts. He meets the beautiful warrior princess Avanthika and learns that her queen has been held captive for the last 25 years. Shividu sets off to rescue her, discovering his own origins in the process.', '[{"name": "Prabhas", "character": "Mahendra \"Sivudu\" Bāhubali / Amarendra Bāhubali"}, {"name": "Rana Daggubati", "character": "Bhallaladeva"}, {"name": "Tamannaah Bhatia", "character": "Avanthika"}, {"name": "Anushka Shetty", "character": "Devasena"}, {"name": "Ramya Krishnan", "character": "Sivagami"}]', 'S. S. Rajamouli', NULL, '2026-07-13 21:31:47.824637');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (383, 'tt1125849', 12163, 'The Wrestler', 2008, '/6OTR8dSoNGjWohJNo3UhIGd3Tj.jpg', '{18,10749}', 'Aging wrestler Randy "The Ram" Robinson is long past his prime but still ready and rarin'' to go on the pro-wrestling circuit. After a particularly brutal beating, however, Randy hangs up his tights, pursues a serious relationship with a long-in-the-tooth stripper, and tries to reconnect with his estranged daughter. But he can''t resist the lure of the ring and readies himself for a comeback.', '[{"name": "Mickey Rourke", "character": "Randy"}, {"name": "Marisa Tomei", "character": "Cassidy"}, {"name": "Evan Rachel Wood", "character": "Stephanie"}, {"name": "Mark Margolis", "character": "Lenny"}, {"name": "Todd Barry", "character": "Wayne"}]', 'Darren Aronofsky', NULL, '2026-07-13 21:31:48.392574');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (384, 'tt0181875', 786, 'Almost Famous', 2000, '/3rrkyLYbgLj84AYvjhdcJot4JPx.jpg', '{18,10402}', 'In 1973, a precocious 15-year-old aspiring rock journalist lands a dream assignment from Rolling Stone to tour with a rising rock band, embarking on a coming-of-age journey as he discovers the exhilarating and heartbreaking realities behind rock stardom.', '[{"name": "Billy Crudup", "character": "Russell Hammond"}, {"name": "Frances McDormand", "character": "Elaine Miller"}, {"name": "Kate Hudson", "character": "Penny Lane"}, {"name": "Jason Lee", "character": "Jeff Bebe"}, {"name": "Patrick Fugit", "character": "William Miller"}]', 'Cameron Crowe', NULL, '2026-07-13 21:31:49.059592');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (385, 'tt0118749', 4995, 'Boogie Nights', 1997, '/wnE24UPCPQsQnbBOu4zVE2qaDNm.jpg', '{18,35}', 'In 1977, an idealistic porn producer and his promising protege try to catch up with the end of an era before their never-ending party collides with cold, hard reality.', '[{"name": "Mark Wahlberg", "character": "Eddie Adams / Dirk Diggler"}, {"name": "Burt Reynolds", "character": "Jack Horner"}, {"name": "Julianne Moore", "character": "Amber Waves"}, {"name": "John C. Reilly", "character": "Reed Rothchild"}, {"name": "Heather Graham", "character": "Rollergirl"}]', 'Paul Thomas Anderson', NULL, '2026-07-13 21:31:49.615265');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (386, 'tt0432283', 10315, 'Fantastic Mr. Fox', 2009, '/euZyZb6iGreujYKrGyZHRddhUYh.jpg', '{12,16,35,10751}', 'The Fantastic Mr. Fox, bored with his current life, plans a heist against the three local farmers. The farmers, tired of sharing their chickens with the sly fox, seek revenge against him and his family.', '[{"name": "George Clooney", "character": "Mr. Fox (voice)"}, {"name": "Meryl Streep", "character": "Felicity Fox (voice)"}, {"name": "Jason Schwartzman", "character": "Ash Fox (voice)"}, {"name": "Eric Chase Anderson", "character": "Kristofferson Silverfox (voice)"}, {"name": "Wallace Wolodarsky", "character": "Kylie (voice)"}]', 'Wes Anderson', NULL, '2026-07-13 21:31:50.215367');
